    const t = new THREE.CylinderGeometry(0.07, 0.13, 1.5, 6); t.translate(0, 0.75, 0); trunk.push(paint(t, [1, 1, 1]));
    for (let i = 0; i < 3; i++) { const b = new THREE.CylinderGeometry(0.02, 0.05, 0.7, 5); b.translate(0, 0.35, 0); b.rotateZ(0.8); b.rotateY(i * 2.1); b.translate(0, 1.0, 0); trunk.push(paint(b, [1, 1, 1])); }
    const cm = mergeGeometries(crown); cm.deleteAttribute('normal');
    const smoothCrown = mergeVertices(cm, 1e-3); smoothCrown.computeVertexNormals(); // (welded: the lumps shade smoothly instead of in flat facets)
    return { crown: smoothCrown, trunk: mergeGeometries(trunk) };
