    this._bed({ x0: POND.x - POND.rx * 1.6, x1: POND.x + POND.rx * 1.6, z0: POND.z - POND.rz * 1.6, z1: POND.z + POND.rz * 1.6, inside: (x, z) => { const q = PQ(x, z); return q > 1.36 && q < 1.52 && Math.hypot(x - PL.x, z - PL.z) > 64; }, pal: 'blue', types: ['spike', 'cup', 'flat'], weights: [3, 2, 2], hMin: 16, hMax: 30, seed: 7, parent: 'pool', gap: 9 });

