import * as THREE from 'three';
import { SUN_DEFAULT } from './atmosphere.js';
import { sseg, clamp } from '../core/ease.js';

// The sun's (and the moon's) path, in the house's frame, for the interactive
// modes. +x is east (the right wall), -x west (the left), -z south (the far
// end, the fountain), +z north. A direction is given by its azimuth φ, the way
// round from +z toward +x of where the light comes from, and its elevation:
//   T = (cos el · sin φ, sin el, cos el · cos φ)   (unit, toward the light)
// By day the sun rises in the east, climbs to the south at noon and sets in the
// west; golden hour (the old fixed sun, from the south-west at about 41°) is
// pinned at 14.5 h exactly, so the look the garden had is the look it keeps there.
// The hour axis (the mood, tod) is not a clock: the sun's place comes from a
// solar hour h, which follows the mood along the afternoon (tod 1 noon, 0.86
// golden hour, 0.56 sunset), or the viewer's clock (My clock), or runs the
// morning branch (the finale's sunrise). By night the light is the moon, higher
// the deeper the night; the key light swings from one to the other as the sun
// goes down (tod 0.56 → 0.36), while it is dim.

const D2R = Math.PI / 180;
const T0 = SUN_DEFAULT.clone().negate();
const PHI0 = Math.atan2(T0.x, T0.z) / D2R; // (about -150°)
const EL0 = Math.asin(T0.y) / D2R; // (about 41°)

// [hour, φ (unwrapped, increasing through the day), elevation]
const SUN = [
  [5.4, 96, -6], [6.6, 100, 5], [8.0, 118, 22], [10.0, 150, 42], [12.5, 180, 56],
  [14.5, PHI0 + 360, EL0], [16.5, 235, 22], [18.2, 260, 5], [19.2, 264, -6],
];
// the mood to a solar hour: the afternoon (the slider), and the morning (the finale's sunrise)
const EVENING = [[0.56, 18.2], [0.7, 16.5], [0.86, 14.5], [1, 12.5]];
const MORNING = [[0.5, 6.6], [0.62, 8.0], [0.74, 10.5], [0.86, 14.5], [1, 12.5]];

const lerpKnots = (k, x, i0 = 0) => {
  if (x <= k[0][0]) return k[0].slice(1);
  for (let i = 0; i < k.length - 1; i++) {
    if (x <= k[i + 1][0]) {
      const u = (x - k[i][0]) / (k[i + 1][0] - k[i][0]);
      return k[i].slice(1).map((v, j) => v + (k[i + 1][j + 1] - v) * u);
    }
  }
  return k[k.length - 1].slice(1);
};

// the solar hour for a mood value (afternoon by default)
export function hourOfTod(d, morning = false) {
  return lerpKnots(morning ? MORNING : EVENING, d)[0];
}

// the viewer's clock as a solar hour
export function hourOfClock(date = new Date()) {
  return date.getHours() + date.getMinutes() / 60 + date.getSeconds() / 3600;
}

const wrap = (a) => ((((a + 180) % 360) + 360) % 360) - 180;

// the key light's direction toward the light, for a mood d and a solar hour h
export function keyDirection(d, h, out = new THREE.Vector3()) {
  const [phiS, elS] = lerpKnots(SUN, clamp(h, SUN[0][0], SUN[SUN.length - 1][0]));
  const k = clamp(d / 0.27);
  const phiM = 15 + 35 * k, elM = 52 - 28 * k; // the moon: higher the deeper the night
  const w = sseg(d, 0.36, 0.56); // 0 the moon … 1 the sun
  const phi = phiM + wrap(phiS - phiM) * w;
  const el = elM + (elS - elM) * w;
  const e = el * D2R, p = phi * D2R;
  return out.set(Math.cos(e) * Math.sin(p), Math.sin(e), Math.cos(e) * Math.cos(p));
}

export const azimuth = (T) => Math.atan2(T.x, T.z);
export const elevation = (T) => Math.asin(clamp(T.y, -1, 1)) / D2R;
