import * as THREE from 'three';
import './core/fastmatrix.js';
import { detectQuality } from './core/quality.js';
import { createMaterials } from './materials/library.js';
import { bedTexture, stoneTexture, noiseTexture } from './materials/textures.js';
import { createEnvironments, setEnvPhoto, envPhoto, rebakeEnvironments } from './world/environment.js';
import { startScans, scansReady, scanImage, scansLive, scansTick } from './materials/scans.js';
import { SCANS } from './materials/scanlist.js';
import { buildWorld } from './world/world.js';
import { Creatures } from './creatures/manager.js';
import { createShots } from './direction/shots.js';
import { Director } from './direction/director.js';
import { Pipeline } from './render/pipeline.js';
import { DURATION, B } from './direction/beats.js';
import { Controls } from './ui/controls.js';
import { Score, renderScore, bufferToWav } from './audio/score.js';
import { clamp, sseg } from './core/ease.js';
import { Explore } from './explore/explore.js';
import { save } from './explore/save.js';
import { todFromClock, hourName } from './explore/timeofday.js';
import { NearField } from './explore/nearfield.js';
import { Input } from './input/input.js';
import { Hud } from './ui/hud.js';
import { showLanding } from './ui/landing.js';
import { LiveAudio } from './audio/live.js';
import { WIND } from './world/wind.js';
import { Governor } from './render/governor.js';
import { singlePassFlatGlass } from './render/singlepass.js';
import { PerfMeter } from './ui/perfmeter.js';

// The Clockwork Garden – entry point.
//   ?t=12.5     start at a timestamp        ?paused=1   start paused
//   ?clean=1    recording mode (no UI)      ?quality=low|med|high
//   ?motion=reduced  gentle-motion version  ?capture=1  frame-capture API only
//   ?mode=film|fly|follow   open a mode directly (otherwise a landing screen asks)
//   ?tod=0..1   time of day in the interactive modes (0 midnight, 0.5 dawn, 1 golden hour)
//   ?tod=live   the hour follows your own clock (also in the menu: My clock)
//   ?rain=1     start in the rain (the menu's Rain, or R, brings and clears it)
//   ?garden=fresh  ignore the saved garden (the beds you grew are remembered between visits)
//   ?touch=1|0  force the touch interface on or off
//   ?debug=1    frame-rate readout (fps, frame times, resolution, GPU/CPU ms)
//   ?adapt=0    hold the resolution and detail fixed (no frame governor)
//   ?bake=0     grow the bee-scale planting here instead of loading the pre-built one
//   ?scans=0    the procedural surfaces and sky only (no photographed scans)

const params = new URLSearchParams(location.search);
if (params.get('bake') === '0') NearField.noBake = true;
const quality = detectQuality(params);
// the photographed surfaces and sky download while the garden is built
startScans(quality);
const clean = params.get('clean') === '1';
const capture = params.get('capture') === '1';
if (capture || params.get('garden') === 'fresh') save.off();
const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
let reduced = params.get('motion') === 'reduced' || (params.get('motion') !== 'full' && prefersReduced);

const canvas = document.getElementById('film');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: false, powerPreference: 'high-performance', preserveDrawingBuffer: capture, stencil: false });
renderer.setPixelRatio(quality.pixelRatio);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFShadowMap; // (r185 draws PCFSoftShadowMap as PCFShadowMap and warns about it)
renderer.toneMapping = THREE.NoToneMapping; // tone mapping happens in the grade pass
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.setClearColor('#000000');

function size() {
  const w = window.innerWidth, h = window.innerHeight;
  renderer.setSize(w, h, false);
  canvas.style.width = w + 'px';
  canvas.style.height = h + 'px';
  return renderer.getDrawingBufferSize(new THREE.Vector2());
}

// issue every material's program for the scene as it stands now (after `prep`
// sets its state), compiled for the scene pass's render target; resolves when
// they are ready (or after a cap, so a slow driver never holds the page)
// (without KHR_parallel_shader_compile the programs are still all issued
// before the first one is waited on, so the driver can work through them)
async function compileAll(renderer, scene, camera, pipeline, prep) {
  prep?.();
  const rt = renderer.getRenderTarget();
  renderer.setRenderTarget(pipeline.scenePass.rtA);
  let p = null;
  if (renderer.extensions.has('KHR_parallel_shader_compile')) p = renderer.compileAsync(scene, camera).catch(() => {});
  else renderer.compile(scene, camera);
  renderer.setRenderTarget(rt);
  if (p) await Promise.race([p, new Promise((r) => setTimeout(r, 12000))]);
}

async function boot() {
  const status = document.getElementById('loading');
  const STEP_TEXT = { materials: 'casting the brass…', light: 'kindling the lanterns…', garden: 'planting the beds…', creatures: 'waking the creatures…', 'garden life': 'oiling the gears…', compile: 'winding the escapement…' };
  const step = async (msg) => {
    if (status) {
      status.dataset.step = msg;
      const line = status.querySelector('.msg');
      if (line && STEP_TEXT[msg]) line.textContent = STEP_TEXT[msg];
    }
    await new Promise((r) => setTimeout(r, 0));
  };
  size();
  await step('materials');
  const mat = createMaterials(quality);
  const tex = {
    bed: bedTexture(21, quality.tier === 'low' ? 512 : 1024),
    stone: stoneTexture(31, 512),
    moss: noiseTexture(51, 256, { cells: 6, octaves: 4, lo: 0.7, hi: 1.3, tint: [190, 210, 170] }),
  };
  await step('light');
  // the photographed sky, if it has arrived (it is small); otherwise the
  // maps are baked again when it does
  const sky = await Promise.race([scanImage('sky'), new Promise((r) => setTimeout(() => r(null), capture ? 20000 : 500))]);
  if (sky) setEnvPhoto(sky, SCANS.sky);
  const envs = createEnvironments(renderer);
  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#000000');
  await step('garden');
  const world = buildWorld(scene, mat, tex, quality);
  await step('creatures');
  world.creatures = new Creatures(world, mat, quality);
  scene.add(world.creatures.group);
  scene.updateMatrixWorld(true);
  const shots = createShots(world);
  const pipeline = new Pipeline(renderer, scene, quality);
  const director = new Director({ scene, world, shots, pipeline, envs, quality, reducedMotion: reduced });
  // look-dev: orbit a named object (?look=bee&yaw=0.6&pitch=0.3&dist=6&fov=30)
  if (params.get('look')) {
    const C = world.creatures;
    const targets = {
      escapement: () => world.escapement.group.position.clone().add(new THREE.Vector3(0, 0.6, 0)),
      crown: () => world.crown.group.localToWorld(new THREE.Vector3(0, 2, 0)),
      flower: () => world.flower.head.getWorldPosition(new THREE.Vector3()),
      stem: () => new THREE.Vector3(0, 16, 0),
      skep: () => world.skep.group.position.clone().add(new THREE.Vector3(0, 6, 0)),
      lily: () => world.lily.perchWorld(),
      reed: () => world.reed.surfacePoint(0.5, 0.6),
      blossom: () => world.blossom.mouthWorld(),
      tree: () => world.tree.perchWorld(),
      bee: () => C.hero.group.getWorldPosition(new THREE.Vector3()),
      monarch: () => C.monarch?.group.getWorldPosition(new THREE.Vector3()),
      beetle: () => C.beetle?.group.getWorldPosition(new THREE.Vector3()),
      ladybird: () => C.ladybird?.group.getWorldPosition(new THREE.Vector3()),
      hummingbird: () => C.hummingbird?.group.getWorldPosition(new THREE.Vector3()),
      songbird: () => C.songbird?.group.getWorldPosition(new THREE.Vector3()),
      dragonfly: () => C.dragonfly?.group.getWorldPosition(new THREE.Vector3()),
      origin: () => new THREE.Vector3(0, 20, 0),
    };
    const name = params.get('look');
    // ?look=bee&stage=landed|flight|walk: inspect the hero bee in a clear spot
    // above the bloom (inside the shot's light) in a chosen pose, facing +Z
    const stage = params.get('stage');
    if (stage && C?.hero) {
      const update = C.updateHero.bind(C);
      C.updateHero = (t, ctx) => {
        update(t, ctx);
        const g = C.hero.group;
        g.visible = true;
        g.position.copy(C.land).add(new THREE.Vector3(0, 4.5, 0));
        g.rotation.set(0, 0, 0);
        const poses = {
          landed: { t, flap: 0, grip: 1, fold: 0.7, pollen: 0.5 },
          folded: { t, flap: 0, grip: 1, fold: 1, pollen: 0 },
          flight: { t, flap: 1, grip: 0, fold: 0, pollen: 0 },
          walk: { t, flap: 0, grip: 1, fold: 1, walk: t * 3 },
          display: { t, flap: 0, grip: 1, fold: 0.1, pollen: 0 },
        };
        C.hero.setPose(poses[stage] || poses.landed);
      };
      // &key=1: a studio-style three-quarter key from the camera's side
      if (params.get('key') === '1') {
        const applyRig = director.applyRig.bind(director);
        director.applyRig = (shot, t, cam) => {
          applyRig(shot, t, cam);
          const c = C.hero.group.position;
          const f = cam.position.clone().sub(c).setY(0).normalize();
          const sd = new THREE.Vector3(-f.z, 0, f.x);
          world.lighting.focusShadow(c, 5);
          world.lighting.aimBeam(c, 4, f.multiplyScalar(0.7).addScaledVector(sd, 0.8).add(new THREE.Vector3(0, 1.0, 0)).normalize(), 4.0, '#ffe2bd', 1.2);
        };
      }
    }
    const yaw = parseFloat(params.get('yaw') || '0.6');
    const pitch = parseFloat(params.get('pitch') || '0.25');
    const dist = parseFloat(params.get('dist') || '8');
    const fov = parseFloat(params.get('fov') || '30');
    director.lookdev = (t) => {
      const c = targets[name]();
      const pos = c.clone().add(new THREE.Vector3(Math.sin(yaw) * Math.cos(pitch), Math.sin(pitch), Math.cos(yaw) * Math.cos(pitch)).multiplyScalar(dist));
      return { pos, target: c, fov, focus: dist, aperture: parseFloat(params.get('ap') || '0'), roll: 0 };
    };
  }

  let explore = null;
  const resize = () => {
    const s = size();
    pipeline.setSize(s.x, s.y);
    director.aspect = s.x / s.y;
    director.pixelRatio = renderer.getPixelRatio();
    if (explore) { explore.aspect = director.aspect; explore.pixelRatio = director.pixelRatio; }
  };
  resize();
  // keeps motion smooth: trades resolution (and in the interactive modes, a
  // little detail) for a steady frame rate (render/governor.js)
  const gov = new Governor({
    renderer,
    base: quality.pixelRatio,
    enabled: !capture && !clean && params.get('adapt') !== '0',
    onScale: (k) => { renderer.setPixelRatio(quality.pixelRatio * k); resize(); },
    onCpu: (level) => explore?.setPerfLevel(level),
  });
  window.addEventListener('resize', () => { resize(); gov.settle(performance.now()); });

  // flat glass and wings draw single-pass (identical pixels, half the draws: render/singlepass.js)
  singlePassFlatGlass(scene);
  // warm up: compile every shader by rendering representative frames.
  // (Kept at boot even when the page opens on the garden: drawing everything
  // through every pass once also readies the driver's pipeline states; without
  // it the first half-minute of flying stalled for 100–600 ms at a time while
  // they were built on demand. Measured 2026-10-05.)
  // the photographed surfaces: those already here are uploaded by the
  // warm-up frames behind the loading screen; the page never waits for the
  // rest (they appear as they arrive), except a capture, which waits for all
  await scansReady(capture ? Infinity : 0);
  if (!envPhoto()) {
    scanImage('sky').then((img) => {
      if (!img || envPhoto()) return;
      setEnvPhoto(img, SCANS.sky);
      const done = [rebakeEnvironments(renderer, envs)];
      if (explore?.tod.maps) done.push(rebakeEnvironments(renderer, explore.tod.maps));
      // (the scene's map is set again each frame; free the old ones after)
      setTimeout(() => done.forEach((d) => d.free()), 1000);
    });
  }
  await step('compile');
  // first every shader the film draws, issued at once (the driver compiles
  // them in parallel where it can, instead of one at a time as each is first
  // drawn); the warm-up frames then only ready the pipeline states. (Compiled
  // for the scene pass's own target: that decides the output variant.)
  await compileAll(renderer, scene, director.camA, pipeline, () => director.render(0.5));
  for (const t of [0.5, 10, 16, 24, 30, 34, 38, 45]) director.render(t);
  // (what the warm-up frames didn't draw, compiled for the scene pass's
  // target too: compiled for the screen it would be a variant never used)
  compileAll(renderer, scene, director.camA, pipeline);

  const title = document.getElementById('title');
  const updateTitle = (t) => {
    const k = sseg(t, B.titleIn[0], B.titleIn[1]) * (1 - sseg(t, B.fadeOut[0], B.fadeOut[1] - 0.3));
    title.style.opacity = k.toFixed(3);
    title.style.setProperty('--rise', ((1 - k) * 10).toFixed(2) + 'px');
    title.style.letterSpacing = (0.32 + (1 - k) * 0.08).toFixed(3) + 'em';
  };

  // ---- interactive modes (built after the film, so the film's state is untouched) ----
  const touch = params.get('touch') === '1' || (params.get('touch') !== '0' && (window.matchMedia('(pointer: coarse)').matches || /Android|iPhone|iPad|Mobile/i.test(navigator.userAgent)));
  const audio = new LiveAudio();
  const makeExplore = () => {
    if (!explore) {
      explore = new Explore({ renderer, scene, world, pipeline, quality, mat, audio, sync: capture });
      singlePassFlatGlass(scene);
      explore.aspect = director.aspect;
      explore.pixelRatio = renderer.getPixelRatio();
      explore.reduced = reduced;
      explore.touch = touch;
      const todParam = params.get('tod');
      const tod = parseFloat(todParam);
      if (todParam === 'live') explore.setLive(true, { jump: true, persist: false });
      else if (Number.isFinite(tod)) explore.tod.value = clamp(tod, 0, 1);
      else if (save.get().live) explore.setLive(true, { jump: true });
      if (params.get('rain') === '1') explore.setRain(true, { jump: true });
      if (params.get('snow') === '1') explore.setSnow(true, { jump: true });
      if (params.get('fog') === '1') explore.setFog(true, { jump: true });
    }
    return explore;
  };
  if (!capture) {
    await step('garden life');
    makeExplore();
    // compile the interactive modes' shaders now at the opening hour; the
    // other end of the day compiles once the landing is up (loop below)
    const keep = explore.tod.value;
    explore.enter('follow');
    explore.update(1 / 60, null);
    explore.render(1 / 60);
    explore.tod.value = keep;
    explore.exit();
  }

  const state = { t: clamp(parseFloat(params.get('t') || '0') || 0, 0, DURATION), playing: !capture && params.get('paused') !== '1' };
  const score = new Score();
  const renderAt = (t) => {
    state.t = clamp(t, 0, DURATION);
    director.reducedMotion = reduced;
    director.render(state.t);
    updateTitle(state.t);
    controls?.sync(state);
  };

  // which mode to open in: ?mode=film|fly|follow; film-only parameters imply
  // the film; otherwise the landing screen asks
  const filmOnly = clean || capture || params.has('t') || params.has('look') || params.get('paused') === '1';
  let mode = ['film', 'fly', 'follow'].includes(params.get('mode')) ? params.get('mode') : filmOnly ? 'film' : null;
  if (capture) mode = 'film';
  let landing = null;

  let controls = null;
  let hud = null;
  let input = null;
  if (!clean && !capture) {
    controls = new Controls({
      onPlayPause: () => {
        if (state.t >= DURATION - 0.01) state.t = 0;
        state.playing = !state.playing;
        state.playing ? score.play(state.t) : score.pause();
      },
      onReplay: () => {
        state.t = 0;
        state.playing = true;
        score.play(0);
      },
      onSeek: (t) => {
        state.t = t;
        renderAt(t);
        if (state.playing) score.play(t);
      },
      onSound: async () => {
        const on = await score.toggle(state.t, state.playing);
        return on;
      },
      onMotion: () => {
        reduced = !reduced;
        if (explore) explore.reduced = reduced;
        hud?.setGentle(reduced);
        return reduced;
      },
      onMode: (m) => setMode(m),
      duration: DURATION,
      reduced: () => reduced,
    });
    input = new Input(canvas, { touch });
    hud = new Hud({
      onMode: (m) => setMode(m),
      onSwap: () => setMode(mode === 'fly' ? 'follow' : 'fly'),
      onTime: (v) => explore.setTime(v),
      onSound: async () => { const on = await audio.toggle(); return on; },
      onPhoto: () => togglePhoto(),
      onSave: () => savePhoto(),
      onGentle: () => { reduced = !reduced; explore.reduced = reduced; controls.motionBtn.setAttribute('aria-pressed', String(reduced)); return reduced; },
      onPanel: (open) => { if (open && input.locked) document.exitPointerLock?.(); },
      onLive: () => explore.setLive(!explore.live),
      onRain: () => explore.setRain(!explore.weather.on),
      onSnow: () => explore.setSnow(!explore.weather.snowOn),
      onFog: () => explore.setFog(!explore.weather.fogOn),
      onLights: () => explore.setLights(!explore.beeLights.on),
      onStamp: () => { const on = !save.get().stamp; save.set({ stamp: on }); hud.setStamp(on); },
      onReset: () => { save.resetProgress(); location.reload(); },
      onNudge: (yes) => {
        save.set({ nudgeDone: true });
        if (yes) audio.enable().then(() => hud.setSound(true));
      },
    });
    hud.setTime(explore.tod.value);
    hud.setGentle(reduced);
    hud.setLive(explore.live);
    hud.setRain(explore.weather.on);
    hud.setSnow(explore.weather.snowOn);
    hud.setFog(explore.weather.fogOn);
    hud.setLights(explore.beeLights.on);
    hud.setStamp(save.get().stamp);
    explore.on('time', (v) => hud.setTime(v));
    explore.on('live', (v) => hud.setLive(v));
    explore.on('lights', (v) => { hud.setLights(v); if (mode) hud.flashHint(v ? 'Navigation lights on' : 'Navigation lights off', 2.2); });
    explore.on('fog', (v) => { hud.setFog(v); if (mode) hud.flashHint(v ? (touch ? 'Fog rolls in: the menu clears it' : 'Fog rolls in: V clears it') : 'The fog lifts', 3.5); });
    explore.on('snow', (v) => { hud.setSnow(v); if (mode) hud.flashHint(v ? (touch ? 'Snow falls: the menu clears it' : 'Snow falls: N clears it') : 'The snow eases', 3.5); });
    explore.on('rain', (v) => { hud.setRain(v); if (mode) hud.flashHint(v ? (touch ? 'Rain on the glass: the menu clears it' : 'Rain on the glass: R clears it') : 'The rain eases', 3.5); });
    wireHints(explore, hud, () => mode, touch, audio);
    window.addEventListener('pagehide', () => save.flush());
    document.addEventListener('visibilitychange', () => { if (document.hidden) save.flush(); });
  }
  document.body.classList.toggle('clean', clean || capture);

  const setURL = (m) => {
    const u = new URL(location.href);
    u.searchParams.set('mode', m);
    history.replaceState(null, '', u);
  };
  const setMode = (m, { fromLanding = false } = {}) => {
    const prev = mode;
    if (m === prev && !fromLanding) return;
    mode = m;
    if (landing) { landing = null; }
    if (m === 'film') {
      explore?.exit();
      input?.enable(false);
      hud?.show(false);
      controls?.enable(true);
      audio.disable();
      document.body.classList.remove('explore', 'photo');
      state.t = 0;
      state.playing = true;
      score.play(0);
      renderAt(0);
    } else {
      if (prev === 'film' || prev === null) {
        state.playing = false;
        score.pause();
        controls?.enable(false);
        title.style.opacity = '0';
      }
      const fresh = prev === 'film' || (prev === null && !fromLanding);
      explore.enter(m);
      setTimeout(() => explore.compileAll(), 400);
      explore.setPerfLevel(gov.cpuLevel);
      if (m === 'fly' && (prev === 'film' || fromLanding)) explore.spawnAtSkep();
      if (fresh && m === 'fly') explore.spawnAtSkep();
      // the first flights: how to move, until the first bloom has been pollinated by hand
      if (m === 'fly' && !save.get().controlsSeen) {
        hud.flashHint(touch ? 'Left stick to fly · drag to look · ▲ ▼ to climb and descend' : 'W to fly · mouse to look · Space and Shift to climb and descend · H for help', 9);
      }
      input.enable(true);
      input.setMode(m);
      hud.show(true);
      hud.setMode(m, { touch });
      if (score.enabled && !audio.enabled) audio.enable().then(() => hud.setSound(true));
    }
    setURL(m);
    gov.settle(performance.now());
  };
  const togglePhoto = () => {
    if (!explore?.active) return;
    explore.togglePhoto();
    input.setMode(explore.photo ? 'photo' : mode);
    if (explore.photo) { hud.togglePanel(false); hud.toggleHelp(false); }
  };
  // the saved picture, with a small caption in the corner when the strip's Caption is on
  const photoURL = () => {
    if (!save.get().stamp) return canvas.toDataURL('image/png');
    const w = canvas.width, h = canvas.height, u = h / 1080;
    const c = document.createElement('canvas');
    c.width = w; c.height = h;
    const g = c.getContext('2d');
    g.drawImage(canvas, 0, 0);
    const shade = g.createLinearGradient(0, h * 0.86, 0, h);
    shade.addColorStop(0, 'rgba(3,10,12,0)');
    shade.addColorStop(1, 'rgba(3,10,12,0.5)');
    g.fillStyle = shade;
    g.fillRect(0, h * 0.86, w, h * 0.14);
    const x = Math.round(w * 0.03), y = h - Math.round(h * 0.045);
    const grown = explore.growth.grownCount, total = explore.growth.sites.length;
    g.textBaseline = 'alphabetic';
    g.shadowColor = 'rgba(0,0,0,0.7)';
    g.shadowBlur = 8 * u;
    g.fillStyle = '#f2e9d6';
    g.font = `500 ${Math.round(27 * u)}px "Cormorant Garamond", Georgia, serif`;
    if ('letterSpacing' in g) g.letterSpacing = `${(7 * u).toFixed(1)}px`;
    g.fillText('THE CLOCKWORK GARDEN', x, y - Math.round(26 * u));
    if ('letterSpacing' in g) g.letterSpacing = '0px';
    g.fillStyle = 'rgba(217,181,106,0.95)';
    g.fillRect(x, y - Math.round(18 * u), Math.round(150 * u), Math.max(1, Math.round(1.4 * u)));
    g.fillStyle = '#e9dfc9';
    g.font = `italic 500 ${Math.round(23 * u)}px "Cormorant Garamond", Georgia, serif`;
    g.fillText(`${hourName(explore.tod.value)} · ${grown === total ? 'every bed in bloom' : `${grown} of ${total} beds grown`} · jez237.com`, x, y + Math.round(8 * u));
    return c.toDataURL('image/png');
  };
  const savePhoto = () => {
    if (!explore?.photo) return;
    explore.render(0);
    const url = photoURL();
    const a = document.createElement('a');
    a.href = url;
    a.download = `clockwork-garden-${new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19)}.png`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    audio.shutter();
    hud.flash();
    hud.flashHint('Saved a photograph', 2);
  };
  const handleActions = (acts) => {
    for (const a of acts) {
      if (a === 'help') hud.toggleHelp();
      else if (a === 'menu') hud.togglePanel();
      else if (a === 'sound') audio.toggle().then((on) => hud.setSound(on));
      else if (a === 'photo') togglePhoto();
      else if (a === 'swap' && !explore.photo) setMode(mode === 'fly' ? 'follow' : 'fly');
      else if (a === 'timeCycle') explore.cycleTime();
      else if (a === 'rain') explore.setRain(!explore.weather.on);
      else if (a === 'snow') explore.setSnow(!explore.weather.snowOn);
      else if (a === 'fog') explore.setFog(!explore.weather.fogOn);
      else if (a === 'lights') explore.setLights(!explore.beeLights.on);
      else if (a === 'timeUp') explore.setTime(explore.tod.value + 0.05);
      else if (a === 'timeDown') explore.setTime(explore.tod.value - 0.05);
      else if (a === 'save') savePhoto();
      else if (a === 'escape') { if (explore.photo) togglePhoto(); else if (hud.overlayOpen) { hud.togglePanel(false); hud.toggleHelp(false); } }
    }
  };
  // touch: tapping closes the help card
  window.addEventListener('pointerdown', (e) => { if (hud && !hud.help.hidden && !e.target.closest('.hud-help, .hud-panel, button')) hud.toggleHelp(false); });

  // public API for review and frame capture
  window.__cg = {
    duration: DURATION,
    renderAt: (t) => { renderAt(t); return true; },
    seek: (t) => renderAt(t),
    play: () => { state.playing = true; },
    pause: () => { state.playing = false; },
    state,
    shot: () => director.current,
    info: () => renderer.info,
    world: capture ? world : undefined, // debugging aid in capture mode only
    scene: capture ? scene : undefined, // (likewise)
    skyPhoto: () => !!envPhoto(),
    wind: WIND, // the breeze (review tools set wind.freeze for the rest pose)
    governor: gov,
    mode: () => mode,
    setMode: (m) => setMode(m),
    save: () => save.get(),
    photoURL: () => photoURL(),
    // review hooks for the interactive modes (state, scripted input, stills)
    explore: () => makeExplore(),
    exploreView: (v) => {
      const ex = makeExplore();
      ex.enter('fly');
      if (v.tod !== undefined) ex.tod.value = v.tod;
      if (v.clock !== undefined) ex.clock = v.clock;
      ex.debugView = v.pos ? { pos: new THREE.Vector3(...v.pos), target: new THREE.Vector3(...v.target), fov: v.fov, aperture: v.aperture, shadowRadius: v.shadowRadius } : null;
      // reachable: move the viewpoint out of solids, as the flight camera would be
      if (ex.debugView && v.reachable) { const p = ex.debugView.pos, d = ex.debugView.target.clone().sub(p); ex.bounds.pushOut(p, 2.5); ex.debugView.target.copy(p).add(d); }
      ex.update(v.dt ?? 0, null);
      ex.render(v.dt ?? 0);
      return true;
    },
    exploreExit: () => { explore?.exit(); return true; },
    // render the procedural score offline and return it as base64 WAV
    audioWav: async () => {
      const buf = await renderScore();
      const blob = bufferToWav(buf);
      const bytes = new Uint8Array(await blob.arrayBuffer());
      let s = '';
      for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
      return btoa(s);
    },
  };

  status?.remove();
  document.body.classList.add('ready');
  if (mode === 'film' || capture) {
    controls?.enable(true);
    // respect the system preference: wait for the viewer to start
    if (!capture && prefersReduced && params.get('motion') !== 'full') { state.playing = false; controls?.showGentleNotice(); }
    renderAt(state.t);
  } else if (mode) {
    const m = mode;
    mode = null;
    setMode(m);
  } else {
    // landing: the garden is alive behind the title; APX-9 is at work
    controls?.enable(false);
    explore.enter('follow');
    hud.show(false);
    landing = showLanding({ reducedMotion: reduced, touch, onChoose: (m) => setMode(m, { fromLanding: true }) });
  }
  if (capture) return;
  // the interactive modes' light-field shaders, compiled in the background
  setTimeout(() => explore?.compileAll(), 400);

  let last = performance.now();
  let partsDone = false;
  const readyAt = performance.now();
  // unseen renders once the landing is up, a few frames apart (each is
  // overwritten by the real frame): the other end of the day's shaders, and
  // the promenade and the blooms at night (the wet path, the arches, the
  // globes, the glowing petals), so they are ready before the first flight
  // without holding up the page
  const warmQueue = explore ? [
    { tod: explore.tod.value > 0.45 ? 0.1 : 0.86 },
    { tod: 0, view: [[70, 24, -330], [70, 48, -570]] },
    { tod: 0, view: [[44, 46, -96], [14, 38, -128]] },
    // the pool: its mirror pass (the outdoors drawn clipped at the water's plane) and the birds' shaders
    { tod: 0.86, view: [[-200, 90, -300], [-650, 8, -330]] },
  ] : [];
  let warmAt = 1500;
  let plantingAt = null; // (when the bee-scale planting was ready, for the readout)
  const meter = params.get('debug') === '1' ? new PerfMeter(gov, () => {
    const planting = explore?.nearfield.ready ?? true;
    if (planting && plantingAt == null) plantingAt = performance.now();
    return { mode, planting, readyAt, plantingAt };
  }) : null;
  const loop = (now) => {
    requestAnimationFrame(loop);
    // on a fast display that can't be held at its full rate: every other refresh
    if (gov.skip(now)) return;
    // a photographed surface that arrived after the page was up (one a frame)
    scansTick();
    const interval = now - last;
    const dt = Math.min(0.1, interval / 1000);
    last = now;
    // the interactive modes' bee-scale planting grows in the frame's spare
    // time until done (more behind the landing screen, a little during the film)
    if (explore && !explore.nearfield.ready) {
      const spare = gov.spare();
      const ms = landing ? clamp(spare, 4, 12) : mode === 'film' ? clamp(spare, 1, 2.5) : clamp(spare, 2, 10);
      explore.nearfield.step(ms);
    } else if (explore && !partsDone) partsDone = explore.nearfield.prepareParts(clamp(gov.spare() * 0.5, 0.5, 3));
    const workStart = performance.now();
    gov.begin();
    if (mode === 'film') {
      if (state.playing) {
        state.t += dt;
        if (state.t >= DURATION) {
          state.t = DURATION;
          state.playing = false;
          score.pause();
          controls?.ended();
        }
        renderAt(state.t);
      } else if (controls?.dirty) {
        controls.dirty = false;
        renderAt(state.t);
      }
    } else if (explore) {
      // the other end of the day's shaders, compiled once things are showing (an
      // unseen render, overwritten by the real frame below)
      if (warmQueue.length && now - readyAt > warmAt && explore.active) {
        const w = warmQueue.shift();
        warmAt += 300;
        const v = explore.tod.value, tg = explore.tod.target, dv = explore.debugView;
        explore.tod.value = w.tod;
        if (w.view) { const V3 = explore.actor.pos.constructor; explore.debugView = { pos: new V3(...w.view[0]), target: new V3(...w.view[1]), fov: 55, aperture: 1.5 }; }
        explore.render(0);
        explore.debugView = dv;
        explore.tod.value = v;
        explore.tod.target = tg;
        gov.settle(now, 800);
      }
      const inp = input && input.enabled ? input.frame(dt) : null;
      if (inp) handleActions(inp.actions);
      explore.update(dt, hud?.overlayOpen && inp ? { ...inp, move: { x: 0, y: 0 }, lift: 0, look: { dx: 0, dy: 0 }, boost: false } : inp);
      explore.render(dt);
      hud?.update(explore.hudState());
    }
    gov.end();
    gov.cpuOn = mode !== 'film' && !!explore?.active;
    gov.frame(now, interval, performance.now() - workStart);
    meter?.update(now);
  };
  scansLive(renderer);
  requestAnimationFrame(loop);
}

// standing hints and one-off messages for the interactive modes
function wireHints(explore, hud, getMode, touch, audio) {
  let firstLantern = true, firstBell = true;
  let nudged = save.get().nudgeDone;
  const say = (t, s) => hud.flashHint(t, s);
  // after the first pollination (by hand or by APX-9), once the viewer is actually in the garden: offer the sound
  const maybeNudge = () => {
    if (nudged || audio.enabled || !getMode() || getMode() === 'film') return;
    nudged = true;
    setTimeout(() => { if (!audio.enabled) hud.showNudge(); }, 2200);
  };
  explore.on('pollinate', ({ landable, first, who }) => {
    maybeNudge();
    if (who !== 'player') return;
    // (flying by hand and landing on a bloom: the controls card has done its work)
    if (!save.get().controlsSeen) save.set({ controlsSeen: true });
    if (landable.kind === 'pad' || landable.kind === 'perch') { say(`Perched on ${landable.name}: ${landable.kind === 'pad' ? 'the water is still beneath you' : 'the garden spreads out below'}`, 3); return; }
    say(first ? `You pollinated ${landable.name}: it answers` : `${landable.name[0].toUpperCase() + landable.name.slice(1)}: more pollen`, 3);
  });
  explore.on('deposit', ({ site, who, honey }) => {
    maybeNudge();
    const whoS = who === 'player' ? 'Pollen delivered' : 'APX-9 delivers its pollen';
    say(site ? `${whoS}: glass blooms are sprouting ${site.name}` : `${whoS} (${honey})`, 5);
  });
  explore.on('wind', ({ source }) => {
    if (source === 'finale') return;
    say(source === 'player' ? 'You wound the garden: watch the bloom wave' : 'APX-9 winds the garden', 5);
  });
  explore.on('finale', (e) => {
    if (e.phase === 'wave') say('Every bed is growing: the whole house answers', 6);
    if (e.phase === 'banner') {
      const parts = ['Twelve beds in bloom'];
      if (e.deposits > 0) parts.push(`${e.deposits} ${e.deposits === 1 ? 'delivery' : 'deliveries'} to the skep`);
      if (e.pollinated > 0) parts.push(`${e.pollinated} ${e.pollinated === 1 ? 'bloom' : 'blooms'} pollinated`);
      hud.showFinale({ title: 'The garden is awake', line: parts.join(' · ') });
    }
  });
  explore.on('kindle', () => { if (firstLantern && getMode() === 'fly') { firstLantern = false; say('Lanterns kindle as you pass', 3); } });
  explore.on('bell', () => { if (firstBell && getMode() === 'fly') { firstBell = false; say('The porcelain bells are tuned to the garden', 3); } });
  explore.on('hint', (t) => say(t, 3.5));
  explore.on('photo', (on) => { if (on) say(touch ? 'Photo mode: drag to look, joystick to move' : 'Photo mode: drag or WASD to frame, wheel to zoom, Enter to save', 4); });
}

boot().catch((e) => {
  console.error(e?.stack || e);
  const el = document.getElementById('loading');
  if (el) el.textContent = 'The garden could not wake: ' + e.message;
});
