import * as THREE from 'three';
import { RNG } from '../core/rng.js';
import { sseg } from '../core/ease.js';
import { SUN_DIR } from '../world/atmosphere.js';
import { OUT, POND } from './scenery.js';

// Birds in the sky beyond the glass (interactive modes; the film keeps its empty sky).
//
// Every flight is an analytic path evaluated in the vertex shader from the explore clock, so a flock costs one
// draw call and nothing on the CPU; the heading is the path's own direction (the position a moment ahead) and the
// banking is how fast that heading turns. The wings beat about the body, the tips lagging the roots.
//
//  · geese cross the sky in V formations, high up (a flock every minute or so, one soon after you arrive), gliding now
//    and then, from first light on; they stay home in rain;
//  · swallows dart in loose streams over the lawns and skim the pond, by day;
//  · starlings (a murmuration) swirl above the roof at dusk, at dawn and in the evening gold: one cloud that
//    stretches, folds and turns, with a wave of density running through it.
// They are dark against the sky and catch the low sun on the wing's edge and through the wing when it stands behind
// them; the land's haze thins them with distance. (They are reflected in the pond like the rest of the outdoors.)

const TAU = Math.PI * 2;

// a bird of span 1: z is forward, x the wings, y up; flat-shaded triangles (drawn double-sided)
function birdGeometry({ neck = 0.12, tail = 0.26, fork = 0.0, lead = 1, chord = 1, body = 0.045 }) {
  const P = [];
  const tri = (a, b, c) => P.push(...a, ...b, ...c);
  // the body: a four-sided tube through a few sections
  const sections = [
    [0.1 + neck, 0.0], [0.07 + neck * 0.55, body * 0.5], [0.09, body * 0.72], [0.0, body], [-0.1, body * 0.7], [-0.15, body * 0.3],
  ];
  const ring = (z, r) => [[-r, 0, z], [0, r * 0.8, z], [r, 0, z], [0, -r * 0.7, z]];
  for (let i = 0; i < sections.length - 1; i++) {
    const A = ring(sections[i][0], sections[i][1]), B = ring(sections[i + 1][0], sections[i + 1][1]);
    for (let k = 0; k < 4; k++) { const k2 = (k + 1) % 4; tri(A[k], A[k2], B[k]); tri(A[k2], B[k2], B[k]); }
  }
  // the tail: a fan, forked when `fork` > 0
  const zb = -0.15, tl = tail, fk = 0.03 + fork;
  const bl = [-0.018, 0, zb], br = [0.018, 0, zb], tL = [-fk, 0, zb - tl], tR = [fk, 0, zb - tl], nt = [0, 0, zb - tl * (fork > 0 ? 0.62 : 0.95)];
  tri(bl, nt, tL); tri(bl, br, nt); tri(br, tR, nt);
  // the wings: five stations from the shoulder to the tip (leading edge swept back toward the tip)
  const xs = [0.04, 0.13, 0.25, 0.38, 0.5];
  const le = [0.075, 0.085, 0.06 * lead, 0.0, -0.075];
  const te = [-0.075, -0.1, -0.115, -0.115, -0.11];
  for (const s of [-1, 1]) {
    for (let i = 0; i < 4; i++) {
      const w0 = xs[i] / 0.5, w1 = xs[i + 1] / 0.5;
      const L0 = [s * xs[i], 0.02 * w0, le[i]], T0 = [s * xs[i], 0.02 * w0, te[i] * chord];
      const L1 = [s * xs[i + 1], 0.02 * w1, le[i + 1]], T1 = [s * xs[i + 1], 0.02 * w1, te[i + 1] * chord];
      tri(L0, T0, T1); tri(L0, T1, L1);
    }
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(P, 3));
  geo.computeVertexNormals();
  return geo;
}

const VERT = /* glsl */ `
  attribute vec4 aA, aB, aC;
  uniform float uT, uVis;
  varying vec3 vN; varying vec3 vWorld; varying float vWing;
  const float TAU = 6.2831853;
  #if KIND == 0
  // geese: a straight crossing of the sky; aA = ( heading, speed, altitude, phase ), aB = ( formation x, formation back, seed, ), aC = ( lateral offset, span, seed2, )
  vec3 posAt( float t ) {
    vec3 D = vec3( cos( aA.x ), 0.0, sin( aA.x ) );
    vec3 right = vec3( D.z, 0.0, -D.x );
    float L = 22000.0;
    float s = mod( t * aA.y + aA.w * L, L ) - L * 0.5;
    vec3 p = vec3( 25.0, aA.z, -300.0 ) - right * aC.x + D * s;
    p += right * aB.x - D * aB.y;
    p.y += sin( t * 0.9 + aB.z * TAU ) * 2.5 + sin( t * 0.045 + aC.z * TAU ) * 45.0 + aB.y * 0.12;
    return p;
  }
  #elif KIND == 1
  // swallows: a loose Lissajous stream; aA = ( centre, speed ), aB = ( extent, phase ), aC = ( lag, span, seed, )
  vec3 posAt( float t ) {
    float tt = ( t - aC.x ) * aA.w;
    return aA.xyz + vec3( aB.x * sin( tt + aB.w ), aB.y * sin( tt * 2.17 + aB.w * 1.9 + 0.5 ), aB.z * sin( tt * 1.31 + aB.w * 1.7 ) );
  }
  #else
  // starlings: one cloud; aA = ( centre, scale ), aB = ( a point in the unit ball, ), aC = ( , span, seed, )
  vec3 posAt( float t ) {
    vec3 u = aB.xyz;
    // the cloud breathes: stretched one way, then another; a wave of density runs through it
    vec3 ax = vec3( 250.0 * ( 1.0 + 0.32 * sin( t * 0.31 ) ), 95.0 * ( 1.0 + 0.45 * sin( t * 0.23 + 1.0 ) ), 160.0 * ( 1.0 + 0.3 * sin( t * 0.19 + 2.0 ) ) );
    u.x *= 1.0 + 0.16 * sin( u.z * 4.0 - t * 1.3 );
    u.y += 0.12 * sin( u.x * 3.0 + t * 0.9 );
    float th = t * 0.22 + u.y * 0.9;
    vec3 q = u * ax;
    q = vec3( q.x * cos( th ) - q.z * sin( th ), q.y, q.x * sin( th ) + q.z * cos( th ) );
    vec3 c = aA.xyz + vec3( sin( t * 0.031 ) * 750.0, sin( t * 0.05 ) * 70.0, cos( t * 0.037 ) * 600.0 );
    return c + q + 9.0 * vec3( sin( t * 1.9 + aC.z * TAU ), sin( t * 2.3 + aC.z * 17.0 ), sin( t * 1.7 + aC.z * 29.0 ) );
  }
  #endif
  void main() {
    float t = uT;
    vec3 P0 = posAt( t ), P1 = posAt( t + 0.15 ), P2 = posAt( t + 0.4 );
    vec3 fwd = normalize( P1 - P0 + vec3( 0.0, 1e-4, 0.0 ) );
    vec3 f2 = normalize( P2 - P1 + vec3( 0.0, 1e-4, 0.0 ) );
    // bank into the turn
    float roll = clamp( cross( fwd, f2 ).y * BANK, -0.9, 0.9 );
    vec3 right = normalize( cross( vec3( 0.0, 1.0, 0.0 ), fwd ) );
    vec3 rr = right * cos( roll ) + cross( fwd, right ) * sin( roll );
    vec3 up = cross( fwd, rr );
    // the wings
    vec3 p = position;
    float w = abs( p.x ) * 2.0;
    float wing = smoothstep( 0.12, 0.4, w );
    #if KIND == 0
      float amp = mix( 0.2, 0.9, smoothstep( -0.3, 0.35, sin( t * 0.21 + aA.w * 20.0 ) ) ); // (glides now and then)
      float rate = 2.5 * TAU * ( 0.92 + 0.16 * aB.z );
    #elif KIND == 1
      float amp = mix( 0.1, 0.95, smoothstep( -0.15, 0.4, sin( ( t - aC.x ) * aA.w * 0.8 + aB.w * 3.1 ) ) );
      float rate = 9.0 * TAU * ( 0.9 + 0.2 * aC.z );
    #else
      float amp = 0.95;
      float rate = 8.0 * TAU * ( 0.88 + 0.24 * aC.z );
    #endif
    float flap = sin( rate * t + aC.z * TAU - w * 1.3 ) * amp;
    p.y += flap * w * w * 0.34 * wing;
    p.x *= 1.0 - 0.14 * abs( flap ) * w * wing;
    p.z -= abs( flap ) * w * w * 0.05 * wing;
    float size = aC.y * uVis;
    vec3 world = P0 + ( rr * p.x + up * p.y + fwd * p.z ) * size;
    vWorld = world;
    vN = rr * normal.x + up * normal.y + fwd * normal.z;
    vWing = wing;
    gl_Position = projectionMatrix * viewMatrix * vec4( world, 1.0 );
  }
`;

const FRAG = /* glsl */ `
  uniform vec3 uHaze, uSun, uBase, uSunCol;
  uniform float uHazeDensity, uSunK, uNight;
  varying vec3 vN; varying vec3 vWorld; varying float vWing;
  void main() {
    vec3 V = normalize( cameraPosition - vWorld );
    vec3 N = normalize( vN );
    if ( dot( N, V ) < 0.0 ) N = -N;
    vec3 toSun = -uSun;
    // looking toward the sun: the wing's edge and the thin wing glow
    float back = pow( max( dot( -V, toSun ), 0.0 ), 3.0 );
    float edge = pow( 1.0 - abs( dot( N, V ) ), 2.0 );
    float lit = max( dot( N, toSun ), 0.0 );
    vec3 col = uBase * ( 0.75 + 0.45 * N.y ) + uSunCol * uSunK * ( 0.22 * lit + 0.42 * back * ( 0.3 + 0.7 * vWing ) + 0.35 * edge * back );
    col *= 1.0 - 0.55 * uNight;
    float d = length( cameraPosition - vWorld );
    float hz = 1.0 - exp( -uHazeDensity * uHazeDensity * d * d );
    col = mix( col, uHaze, hz );
    gl_FragColor = vec4( col, 1.0 );
  }
`;

export class Birds {
  constructor({ scenery, quality }) {
    this.group = new THREE.Group();
    this.group.name = 'birds';
    const tier = quality?.tier || 'high';
    const lo = tier === 'low', mid = tier === 'medium' || tier === 'med';
    const r = new RNG('birds');
    this.uT = { value: 0 };
    const shared = {
      uT: this.uT, uHaze: scenery.haze.uHaze, uHazeDensity: scenery.haze.uHazeDensity, uSun: { value: SUN_DIR },
      uSunCol: { value: new THREE.Color(1.0, 0.72, 0.4) }, uSunK: OUT.uSunK, uNight: OUT.uNight,
    };
    const make = (kind, geo, count, fill, base, bank) => {
      const g = new THREE.InstancedBufferGeometry();
      g.index = geo.index;
      g.setAttribute('position', geo.attributes.position);
      g.setAttribute('normal', geo.attributes.normal);
      const A = new Float32Array(count * 4), B = new Float32Array(count * 4), C = new Float32Array(count * 4);
      for (let i = 0; i < count; i++) fill(i, A.subarray(i * 4, i * 4 + 4), B.subarray(i * 4, i * 4 + 4), C.subarray(i * 4, i * 4 + 4));
      g.setAttribute('aA', new THREE.InstancedBufferAttribute(A, 4));
      g.setAttribute('aB', new THREE.InstancedBufferAttribute(B, 4));
      g.setAttribute('aC', new THREE.InstancedBufferAttribute(C, 4));
      g.instanceCount = count;
      const uVis = { value: 1 };
      const mat = new THREE.ShaderMaterial({
        defines: { KIND: kind, BANK: bank.toFixed(1) }, vertexShader: VERT, fragmentShader: FRAG, side: THREE.DoubleSide,
        uniforms: { ...shared, uVis, uBase: { value: new THREE.Color(...base) } },
      });
      const m = new THREE.Mesh(g, mat);
      m.frustumCulled = false;
      m.visible = false;
      m.renderOrder = 2;
      m.layers.enable(1); // (reflected in the pond)
      this.group.add(m);
      return { mesh: m, uVis, A, B, C };
    };

    // geese: V formations; the first flock crosses soon after you arrive
    const flocks = lo ? 2 : 3;
    const gGeo = birdGeometry({ neck: 0.2, tail: 0.18, lead: 1.0, chord: 1.15, body: 0.05 });
    const gF = [];
    for (let f = 0; f < flocks; f++) {
      const n = f === 0 ? 11 : r.int(7, 13);
      const spd = r.range(145, 185);
      gF.push({
        a: f === 0 ? 2.45 : r.range(0, TAU), spd, alt: r.range(430, 720), lat: f === 0 ? 700 : r.range(-1700, 1700),
        ph: f === 0 ? 0.5 - 2300 / 22000 : r.float(), span: r.range(78, 104), n, sp: r.range(0.5, 0.62),
      });
    }
    const gList = gF.flatMap((fl) => Array.from({ length: fl.n }, (_, k) => [fl, k]));
    this.geese = make(0, gGeo, gList.length, (i, A, B, C) => {
      const [fl, k] = gList[i];
      const row = Math.ceil(k / 2), side = k % 2 ? 1 : -1;
      A.set([fl.a, fl.spd, fl.alt, fl.ph]);
      B.set([k === 0 ? 0 : side * row * fl.span * fl.sp + r.range(-4, 4), k === 0 ? 0 : row * fl.span * fl.sp * 0.95 + r.range(-4, 4), r.float(), 0]);
      C.set([fl.lat, fl.span * r.range(0.95, 1.05), r.float(), 0]);
    }, [0.06, 0.052, 0.046], 0.0);

    // swallows: three loose streams, two over the lawns either side of the house, one skimming the pond
    const sGeo = birdGeometry({ neck: 0.07, tail: 0.3, fork: 0.07, lead: 0.85, chord: 0.7, body: 0.038 });
    const streams = [
      { c: [-800, 175, -330], ax: [540, 115, 900], ws: 0.34, n: lo ? 8 : 14 },
      { c: [850, 175, -300], ax: [500, 115, 900], ws: 0.31, n: lo ? 8 : 14 },
      { c: [POND.x, 38, POND.z], ax: [170, 22, 420], ws: 0.52, n: lo ? 4 : 8 },
    ];
    const sList = streams.flatMap((s, si) => Array.from({ length: s.n }, (_, k) => [s, k, si]));
    this.swallows = make(1, sGeo, sList.length, (i, A, B, C) => {
      const [s, k, si] = sList[i];
      A.set([...s.c, s.ws * r.range(0.95, 1.05)]);
      B.set([s.ax[0] * r.range(0.9, 1.08), s.ax[1] * r.range(0.85, 1.15), s.ax[2] * r.range(0.9, 1.08), si * 2.1 + r.range(-0.12, 0.12)]);
      C.set([k * 0.27 + r.range(0, 0.35), si === 2 ? r.range(24, 30) : r.range(31, 38), r.float(), 0]);
    }, [0.04, 0.04, 0.045], 6.0);

    // starlings: one murmuration
    const nS = lo ? 130 : mid ? 240 : 380;
    const stGeo = birdGeometry({ neck: 0.06, tail: 0.14, lead: 0.9, chord: 0.8, body: 0.05 });
    this.starlings = make(2, stGeo, nS, (i, A, B, C) => {
      // a point in the unit ball
      let x, y, z;
      do { x = r.range(-1, 1); y = r.range(-1, 1); z = r.range(-1, 1); } while (x * x + y * y + z * z > 1);
      A.set([60, 730, -320, 1]);
      B.set([x, y, z, 0]);
      C.set([0, r.range(23, 29), r.float(), 0]);
    }, [0.03, 0.03, 0.035], 3.0);
    this.vis = { geese: 0, swallows: 0, starlings: 0 };
    // the leaders of the flocks and the first bird of each stream (what the sound follows)
    this.gLeads = []; { let at = 0; for (const fl of gF) { this.gLeads.push(at); at += fl.n; } }
    this.sLeads = []; { let at = 0; for (const s of streams) { this.sLeads.push(at); at += s.n; } }
    this._p = Array.from({ length: 12 }, () => new THREE.Vector3());
  }

  // CPU twins of the shader paths (the same arithmetic): where bird `i` of a kind is at time `t`
  gooseAt(i, t, out) {
    const { A, B, C } = this.geese, a = A[i * 4], spd = A[i * 4 + 1], alt = A[i * 4 + 2], ph = A[i * 4 + 3];
    const dx = Math.cos(a), dz = Math.sin(a), rx = dz, rz = -dx, L = 22000;
    const s = (((t * spd + ph * L) % L) + L) % L - L * 0.5;
    const fx = B[i * 4], fb = B[i * 4 + 1], sd = B[i * 4 + 2], lat = C[i * 4], sd2 = C[i * 4 + 2];
    return out.set(
      25 - rx * lat + dx * s + rx * fx - dx * fb,
      alt + Math.sin(t * 0.9 + sd * TAU) * 2.5 + Math.sin(t * 0.045 + sd2 * TAU) * 45 + fb * 0.12,
      -300 - rz * lat + dz * s + rz * fx - dz * fb,
    );
  }

  swallowAt(i, t, out) {
    const { A, B, C } = this.swallows, tt = (t - C[i * 4]) * A[i * 4 + 3], w = B[i * 4 + 3];
    return out.set(
      A[i * 4] + B[i * 4] * Math.sin(tt + w),
      A[i * 4 + 1] + B[i * 4 + 1] * Math.sin(tt * 2.17 + w * 1.9 + 0.5),
      A[i * 4 + 2] + B[i * 4 + 2] * Math.sin(tt * 1.31 + w * 1.7),
    );
  }

  starCentre(t, out) {
    const A = this.starlings.A;
    return out.set(A[0] + Math.sin(t * 0.031) * 750, A[1] + Math.sin(t * 0.05) * 70, A[2] + Math.cos(t * 0.037) * 600);
  }

  // who is out and where (for the sound): the flocks and streams that can be seen, and the cloud. Reuses its vectors.
  sources(t) {
    let k = 0;
    const geese = [], swallows = [];
    if (this.vis.geese > 0.2) for (const i of this.gLeads) geese.push(this.gooseAt(i, t, this._p[k++]));
    if (this.vis.swallows > 0.2) for (const i of this.sLeads) swallows.push(this.swallowAt(i, t, this._p[k++]));
    const star = this.vis.starlings > 0.2 ? this.starCentre(t, this._p[k++]) : null;
    return { geese, swallows, star, vis: this.vis };
  }

  // d: the hour (0 midnight … 1 golden); rain: 0..1
  update(clock, d, rain) {
    this.uT.value = clock;
    const dry = 1 - sseg(rain, 0.25, 0.6);
    const set = (b, v) => { b.uVis.value = v; b.mesh.visible = v > 0.01; };
    set(this.geese, (this.vis.geese = sseg(d, 0.38, 0.5) * dry));
    set(this.swallows, (this.vis.swallows = sseg(d, 0.52, 0.64) * (1 - sseg(rain, 0.5, 0.85))));
    const dusk = Math.exp(-(((d - 0.27) / 0.06) ** 2)) * 0.9, dawn = Math.exp(-(((d - 0.5) / 0.1) ** 2)) * 0.8, gold = sseg(d, 0.78, 0.9);
    set(this.starlings, (this.vis.starlings = Math.max(dusk, dawn, gold) * (1 - sseg(rain, 0.2, 0.5))));
  }
}
