// The interactive modes' interface, set in the film's typography: a quiet
// corner menu, a one-line hint, the pollen gauge (seven cells, like the
// cuff gauge on APX-9) with the garden's progress (beds grown of twelve), a
// chevron home to the skep, controls help (H), the menu panel (modes, time of
// day, the viewer's clock, sound, photo, fullscreen, gentle motion, start over),
// photo mode's strip, the sound nudge and the finale's title card.

const ICON = {
  menu: '<svg viewBox="0 0 24 24"><path d="M5 8h14M5 12h14M5 16h14" stroke="currentColor" stroke-width="1.5" fill="none"/></svg>',
  close: '<svg viewBox="0 0 24 24"><path d="M6 6l12 12M18 6L6 18" stroke="currentColor" stroke-width="1.5" fill="none"/></svg>',
  moon: '<svg viewBox="0 0 24 24"><path d="M15.5 4.5a7.5 7.5 0 1 0 4 13.6A8 8 0 0 1 15.5 4.5z" fill="currentColor"/></svg>',
  sun: '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="4" fill="currentColor"/><path d="M12 2.5v3M12 18.5v3M2.5 12h3M18.5 12h3M5.3 5.3l2.1 2.1M16.6 16.6l2.1 2.1M5.3 18.7l2.1-2.1M16.6 7.4l2.1-2.1" stroke="currentColor" stroke-width="1.4"/></svg>',
  chevron: '<svg viewBox="0 0 24 24"><path d="M8 5l8 7-8 7" fill="none" stroke="currentColor" stroke-width="1.8"/></svg>',
};

export class Hud {
  constructor(opts) {
    this.opts = opts;
    const el = document.createElement('div');
    el.id = 'hud';
    el.innerHTML = `
      <div class="hud-corner">
        <button class="hud-btn hud-menu" aria-label="Menu" aria-expanded="false">${ICON.menu}</button>
        <span class="hud-title"></span>
      </div>
      <button class="hud-swap" aria-label=""></button>
      <div class="hud-bottom">
        <div class="hud-hint" role="status" aria-live="polite"></div>
        <div class="hud-gauge" aria-label="Pollen">
          <span class="cells">${'<i></i>'.repeat(7)}</span>
          <span class="honey" title="Beds of the garden grown from the pollen you deliver to the skep" aria-live="polite" aria-atomic="true"><b>0</b>/12 beds</span>
        </div>
      </div>
      <div class="hud-arrow" aria-hidden="true">${ICON.chevron}</div>
      <div class="hud-panel" role="dialog" aria-label="Garden menu" hidden>
        <div class="seg" role="radiogroup" aria-label="Mode">
          <button data-mode="film" role="radio">Film</button><button data-mode="fly" role="radio">Fly</button><button data-mode="follow" role="radio">Follow</button>
        </div>
        <label class="tod"><span class="ico">${ICON.moon}</span><input type="range" min="0" max="1" step="0.01" aria-label="Time of day"/><span class="ico">${ICON.sun}</span></label>
        <div class="row">
          <button data-act="sound" aria-pressed="false">Sound off</button>
          <button data-act="photo">Photo mode</button>
          <button data-act="help">Controls</button>
        </div>
        <div class="row">
          <button data-act="gentle" aria-pressed="false">Gentle motion</button>
          <button data-act="full">Fullscreen</button>
        </div>
        <div class="row">
          <button data-act="rain" aria-pressed="false" title="Bring the rain (R)">Rain</button>
          <button data-act="snow" aria-pressed="false" title="Let it snow (N)">Snow</button>
          <button data-act="fog" aria-pressed="false" title="Bring the fog (V)">Fog</button>
          <button data-act="lights" aria-pressed="true" title="APX-9's navigation lights (L)">Lights</button>
          <button data-act="live" aria-pressed="false" title="Let the garden's hour follow your own clock">My clock</button>
        </div>
        <div class="row" data-row="reset" hidden>
          <button data-act="reset" title="Forget the garden you have grown and begin again">Start over</button>
        </div>
      </div>
      <div class="hud-help" hidden></div>
      <div class="hud-finale" aria-hidden="true"><h2></h2><span class="rule"></span><p></p></div>
      <div class="hud-nudge" role="group" aria-label="Sound">
        <span>The garden has a score.</span>
        <button data-act="nudge-on">Turn sound on</button><button data-act="nudge-off" class="quiet" aria-label="Not now">Not now</button>
      </div>
      <div class="hud-photo" hidden>
        <span class="txt"></span>
        <button data-act="stamp" aria-pressed="true" title="Add a small caption to the saved picture">Caption</button>
        <button data-act="save">Save PNG</button><button data-act="exitphoto">Done</button>
      </div>
      <div class="hud-flash"></div>`;
    document.body.appendChild(el);
    this.el = el;
    this.q = (s) => el.querySelector(s);
    this.cells = [...el.querySelectorAll('.cells i')];
    this.hintEl = this.q('.hud-hint');
    this.honeyBox = this.q('.honey');
    this.honeyEl = this.q('.honey b');
    this.finaleEl = this.q('.hud-finale');
    this.nudgeEl = this.q('.hud-nudge');
    this.resetBtn = this.q('[data-act=reset]');
    this._grown = 0;
    this.arrow = this.q('.hud-arrow');
    this.panel = this.q('.hud-panel');
    this.help = this.q('.hud-help');
    this.photo = this.q('.hud-photo');
    this.slider = this.q('.tod input');
    this.swapBtn = this.q('.hud-swap');
    this.title = this.q('.hud-title');
    this._hint = '';
    this._hintUntil = 0;
    this._baseHint = '';

    this.q('.hud-menu').addEventListener('click', () => this.togglePanel());
    this.swapBtn.addEventListener('click', () => opts.onSwap());
    this.slider.addEventListener('input', () => opts.onTime(parseFloat(this.slider.value)));
    el.querySelectorAll('.seg button').forEach((b) => b.addEventListener('click', () => { this.togglePanel(false); opts.onMode(b.dataset.mode); }));
    el.addEventListener('click', async (e) => {
      const b = e.target.closest('button[data-act]');
      if (!b) return;
      const a = b.dataset.act;
      if (a === 'sound') this.setSound(await opts.onSound());
      if (a === 'photo') { this.togglePanel(false); opts.onPhoto(); }
      if (a === 'help') { this.togglePanel(false); this.toggleHelp(true); }
      if (a === 'full') { if (document.fullscreenElement) document.exitFullscreen(); else document.documentElement.requestFullscreen?.(); }
      if (a === 'gentle') { const r = opts.onGentle(); b.setAttribute('aria-pressed', String(r)); }
      if (a === 'live') opts.onLive?.();
      if (a === 'rain') opts.onRain?.();
      if (a === 'snow') opts.onSnow?.();
      if (a === 'fog') opts.onFog?.();
      if (a === 'lights') opts.onLights?.();
      if (a === 'stamp') opts.onStamp?.();
      if (a === 'reset') this._confirmReset(b);
      if (a === 'nudge-on') { this.hideNudge(); opts.onNudge?.(true); }
      if (a === 'nudge-off') { this.hideNudge(); opts.onNudge?.(false); }
      if (a === 'save') opts.onSave();
      if (a === 'exitphoto') opts.onPhoto();
    });
    // keep clicks on the interface from steering the bee
    for (const ev of ['mousedown', 'touchstart', 'wheel']) el.addEventListener(ev, (e) => { if (e.target.closest('button, input, .hud-panel, .hud-help')) e.stopPropagation(); }, { passive: true });
  }

  show(on) { document.body.classList.toggle('explore', on); }

  setMode(mode, { touch = false } = {}) {
    this.mode = mode;
    document.body.dataset.mode = mode;
    this.title.textContent = mode === 'fly' ? 'Flying as APX-9' : mode === 'follow' ? 'Following APX-9' : '';
    this.swapBtn.textContent = mode === 'fly' ? 'Autopilot' : 'Take the controls';
    this.swapBtn.setAttribute('aria-label', mode === 'fly' ? 'Hand APX-9 back to its autopilot (C)' : 'Take control of APX-9 (C)');
    this.el.querySelectorAll('.seg button').forEach((b) => b.setAttribute('aria-checked', String(b.dataset.mode === mode)));
    this.touch = touch;
    this._renderHelp();
  }

  setGentle(on) { this.q('[data-act=gentle]').setAttribute('aria-pressed', String(on)); }

  setSound(on) {
    const b = this.q('[data-act=sound]');
    b.textContent = on ? 'Sound on' : 'Sound off';
    b.setAttribute('aria-pressed', String(on));
  }

  setTime(v) { this.slider.value = String(v); }

  setLive(on) { this.q('[data-act=live]').setAttribute('aria-pressed', String(!!on)); }

  setRain(on) { this.q('[data-act=rain]').setAttribute('aria-pressed', String(!!on)); }

  setSnow(on) { this.q('[data-act=snow]').setAttribute('aria-pressed', String(!!on)); }

  setFog(on) { this.q('[data-act=fog]').setAttribute('aria-pressed', String(!!on)); }

  setLights(on) { this.q('[data-act=lights]').setAttribute('aria-pressed', String(!!on)); }

  setStamp(on) { this.q('[data-act=stamp]').setAttribute('aria-pressed', String(!!on)); }

  // "Start over" asks twice: the first press arms it for a few seconds
  _confirmReset(b) {
    if (b.dataset.armed) {
      clearTimeout(this._resetTimer);
      this.opts.onReset?.();
      return;
    }
    b.dataset.armed = '1';
    b.classList.add('warn');
    b.textContent = 'Press again to confirm';
    this._resetTimer = setTimeout(() => { delete b.dataset.armed; b.classList.remove('warn'); b.textContent = 'Start over'; }, 4000);
  }

  // the sound nudge: a quiet offer after the first pollination, for a few seconds
  showNudge(secs = 16) {
    this.nudgeEl.classList.add('on');
    clearTimeout(this._nudgeTimer);
    this._nudgeTimer = setTimeout(() => { this.hideNudge(); this.opts.onNudge?.(null); }, secs * 1000);
  }

  hideNudge() {
    clearTimeout(this._nudgeTimer);
    this.nudgeEl.classList.remove('on');
  }

  // the finale's title card
  showFinale({ title, line, secs = 11 }) {
    this.finaleEl.querySelector('h2').textContent = title;
    this.finaleEl.querySelector('p').textContent = line;
    this.finaleEl.classList.add('on');
    clearTimeout(this._finaleTimer);
    this._finaleTimer = setTimeout(() => this.finaleEl.classList.remove('on'), secs * 1000);
  }

  togglePanel(force) {
    const open = force ?? this.panel.hidden;
    this.panel.hidden = !open;
    this.q('.hud-menu').setAttribute('aria-expanded', String(open));
    this.q('.hud-menu').innerHTML = open ? ICON.close : ICON.menu;
    if (open) this.toggleHelp(false);
    this.opts.onPanel?.(open);
  }

  toggleHelp(force) {
    const open = force ?? this.help.hidden;
    this.help.hidden = !open;
    if (open) this._renderHelp();
  }

  get overlayOpen() { return !this.panel.hidden || !this.help.hidden; }

  _renderHelp() {
    const t = this.touch;
    const fly = this.mode === 'fly';
    const rows = fly
      ? (t
        ? [['Left stick', 'up/down: fly forward · back; left/right: turn'], ['Drag the view', 'look around and steer'], ['▲ ▼', 'climb · descend'], ['»', 'boost'], ['Settle', 'descend gently onto a bloom, lily, flower bed or lamp to land'], ['The north doors', 'fly out: the whole walled garden is yours'], ['The skep', 'fly into the doorway to deposit pollen']]
        : [['Mouse', 'steer (click to capture the pointer, Esc to release)'], ['W S · ↑ ↓', 'fly forward · back'], ['A D · ← →', 'turn (the camera turns with you)'], ['Space / E · Shift / Q', 'climb · descend'], ['F or hold left mouse', 'boost'], ['Settle on a bloom', 'descend gently onto it to gather pollen (lilies, flower beds, lamps and the temple too)'], ['The north doors', 'fly out: the pool, the temple, the lamps; C brings you home'], ['The skep', 'fly into its doorway to deposit'], ['The escapement', 'touch it to wind the garden']])
      : (t
        ? [['Drag', 'orbit the camera'], ['Pinch', 'zoom'], ['Take the controls', 'fly APX-9 from where it is'], ['Trips', 'now and then APX-9 flies out to the pool or along the avenue']]
        : [['Drag', 'orbit the camera'], ['Wheel', 'zoom'], ['C', 'take the controls, from where APX-9 is'], ['Trips', 'now and then APX-9 flies out to the pool or along the avenue']]);
    const common = t ? [] : [['C', fly ? 'hand back to the autopilot' : ''], ['T · [ ]', 'time of day'], ['P', 'photo mode'], ['M', 'sound'], ['L', 'navigation lights'], ['R · N · V', 'rain · snow · fog'], ['H', 'this help'], ['G', 'menu']].filter((r) => r[1]);
    const gp = fly && !t ? [['Gamepad', 'sticks fly and look · A climb · B or LT descend · RB boost · Y autopilot']] : [];
    this.help.innerHTML = `<h2>${fly ? 'Flying as APX-9' : 'Following APX-9'}</h2><dl>${[...rows, ...common, ...gp].map(([k, v]) => `<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl><p class="foot">${t ? 'Tap anywhere to close' : 'Press H to close'}</p>`;
  }

  // a message for a few seconds, then back to the standing hint
  flashHint(text, secs = 3.5) {
    this._hint = text;
    this._hintUntil = performance.now() + secs * 1000;
    this._setHint(text);
  }

  baseHint(text) {
    this._baseHint = text;
    if (performance.now() > this._hintUntil) this._setHint(text);
  }

  _setHint(text) {
    if (this.hintEl.textContent === text) return;
    this.hintEl.classList.remove('in');
    void this.hintEl.offsetWidth;
    this.hintEl.textContent = text;
    this.hintEl.classList.add('in');
  }

  flash() {
    const f = this.q('.hud-flash');
    f.classList.remove('go');
    void f.offsetWidth;
    f.classList.add('go');
  }

  update({ pollen, honey, grown = 0, total = 12, arrow, photo, photoText, hint }) {
    if (hint !== undefined) this.baseHint(hint);
    if (performance.now() > this._hintUntil && this._hint) { this._hint = ''; this._setHint(this._baseHint); }
    const n = pollen * 7;
    this.cells.forEach((c, i) => { const k = Math.max(0, Math.min(1, n - i)); c.style.setProperty('--k', k.toFixed(2)); });
    if (String(grown) !== this.honeyEl.textContent || this._total !== total) {
      const bump = this._total !== undefined && grown > this._grown;
      this._grown = grown;
      this._total = total;
      this.honeyEl.textContent = String(grown);
      const done = grown >= total;
      this.honeyBox.lastChild.textContent = done ? ' · in full bloom' : `/${total} beds`;
      this.honeyBox.classList.toggle('done', done);
      this.resetBtn.parentElement.hidden = grown === 0 && honey === 0;
      if (bump) { this.honeyBox.classList.remove('bump'); void this.honeyBox.offsetWidth; this.honeyBox.classList.add('bump'); }
    }
    if (arrow) {
      this.arrow.style.opacity = '1';
      this.arrow.style.transform = `translate(${arrow.x.toFixed(1)}px, ${arrow.y.toFixed(1)}px) rotate(${arrow.a.toFixed(3)}rad)`;
    } else this.arrow.style.opacity = '0';
    this.photo.hidden = !photo;
    if (photo) this.photo.querySelector('.txt').textContent = photoText;
    document.body.classList.toggle('photo', !!photo);
  }
}
