import * as THREE from 'three';
import { clamp, sseg } from '../core/ease.js';
import { WIND, gust } from '../world/wind.js';
import { POND, AXIS_X, MANOR } from './scenery.js';
import { WEATHER } from '../world/weatherU.js';
import { WATER_Y } from './pond.js';

// The sound of the world beyond the glass (interactive modes, once sound is on). Nothing here is a loop of a recording:
// every voice is synthesised (audio/live.js) and every one is fired by something that is really happening.
//
//  · the wind in the trees follows the garden's own gust field at the camera (the leaves you see lean as it swells),
//    stronger in a storm; the reeds hiss in a gust, the pool laps at its stone; both pan toward the pool and swell as you near it;
//  · the mallards quack now and then, each from where it floats; a duck that tips up splashes as its head goes under and as it
//    comes up; APX-9 passing low over one startles it into a run of quacks;
//  · geese honk as their formation crosses (a chorus from the flock's own place in the sky), swallows twitter as a stream darts by,
//    the starling cloud rustles and whistles as it swirls above the roof;
//  · songbirds sing far off: a dawn chorus at first light, a few through the day, one or two at dusk, and again once a storm has cleared;
//  · rain makes the pool plink; frogs croak at the pool after dusk and in the wet; crickets chirp on the lawns at night and an owl
//    calls now and then from the woods.
// Sounds are panned and thinned with distance from the camera (audio.spatial) and dulled by the glazing (audio's outdoor bus).

const TAU = Math.PI * 2;
const rnd = (a, b) => a + (b - a) * Math.random();

export class Outdoors {
  constructor({ audio, pond, birds, dragonflies }) {
    this.audio = audio;
    this.pond = pond;
    this.birds = birds;
    this.dragonflies = dragonflies;
    this.tSkim = 0;
    const n = pond.ducks.length;
    this.tDuck = Array.from({ length: n }, () => rnd(4, 22));
    this.coolDuck = Array.from({ length: n }, () => 0);
    this.tGoose = Array.from({ length: 3 }, () => rnd(0.2, 2));
    this.tSwallow = Array.from({ length: 3 }, () => rnd(0.3, 2.5));
    this.tStar = 1;
    this.tSong = 2;
    this.tFrog = 3;
    this.tOwl = rnd(8, 25);
    this.tDrip = 2;
    this.tToll = 5;
    this.plinkAcc = 0;
    // crickets live where they live: fixed spots on the lawns, each with its own pitch and pace
    this.crickets = Array.from({ length: 6 }, (_, i) => {
      const a = (i / 6) * TAU + rnd(-0.4, 0.4), r = rnd(380, 1300);
      return { x: 25 + Math.cos(a) * r * 1.2, z: -300 + Math.sin(a) * r, f: rnd(4300, 4950), t: rnd(0, 1.5), gap: rnd(0.5, 0.8) };
    });
    // (the pool tells us when a duck dabbles)
    pond.onDabble = (x, z, size) => {
      const au = this.audio;
      if (!au?.enabled || !au.ctx || WEATHER.uCover.value > 0.3) return; // (frozen over: no ducks, no splash)
      au.splash(au.spatial(x, WATER_Y + 1, z, 170), 0.085 * size * size, 0.7);
    };
    // a koi rising: a bloop; a dragonfly touching the water: a drop
    pond.onRise = (x, z) => {
      const au = this.audio;
      if (au?.enabled && au.ctx) au.bloop(au.spatial(x, WATER_Y + 1, z, 190), 0.12);
    };
    pond.onStartle = (x, z) => {
      const au = this.audio;
      if (au?.enabled && au.ctx && WEATHER.uCover.value < 0.3) au.splash(au.spatial(x, WATER_Y + 1, z, 150), 0.055, 0.45);
    };
    if (dragonflies) dragonflies.onDip = (x, z) => {
      const au = this.audio;
      if (au?.enabled && au.ctx) au.plink(au.spatial(x, WATER_Y + 1, z, 150), 0.12);
    };
    this._v = new THREE.Vector3();
  }

  // dt: seconds of real time; clock: the explore clock; s: { camera, bee: { pos, flying }, d: the hour, rain }
  update(dt, clock, { camera, bee, d, rain, snow = 0, fog = 0, bow = 0, outside = false }) {
    const au = this.audio;
    if (!au || !au.enabled || !au.ctx) return;
    dt = Math.min(dt, 0.1);
    const cp = camera.position, e = camera.matrixWorld.elements, rl = Math.hypot(e[0], e[2]) || 1;
    au.listen(cp.x, cp.y, cp.z, e[0] / rl, e[2] / rl);
    const night = 1 - sseg(d, 0, 0.55), day = 1 - night;
    const dry = (1 - rain) * (1 - snow); // (the cold is as quiet as the wet for the crickets and the frogs, and the songbirds)
    // snow deadens the outdoors, and breathes its own low hush
    au.muffle(Math.min(1, Math.max(snow * 1.2, fog * 0.5)), outside ? 1 : 0); // (outside the glass nothing is dulled by it)
    au.bed('hush', 0.008 * snow, 0);

    // ---- beds -------------------------------------------------------------------------------------
    const g = gust(cp.x, cp.z, WIND.u.uWindT.value);
    const windK = (0.45 + 0.55 * g) * (0.55 + 0.45 * day) * (1 + 0.8 * rain);
    au.bed('wind', 0.0125 * windK * (1 - 0.5 * snow));
    au.bed('leaves', 0.0065 * (0.12 + g) * (0.4 + 0.6 * day) * (1 + 0.5 * rain) * (1 - 0.8 * snow));
    // the pool: how close its water is (to its edge, with height counting for something)
    const k = Math.hypot((cp.x - POND.x) / POND.rx, (cp.z - POND.z) / POND.rz);
    const dEdge = Math.hypot(Math.max(0, k - 1) * 230, Math.max(0, cp.y - 30) * 0.55);
    const near = 1 / (1 + (dEdge / 170) ** 2);
    const pp = au.spatial(POND.x, WATER_Y, POND.z, 400);
    au.bed('lap', 0.016 * near * (1 - 0.4 * rain), pp.pan * 0.9);
    au.bed('trickle', 0.0045 * near * (1 + 1.5 * rain), pp.pan * 0.9);
    au.bed('reeds', 0.0075 * near * (0.15 + g) * (1 + rain), pp.pan * 0.8);

    // dragonflies: a dry whirr that swells as the nearest comes by
    {
      const dr = this.dragonflies;
      let best = 0, pan = 0;
      if (dr && dr.vis > 0.05) for (const f of dr.flies) {
        const sp = au.spatial(f.pos.x, f.pos.y, f.pos.z, 120);
        if (sp.gain > best) { best = sp.gain; pan = sp.pan; }
      }
      au.bed('dragon', 0.011 * best * (dr ? dr.vis : 0), pan);
    }
    // the bee skimming the water: a small splash now and then
    this.tSkim -= dt;
    if (this.tSkim <= 0 && bee.flying) {
      const k2 = Math.hypot((bee.pos.x - POND.x) / POND.rx, (bee.pos.z - POND.z) / POND.rz);
      if (k2 < 1.0 && bee.pos.y - WATER_Y < 9 && bee.pos.y - WATER_Y > -1 && WEATHER.uCover.value < 0.3) {
        this.tSkim = rnd(0.6, 1.2);
        au.splash(au.spatial(bee.pos.x, WATER_Y + 1, bee.pos.z, 150), 0.07, 0.45);
      }
    }

    const src = this.birds.sources(clock);
    // the murmuration: a rustle that swells as the cloud comes near, and now and then a starling's whistle
    if (src.star) {
      const sp = au.spatial(src.star.x, src.star.y, src.star.z, 900);
      au.bed('star', 0.02 * sp.gain * src.vis.starlings, sp.pan);
      this.tStar -= dt;
      if (this.tStar <= 0) {
        this.tStar = rnd(0.7, 2.4);
        const v = this._v.copy(src.star).add(new THREE.Vector3(rnd(-200, 200), rnd(-80, 80), rnd(-150, 150)));
        au.starling(au.spatial(v.x, v.y, v.z, 520), 0.045 * src.vis.starlings);
      }
    } else au.bed('star', 0);

    // ---- the ducks ----------------------------------------------------------------------------------
    const ducks = this.pond.ducks;
    for (let i = 0; i < ducks.length; i++) {
      const dk = ducks[i];
      if (dk.x === undefined) continue;
      this.coolDuck[i] -= dt;
      this.tDuck[i] -= dt;
      const bd = Math.hypot(bee.pos.x - dk.x, bee.pos.y - WATER_Y, bee.pos.z - dk.z);
      if (bee.flying && bd < 75 && this.coolDuck[i] <= 0) {
        // startled by APX-9 passing low: a run of quacks and a slap of water
        this.coolDuck[i] = rnd(6, 11);
        this.tDuck[i] = rnd(9, 24);
        const sp = au.spatial(dk.x, WATER_Y + 3, dk.z, 260);
        au.quack(sp, 0.11, 3 + Math.floor(Math.random() * 4));
        au.splash(sp, 0.08, 0.6);
      } else if (this.tDuck[i] <= 0) {
        this.tDuck[i] = rnd(9, 36) * (night > 0.8 ? 4 : 1) * (1 + rain);
        if (night < 0.9 && snow < 0.3) au.quack(au.spatial(dk.x, WATER_Y + 3, dk.z, 260), 0.08);
      }
    }

    // ---- the flocks ---------------------------------------------------------------------------------
    for (let i = 0; i < src.geese.length; i++) {
      this.tGoose[i] -= dt;
      if (this.tGoose[i] > 0) continue;
      this.tGoose[i] = rnd(1.4, 4.4);
      const lead = src.geese[i], v = this._v;
      if (lead.distanceTo(cp) > 3200) continue; // (too far to hear)
      const voices = 1 + Math.floor(Math.random() * 3);
      for (let j = 0; j < voices; j++) {
        v.set(lead.x + rnd(-260, 260), lead.y + rnd(-30, 30), lead.z + rnd(-260, 260));
        au.honk(au.spatial(v.x, v.y, v.z, 1100), 0.05 * src.vis.geese, j * rnd(0.04, 0.16)); // (a wide, gentle law: far geese are faint, near ones not deafening)
      }
    }
    for (let i = 0; i < src.swallows.length; i++) {
      this.tSwallow[i] -= dt;
      if (this.tSwallow[i] > 0) continue;
      this.tSwallow[i] = rnd(1.1, 4);
      const p = src.swallows[i];
      if (p.distanceTo(cp) > 1400) continue;
      au.twitter(au.spatial(p.x, p.y, p.z, 230), 0.06 * src.vis.swallows);
    }

    // ---- far-off songbirds ----------------------------------------------------------------------------
    this.tSong -= dt;
    if (this.tSong <= 0 && rain < 0.7 && snow < 0.25) {
      const chorus = Math.exp(-(((d - 0.5) / 0.09) ** 2)); // first light
      const rate = 0.12 + 0.9 * chorus + 0.18 * sseg(d, 0.55, 0.7) + 0.1 * Math.exp(-(((d - 0.27) / 0.05) ** 2)) + 0.7 * bow * sseg(d, 0.4, 0.55); // phrases a second, roughly (and the birds sing again when the rain has cleared)
      this.tSong = rnd(0.6, 1.6) / (rate * dry + 0.02);
      if (night < 0.85 || chorus > 0.1) {
        const a = rnd(0, TAU), r = rnd(450, 1900);
        const sp = au.spatial(25 + Math.cos(a) * r * 1.2, rnd(30, 220), -300 + Math.sin(a) * r, 520);
        const pick = Math.random();
        if (pick < 0.45) au.whistle(sp, 0.055);
        else if (pick < 0.75) au.trill(sp, 0.07);
        else au.chirp(sp.pan, 0.03 * sp.gain);
      }
    }

    // ---- the pool in the wet and the dark -----------------------------------------------------------------
    if (rain > 0.12 && near > 0.03) {
      this.plinkAcc += dt * rain * 16 * near;
      let n = 0;
      while (this.plinkAcc >= 1 && n++ < 4) {
        this.plinkAcc -= 1;
        // a drop somewhere on the water, nearer the camera than not
        const a = rnd(0, TAU), rr = Math.sqrt(Math.random()) * 0.8;
        const x = clamp(cp.x, POND.x - POND.rx, POND.x + POND.rx) * 0.5 + (POND.x + Math.cos(a) * POND.rx * rr) * 0.5;
        const z = clamp(cp.z, POND.z - POND.rz, POND.z + POND.rz) * 0.5 + (POND.z + Math.sin(a) * POND.rz * rr) * 0.5;
        au.plink(au.spatial(x, WATER_Y, z, 140), 0.1);
      }
    } else this.plinkAcc = 0;

    const dusk = Math.exp(-(((d - 0.27) / 0.12) ** 2));
    const wet = rain > 0.3 ? 0.6 : 0;
    const frogK = Math.max(night * 0.9, dusk * 0.7, wet) * (1 - Math.min(1, snow * 2));
    this.tFrog -= dt;
    if (this.tFrog <= 0) {
      this.tFrog = rnd(1.4, 5) / (frogK + 0.02);
      if (frogK > 0.3) {
        const a = rnd(0, TAU);
        au.croak(au.spatial(POND.x + Math.cos(a) * POND.rx * 0.9, WATER_Y + 1, POND.z + Math.sin(a) * POND.rz * 0.9, 300), 0.1 * frogK);
      }
    }
    const cricketK = night * dry;
    if (cricketK > 0.25) {
      for (const c of this.crickets) {
        c.t -= dt;
        if (c.t <= 0) {
          c.t = c.gap * rnd(0.85, 1.2) / (0.5 + 0.5 * cricketK);
          au.cricket(au.spatial(c.x, 6, c.z, 190), 0.05 * cricketK, c.f);
        }
      }
    }
    // fog: dew dripping from the glasshouse and, now and then, the manor's bell tolling far off through it
    if (fog > 0.3) {
      this.tDrip -= dt;
      if (this.tDrip <= 0) {
        this.tDrip = rnd(0.9, 3.2) / fog;
        const a = rnd(0, TAU), r = rnd(25, 90);
        au.plink(au.spatial(cp.x + Math.cos(a) * r, 2, cp.z + Math.sin(a) * r, 70), 0.05 * fog);
      }
      this.tToll -= dt;
      if (this.tToll <= 0) {
        this.tToll = rnd(38, 80);
        au.toll(au.spatial(AXIS_X, 70, MANOR.z, 1500), 0.11 * fog, 3 + Math.floor(Math.random() * 2), rnd(3.3, 4.2));
      }
    } else this.tToll = Math.min(this.tToll, 6); // (the first toll comes soon after the fog does)
    this.tOwl -= dt;
    if (this.tOwl <= 0) {
      this.tOwl = rnd(26, 70);
      if (night > 0.55 && rain < 0.4) {
        const a = rnd(0, TAU), r = rnd(1500, 2800);
        au.hoot(au.spatial(25 + Math.cos(a) * r, 220, -300 + Math.sin(a) * r, 900), 0.07);
      }
    }
  }
}
