import * as THREE from 'three';
import { RNG } from '../core/rng.js';
import { POND } from './scenery.js';
import { WATER_Y } from './pond.js';

// Fireflies over the pool and its margin, at night (interactive modes; the brass ones in the house are in fireflies.js).
//
// A few score of them hang over the water, in the reeds and along the lawn's edge, each drifting on its own slow loop and
// blinking in its own time: a short, soft pulse every few seconds, so that the swarm never blinks together but sparkles.
// All of it is worked out in the vertex shader from fixed per-firefly numbers and the clock (no work on the CPU), each fly one
// point sprite with an HDR core and a halo for the bloom to take up; they are drawn into the pool's mirror pass too, so every
// one has its reflection in the black water, which is most of the point. Sprites are sized from the height of whatever target
// is being drawn into, so they are the same in the mirror's small target as on the screen. They go out in rain and by day.

const TAU = Math.PI * 2;

const VERT = /* glsl */ `
  attribute vec4 aHome;  // home x, y, z, drift radius
  attribute vec4 aP;     // phase, rate, blink period, seed
  uniform float uT, uVis, uRes;
  varying float vB; varying float vFade;
  const float TAU = 6.2831853;
  void main() {
    float t = uT * aP.y;
    vec3 p = aHome.xyz + aHome.w * vec3(sin(t * 0.35 + aP.x) + 0.5 * sin(t * 0.83 + aP.x * 2.0), 0.35 * sin(t * 0.5 + aP.x * 1.7) + 0.2 * sin(t * 1.3), cos(t * 0.29 + aP.x * 1.3) + 0.5 * cos(t * 0.71 + aP.x));
    // a short pulse in its own time: up fast, down slower, then dark
    float ph = fract(uT / aP.z + aP.w);
    float duty = 0.3;
    float pulse = ph < duty ? pow(sin(ph / duty * 3.14159), 1.6) : 0.0;
    // (a little glow in between, as the real ones have)
    vB = (pulse + 0.1) * uVis;
    vec4 mv = modelViewMatrix * vec4(p, 1.0);
    float d = -mv.z;
    // world size 5 units: pixels from the target's height and the projection
    float px = 5.0 * uRes * 0.5 * projectionMatrix[1][1] / max(d, 1.0) * (0.8 + 0.7 * pulse);
    gl_PointSize = clamp(px, 1.5 * uRes / 720.0, 34.0 * uRes / 720.0);
    vFade = 1.0 - smoothstep(900.0, 2600.0, d);
    gl_Position = projectionMatrix * mv;
  }
`;

const FRAG = /* glsl */ `
  uniform vec3 uColor;
  varying float vB; varying float vFade;
  void main() {
    float r = length(gl_PointCoord - 0.5) * 2.0;
    float core = exp(-r * r * 14.0) * 4.5;
    float halo = pow(max(1.0 - r, 0.0), 2.2) * 1.1;
    gl_FragColor = vec4(uColor * (core + halo) * vB * vFade, 1.0);
  }
`;

export class NightFlies {
  constructor({ quality }) {
    this.group = new THREE.Group();
    this.group.name = 'nightflies';
    const r = new RNG('nightflies');
    const tier = quality?.tier || 'high';
    const n = tier === 'low' ? 90 : tier === 'med' || tier === 'medium' ? 180 : 280;
    const home = new Float32Array(n * 4), par = new Float32Array(n * 4), pos = new Float32Array(n * 3);
    for (let i = 0; i < n; i++) {
      const u = r.float();
      let x, z, y, rad;
      if (u < 0.6) { // over the water
        const a = r.range(0, TAU), k = Math.sqrt(r.float()) * 0.9;
        x = POND.x + Math.cos(a) * POND.rx * k; z = POND.z + Math.sin(a) * POND.rz * k; y = WATER_Y + r.range(6, 38); rad = r.range(8, 26);
      } else if (u < 0.92) { // along the margin, among the reeds
        const a = r.range(0, TAU), k = r.range(0.92, 1.15);
        x = POND.x + Math.cos(a) * POND.rx * k; z = POND.z + Math.sin(a) * POND.rz * k; y = WATER_Y + r.range(6, 60); rad = r.range(8, 22);
      } else { // out over the lawn
        const a = r.range(0, TAU), k = r.range(1.2, 2.0);
        x = POND.x + Math.cos(a) * POND.rx * k; z = POND.z + Math.sin(a) * POND.rz * k; y = r.range(10, 70); rad = r.range(14, 34);
      }
      home.set([x, y, z, rad], i * 4);
      par.set([r.range(0, TAU), r.range(0.7, 1.3), r.range(1.8, 4.8), r.float()], i * 4);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setAttribute('aHome', new THREE.BufferAttribute(home, 4));
    geo.setAttribute('aP', new THREE.BufferAttribute(par, 4));
    this.uni = { uT: { value: 0 }, uVis: { value: 0 }, uRes: { value: 720 }, uColor: { value: new THREE.Color(1.0, 0.86, 0.28) } };
    const mat = new THREE.ShaderMaterial({ uniforms: this.uni, vertexShader: VERT, fragmentShader: FRAG, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, fog: false });
    geo.boundingSphere = new THREE.Sphere(new THREE.Vector3(POND.x, WATER_Y + 40, POND.z), Math.max(POND.rx, POND.rz) * 2.4); // (over the pool, its margin and the lawn about it: culled with that)
    this.points = new THREE.Points(geo, mat);
    this.points.renderOrder = 3;
    this.points.visible = false;
    this.points.layers.enable(1); // (reflected in the pool)
    // sized from the target being drawn: the screen's pass and the mirror's small one differ
    this.points.onBeforeRender = (renderer) => {
      const rt = renderer.getRenderTarget();
      this.uni.uRes.value = rt ? rt.height : renderer.domElement.height;
    };
    this.group.add(this.points);
    this.n = n;
  }

  // phases.flies: 1 after dark … 0 by day; rain 0..1
  update(clock, phases, rain) {
    this.uni.uT.value = clock;
    const v = phases.flies * (1 - Math.min(1, rain * 2));
    this.uni.uVis.value = v;
    this.points.visible = v > 0.01;
  }

  setPerfLevel(level) {
    this.points.geometry.setDrawRange(0, Math.round(this.n * [1, 1, 0.7, 0.5][Math.max(0, Math.min(3, level))]));
  }
}
