// The garden remembers a visitor between visits: how many beds have grown, what
// has been delivered, whether the finale has played, and a few preferences.
// localStorage only, and every access is guarded (private windows and blocked
// site data throw or come back empty); without it the page works as before.
// Tools and capture runs call `save.off()` so they always start from a fresh garden.

const KEY = 'clockwork-garden.v1';
const DEFAULTS = {
  grown: 0, // beds grown (0..12)
  deposits: 0, // pollen deliveries to the skep
  pollinated: 0, // blooms pollinated (by anyone, first visit per session)
  winds: 0, // times the garden was wound
  finished: false, // the finale has played
  nudgeDone: false, // the sound nudge was answered
  controlsSeen: false, // the first-flight controls card was shown
  stamp: true, // photo mode: caption the saved picture
  live: false, // time of day follows the viewer's clock
  lights: true, // APX-9's navigation lights are on
};

let data = null;
let enabled = true;

function read() {
  const out = { ...DEFAULTS };
  try {
    const raw = JSON.parse(localStorage.getItem(KEY) || 'null');
    if (raw && typeof raw === 'object') {
      for (const k of Object.keys(DEFAULTS)) {
        if (typeof raw[k] === typeof DEFAULTS[k]) out[k] = raw[k];
      }
    }
  } catch (e) { /* unavailable or corrupt: start fresh */ }
  for (const k of ['grown', 'deposits', 'pollinated', 'winds']) out[k] = Math.max(0, Math.min(99999, Math.floor(out[k]) || 0));
  return out;
}

export const save = {
  // the saved record (a copy of the defaults when there is none)
  get() { return (data ||= enabled ? read() : { ...DEFAULTS }); },
  set(patch) {
    Object.assign(this.get(), patch);
    this.flush();
  },
  flush() {
    if (!enabled || !data) return;
    try { localStorage.setItem(KEY, JSON.stringify(data)); } catch (e) { /* ignore */ }
  },
  // forget the garden's progress (preferences stay)
  resetProgress() {
    const d = this.get();
    Object.assign(d, { grown: 0, deposits: 0, pollinated: 0, winds: 0, finished: false });
    this.flush();
  },
  // do not read or write anything (capture and review tools)
  off() { enabled = false; data = { ...DEFAULTS }; },
  get enabled() { return enabled; },
};
