import * as THREE from 'three';
import { clamp, sseg } from '../core/ease.js';
import { MM } from '../creatures/apx9.js';

// APX-9's navigation lights (interactive modes only: the rig is the film's too, so everything here is hidden outside them).
//
// As on an aircraft: a red light on the port wingtip and a green one on the starboard, a steady white light at the tail, a white
// anti-collision strobe on the back of the thorax that flashes twice and rests (faster on a boost), and, at dusk and after dark,
// a warm lamp at the front with a soft beam. The wingtip lights are riding the wing beat, so as the wings blur each light paints its
// own arc in the air (a red and a green sector of the stroke, fading as the wings fold). Every light is a glow sprite (an HDR core
// and a halo, taken up by the bloom), sized from the target being drawn and the bee's own scale. At night they also light the garden
// through the light field: a red and a green pool at the wingtips, the strobe's flash lighting the beds, the lamp's warm pool ahead.
// By day they are small and quiet; the strobe still flashes. `L` or the menu switches them off.

const V = (x = 0, y = 0, z = 0) => new THREE.Vector3(x, y, z);
const RED = new THREE.Color(1.0, 0.06, 0.035), GREEN = new THREE.Color(0.04, 1.0, 0.22), WHITE = new THREE.Color(1.0, 0.95, 0.88), WARM = new THREE.Color(1.0, 0.82, 0.55);

const GLOW_VERT = /* glsl */ `
  uniform float uRes, uSize;
  void main() {
    vec4 mv = modelViewMatrix * vec4( position, 1.0 );
    float sc = length( modelMatrix[ 0 ].xyz );
    float d = -mv.z;
    float px = uSize * sc * uRes * 0.5 * projectionMatrix[ 1 ][ 1 ] / max( d, 0.4 );
    gl_PointSize = clamp( px, 2.5 * uRes / 720.0, 150.0 * uRes / 720.0 );
    gl_Position = projectionMatrix * mv;
  }
`;
const GLOW_FRAG = /* glsl */ `
  uniform vec3 uColor; uniform float uI;
  void main() {
    float r = length( gl_PointCoord - 0.5 ) * 2.0;
    float core = exp( -r * r * 22.0 ) * 5.0;
    float halo = pow( max( 1.0 - r, 0.0 ), 2.0 ) * 0.9;
    gl_FragColor = vec4( uColor * ( core + halo ) * uI, 1.0 );
  }
`;
const ARC_VERT = /* glsl */ `
  attribute float aU, aV;
  varying float vU, vV;
  void main() { vU = aU; vV = aV; gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 ); }
`;
const ARC_FRAG = /* glsl */ `
  uniform vec3 uColor; uniform float uI, uT;
  varying float vU, vV;
  void main() {
    // brightest along the middle of the stroke and its middle across, soft at the edges, with a quick shimmer along it
    float k = max( sin( vU * 3.14159 ), 0.0 ) * pow( max( sin( vV * 3.14159 ), 0.0 ), 1.5 ); // (pow of a tiny negative at the edge is NaN)
    float shimmer = 0.7 + 0.3 * sin( vU * 40.0 - uT * 55.0 );
    gl_FragColor = vec4( uColor * uI * k * shimmer * 0.9, 1.0 );
  }
`;
const BEAM_VERT = /* glsl */ `
  varying float vAxis; varying vec3 vN; varying vec3 vV;
  void main() {
    vAxis = position.x;
    vec4 mv = modelViewMatrix * vec4( position, 1.0 );
    vN = normalize( normalMatrix * normal );
    vV = normalize( -mv.xyz );
    gl_Position = projectionMatrix * mv;
  }
`;
const BEAM_FRAG = /* glsl */ `
  uniform vec3 uColor; uniform float uI, uLen;
  varying float vAxis; varying vec3 vN; varying vec3 vV;
  void main() {
    float u = clamp( vAxis / uLen, 0.0, 1.0 );
    // a soft volume: brightest down the middle of the cone as seen, thinning toward its end and its edges
    float mid = pow( abs( dot( normalize( vN ), normalize( vV ) ) ), 1.6 );
    float a = mid * pow( 1.0 - u, 1.7 ) * smoothstep( 0.0, 0.06, u );
    gl_FragColor = vec4( uColor * uI * a * 0.5, 1.0 );
  }
`;

// the double flash of an anti-collision strobe: two short flashes, then a rest
const strobe = (t, period) => {
  const p = (t % period) / period, w = 0.06;
  const f = (c) => Math.max(0, 1 - Math.abs(p - c) / w);
  return Math.min(1, f(0.1) * 1.4 + f(0.26) * 1.4);
};

export class BeeLights {
  constructor({ bee, field, quality }) {
    this.bee = bee;
    this.field = field;
    this.on = true; // the viewer's switch
    this.k = 1; // eased on/off
    this.active = false; // interactive modes
    this.group = new THREE.Group();
    this.group.name = 'bee-lights';
    this.res = { value: 720 };
    const S = MM;
    const mats = [];
    const glow = (color, size) => {
      const m = new THREE.ShaderMaterial({ uniforms: { uColor: { value: color.clone() }, uI: { value: 0 }, uRes: this.res, uSize: { value: size } }, vertexShader: GLOW_VERT, fragmentShader: GLOW_FRAG, transparent: true, depthWrite: false, depthTest: true, blending: THREE.AdditiveBlending, fog: false });
      mats.push(m);
      return m;
    };
    const point = (mat, pos, parent) => {
      const g = new THREE.BufferGeometry();
      g.setAttribute('position', new THREE.Float32BufferAttribute([0, 0, 0], 3));
      const p = new THREE.Points(g, mat);
      p.position.copy(pos);
      g.boundingSphere = new THREE.Sphere(new THREE.Vector3(), 8); // (a sprite is sized on screen: a generous radius, culled when the bee is out of the frame)
      p.renderOrder = 6;
      p.onBeforeRender = (renderer) => { const rt = renderer.getRenderTarget(); this.res.value = rt ? rt.height : renderer.domElement.height; };
      parent.add(p);
      return p;
    };
    const body = bee.body;
    // the wingtips (in each wing's own frame, so they ride the beat; the starboard wing is +Z, the port -Z)
    this.wingLights = [];
    for (const w of bee.wings) {
      const c = w.s > 0 ? GREEN : RED;
      const m = glow(c, 3.4 * S * 3.2);
      const p = point(m, bee.wingTip, w.mesh);
      // the light painted by the stroke: a thin sector at the tip's radius, laid as the wing fan is
      const rad = bee.wingTip.length(), ang = 2.1, n = 40;
      const geo = new THREE.RingGeometry(rad * 0.93, rad * 1.06, n, 1, -ang / 2, ang);
      const u = new Float32Array(geo.attributes.position.count);
      for (let i = 0; i < u.length; i++) u[i] = (i % (n + 1)) / n; // (a ring's vertices run along the arc: inner ring, then outer)
      geo.setAttribute('aU', new THREE.BufferAttribute(u, 1));
      const vv = new Float32Array(u.length);
      for (let i = 0; i < vv.length; i++) vv[i] = Math.floor(i / (n + 1)); // 0 on the inner edge, 1 on the outer
      geo.setAttribute('aV', new THREE.BufferAttribute(vv, 1));
      const am = new THREE.ShaderMaterial({ uniforms: { uColor: { value: c.clone() }, uI: { value: 0 }, uT: { value: 0 } }, vertexShader: ARC_VERT, fragmentShader: ARC_FRAG, transparent: true, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, fog: false });
      const arc = new THREE.Mesh(geo, am);
      arc.position.copy(w.hinge.position);
      arc.rotation.set(0, w.s > 0 ? 0 : Math.PI, 0.18);
      arc.renderOrder = 5;
      body.add(arc);
      this.wingLights.push({ s: w.s, m, p, arc, am, color: c, src: null });
    }
    // the tail (at the sting's tip), the beacon on the back of the thorax, the lamp at the front
    this.tail = { m: glow(WHITE, 2.4 * S * 2.8), color: WHITE };
    this.tail.p = point(this.tail.m, V(-14.6 * S, -2.7 * S, 0), body);
    this.beacon = { m: glow(WHITE, 4.6 * S * 3.0), color: WHITE };
    this.beacon.p = point(this.beacon.m, V(1.4 * S, 6.2 * S, 0), body);
    this.lamp = { m: glow(WARM, 3.6 * S * 2.2), color: WARM };
    this.lamp.p = point(this.lamp.m, V(13.9 * S, -0.9 * S, 0), body);
    // the beam: a cone from the lamp, slightly down, soft and additive (only the dark shows it)
    const L = 190 * S, R = 38 * S;
    const cg = new THREE.ConeGeometry(1, 1, 28, 1, true);
    cg.translate(0, -0.5, 0); cg.rotateZ(Math.PI / 2); cg.scale(L, R, R);
    this.beamMat = new THREE.ShaderMaterial({ uniforms: { uColor: { value: WARM.clone() }, uI: { value: 0 }, uLen: { value: L } }, vertexShader: BEAM_VERT, fragmentShader: BEAM_FRAG, transparent: true, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, fog: false });
    this.beam = new THREE.Mesh(cg, this.beamMat);
    this.beam.position.copy(this.lamp.p.position);
    this.beam.rotation.z = -0.12;
    this.beam.renderOrder = 4;
    body.add(this.beam);
    this.parts = [...this.wingLights.flatMap((w) => [w.p, w.arc]), this.tail.p, this.beacon.p, this.lamp.p, this.beam];
    for (const o of this.parts) o.visible = false;
    // the light field's sources (night.js owns the field)
    const add = (radius, core) => field?.add({ pos: V(), radius, core, color: new THREE.Color(0, 0, 0), k: 1 });
    for (const w of this.wingLights) w.src = add(13, 3);
    this.beaconSrc = add(44, 9);
    this.lampSrc = add(46, 11);
    this.tailSrc = add(8, 2);
    this._w = V(); this._f = V(); this._q = new THREE.Quaternion();
  }

  // the interactive modes' (the film's rig is shared: nothing here shows outside them)
  setActive(on) {
    this.active = on;
    this._show();
    if (!on) for (const s of [...this.wingLights.map((w) => w.src), this.beaconSrc, this.lampSrc, this.tailSrc]) s?.color.setRGB(0, 0, 0); // (the garden is not lit by them outside the modes)
  }

  setOn(on) { this.on = !!on; }

  _show() {
    const v = this.active && this.k > 0.01;
    for (const o of this.parts) o.visible = v;
  }

  // clock: the explore clock; s: { flap 0..1, boost 0..1, dark 0..1 (night, dusk, storm), flying }
  update(clock, dt, { flap = 0, boost = 0, dark = 0, flying = true }) {
    if (!this.active) return;
    this.k += ((this.on ? 1 : 0) - this.k) * (1 - Math.exp(-Math.max(dt, 1 / 120) / 0.18));
    if (!this.on && this.k < 0.01) this.k = 0;
    this._show();
    const k = this.k;
    // glints by day, brilliant at night
    const base = (0.3 + 0.7 * dark) * k;
    const st = strobe(clock, boost > 0.2 ? 0.55 : 1.3);
    for (const w of this.wingLights) {
      w.m.uniforms.uI.value = base * 1.15;
      // the wingtip's stroke is a smear only while the wings beat
      w.am.uniforms.uI.value = base * 1.05 * clamp((flap - 0.45) * 2) * (0.5 + 0.5 * dark);
      w.am.uniforms.uT.value = clock;
    }
    this.tail.m.uniforms.uI.value = base * 0.85;
    this.beacon.m.uniforms.uI.value = (0.15 + st * (0.9 + 1.4 * dark)) * k;
    // the lamp: for dusk and the dark, when flying
    const lampK = sseg(dark, 0.25, 0.7) * k * (flying ? 1 : 0.4);
    this.lamp.m.uniforms.uI.value = (0.12 * k + 0.9 * lampK);
    this.beamMat.uniforms.uI.value = lampK * (0.85 + 0.15 * Math.sin(clock * 9));
    // the light field: only when it is dark enough to read as light
    const g = sseg(dark, 0.12, 0.7) * k;
    const bee = this.bee.group;
    for (const w of this.wingLights) {
      if (!w.src) continue;
      w.p.getWorldPosition(w.src.pos);
      w.src.color.copy(w.color).multiplyScalar(0.55 * g * (0.55 + 0.45 * flap));
    }
    this.tail.p.getWorldPosition(this.tailSrc.pos);
    this.tailSrc.color.copy(WHITE).multiplyScalar(0.28 * g);
    this.beacon.p.getWorldPosition(this.beaconSrc.pos);
    this.beaconSrc.color.copy(WHITE).multiplyScalar(1.6 * g * st);
    // the lamp's pool, a little ahead of the bee along where it faces
    this.lamp.p.getWorldPosition(this._w);
    this._f.set(1, -0.12, 0).applyQuaternion(bee.getWorldQuaternion(this._q)).normalize();
    this.lampSrc.pos.copy(this._w).addScaledVector(this._f, 11);
    this.lampSrc.color.copy(WARM).multiplyScalar(0.9 * lampK * sseg(dark, 0.25, 0.8));
  }
}
