import * as THREE from 'three';
import { TimeOfDay, STOPS, todFromClock } from './timeofday.js';
import { save } from './save.js';
import { Bounds } from './bounds.js';
import { BeeActor, SPEED } from './actor.js';
import { Pilot } from './pilot.js';
import { ChaseCam, FollowCam, PhotoCam, lookDir } from './cameras.js';
import { Growth } from './growth.js';
import { Bellflowers } from './bells.js';
import { Interactions } from './interactions.js';
import { Ambient } from './ambient.js';
import { Scenery, GARDEN, POND, AXIS_X, OUT } from './scenery.js';
import { LookUpgrade, FADE, GLOW } from './upgrade.js';
import { Night } from './night.js';
import { Fountain } from './fountain.js';
import { Weather } from './rain.js';
import { Outside } from './outside.js';
import { Pond, WATER_Y } from './pond.js';
import { Birds } from './birds.js';
import { NightFlies } from './nightflies.js';
import { Dragonflies } from './dragonflies.js';
import { BeeShadow } from './beeshadow.js';
import { Gardenscape } from './gardenscape.js';
const NOBEE = typeof location !== 'undefined' && /[?&]nobee=1/.test(location.search); // (an A/B switch for the performance gate: leaves the bee's shadow and its reflection out)
import { BeeLights } from './beelights.js';
import { Outdoors } from './outdoors.js';
import { WetPath } from './wetpath.js';
import { ButterflyCloud } from './butterflies.js';
import { lightFieldAll, setLightField, LF } from '../world/lightfield.js';
import { DetailCull } from './cull.js';
import { NearField } from './nearfield.js';
import { applyPose } from '../direction/camera.js';
import { SUN_DIR, SUN_DEFAULT } from '../world/atmosphere.js';
import { keyDirection, hourOfTod, hourOfClock, azimuth, elevation } from '../world/sunpath.js';
import { WashTrail, setWash, setCamera, setPushers, setTime as setWindTime } from '../world/wind.js';
import { L } from '../world/layout.js';
import { MATRICES } from '../core/fastmatrix.js';
import { clamp, lerp, smooth, sseg } from '../core/ease.js';

// Interactive modes (fly / follow / photo). The garden is held in its fully
// awake state and runs on a free real-time clock that is separate from the
// film's timeline; the explore controller owns the camera, APX-9, ambient
// life, interactions and the lighting rig while it is active. Leaving it
// hands everything back to the film, which re-derives its state from t.

const V = (x = 0, y = 0, z = 0) => new THREE.Vector3(x, y, z);
const WORLD_T0 = 70; // world clock offset: every film beat has played out
const TIMES = STOPS.map((s) => s.v); // T cycles midnight → dusk → dawn → golden hour
// the see-through window round a landed APX-9: its middle (above its feet) and radius there
const SIGHT_UP = V(0, 0.3, 0);
const SIGHT_R = 3.2;

export class Explore {
  constructor({ renderer, scene, world, pipeline, quality, mat, audio, sync = false }) {
    this.renderer = renderer;
    this.scene = scene;
    this.world = world;
    this.pipeline = pipeline;
    // (capture tools read the light meter back at once, so a still is exposed the same every time)
    if (sync) pipeline.lens.sync = true;
    this.quality = quality;
    this.audio = audio;
    this.camera = new THREE.PerspectiveCamera(50, 16 / 9, 0.05, 9000);
    this.tod = new TimeOfDay(renderer);
    this.clock = 0;
    this.active = false;
    this.aspect = 16 / 9;
    this.pixelRatio = 1;
    this.reduced = false;
    this.mode = 'follow';
    this.photo = false;
    this.group = new THREE.Group();
    this.group.name = 'explore';
    this.group.visible = false;
    scene.add(this.group);
    this.debugView = null;
    this.focus = { center: V(0, 20, 0), radius: 60 };
    this.frustum = new THREE.Frustum();
    this.listeners = {};

    // the flight volume and everything that lives in it
    this.bounds = new Bounds(world);
    const sk = world.skep;
    const out = V(0, 0, 1).applyQuaternion(sk.group.quaternion);
    this.skep = {
      board: world.creatures.beeBoard.clone(),
      inside: world.creatures.beeInside.clone(),
      entrance: sk.entranceWorld(),
      out,
      side: V(-out.z, 0, out.x),
    };
    this.upgrade = new LookUpgrade(world, quality, mat);
    this.group.add(this.upgrade.group);
    // the living fountain: moving water, wake rings, caustic light on the stone
    this.fountain = new Fountain({ world, upgrade: this.upgrade, quality });
    // weather (off until asked for): overcast, rain outside the glass, droplets on it, thunder
    this.weather = new Weather({ quality, group: this.group, audio });
    this.scenery = new Scenery(mat, quality, world, this.bounds, this.upgrade);
    this.group.add(this.scenery.group);
    // what lies beyond the glass: shadows that follow the sun, a manor, a temple, gates, lamps, borders
    this.outside = new Outside({ scenery: this.scenery, quality });
    this.group.add(this.outside.group);
    // the garden is flyable: its wall as the soft edge, the trees, the temple and the pool as solids (bounds.js)
    this.bounds.setOutdoors({
      garden: GARDEN, pond: POND, temple: { x: AXIS_X, z: -2440 },
      trees: this.scenery.treeInfo.filter((t) => t.x > GARDEN.x0 + 40 && t.x < GARDEN.x1 - 40 && t.z > GARDEN.z1 + 40 && t.z < GARDEN.z0 - 40),
    });
    // (capture and review tools always start from a fresh garden)
    if (sync) save.off();
    const saved = save.get();
    this.growth = new Growth(mat, quality, this.bounds);
    this.group.add(this.growth.group);
    this.growth.registerLandables(this.bounds);
    // a returning visitor's garden: the beds they grew stand grown from the first frame
    this.growth.grow(saved.grown);
    this.finished = saved.finished || this.growth.grownCount >= this.growth.sites.length;
    this.finale = null;
    this.live = false;
    this.sunMorning = false; // the sun's morning branch (the finale's sunrise)
    this._sunH = undefined; // the solar hour the sun is at (eased)
    this.bells = new Bellflowers(mat, this.bounds);
    this.group.add(this.bells.group);
    // bee-scale planting: every leaf grown again at APX-9's scale, clear of everything
    // (grown a few ms a frame from boot: stepNearfield(); synchronously for capture tools)
    this.nearfield = new NearField({ world, bounds: this.bounds, quality, growth: this.growth, bells: this.bells, scenery: this.scenery });
    this.nearfield.onReady = (nf) => {
      if (this.upgrade.fernMatIn) nf.setFernMaterial(this.upgrade.fernMatIn);
      if (this.upgrade.palmMatIn) nf.setPalmMaterial(this.upgrade.palmMatIn);
      // dissolve the film's foliage into the bee-scale planting over ~0.6 s (at once if nobody is looking)
      this.swapFade = { k: 0 };
      if (!this.active || sync) this._finishSwap();
    };
    FADE.uSwapK.value = 0;
    this.group.add(this.nearfield.group);
    this.interactions = new Interactions({ world, mat, quality, bounds: this.bounds, growth: this.growth, bells: this.bells, audio, emit: (n, d) => { if (n === 'kindle' && this.stats) this.stats.lanterns++; this._emit(n, d); } });
    this.group.add(this.interactions.group);
    this.interactions.honey = saved.deposits;
    this.ambient = new Ambient({ world, mat, quality, bounds: this.bounds, audio, skep: this.skep });
    this.group.add(this.ambient.group);
    // a night that glows: the light field, kindling, haloes, glowing blooms, fireflies
    this.night = new Night({ world, quality, mat, upgrade: this.upgrade, interactions: this.interactions, growth: this.growth, bells: this.bells, group: this.group });
    // APX-9's navigation lights (red and green wingtips, a white tail, a strobe, a lamp at dusk): the film's rig is the same one,
    // so they show only while exploring
    this.beeLights = new BeeLights({ bee: world.creatures.hero, field: this.night.field, quality });
    this.beeLights.setOn(saved.lights !== false);
    // hundreds of butterflies by day
    this.butterflies = new ButterflyCloud({ world, quality });
    this.group.add(this.butterflies.group);
    // the wet path that mirrors every lamp at night
    this.wet = new WetPath({ renderer, world, upgrade: this.upgrade, night: this.night, quality });
    // the reflecting pool on the west lawn: still water that mirrors the land, lilies, reeds, ducks
    // (built after the lights so its mirror pass can see them)
    this.pond = new Pond({ scenery: this.scenery, outside: this.outside, world, scene, quality });
    // the garden's furnishings: walks, beds, a pergola, benches, a sundial, a bronze bee (built after the pool, so that what stands by the water is what it reflects)
    this.gardenscape = new Gardenscape({ scenery: this.scenery, outside: this.outside, bounds: this.bounds, quality });
    this.group.add(this.gardenscape.group);
    this.gardenscape.poolside.traverse((o) => o.layers.enable(1));
    this._outdoorLandables();
    { const det0 = quality.tier === 'low' ? 0 : 1; OUT.uDetail.value = det0; if (this.scenery.grassU) this.scenery.grassU.value = det0; } // (the close-range detail: off from the start on `low`)
    this.group.add(this.pond.group);
    // birds crossing the sky: geese in formation, swallows over the lawns and the water, a murmuration at dusk
    this.birds = new Birds({ scenery: this.scenery, quality });
    this.group.add(this.birds.group);
    // what it sounds like out there (silent until sound is on): wind, water, ducks, geese, swallows, songbirds, frogs, crickets, an owl
    // and over the pool: fireflies at night (reflected in it), dragonflies by day
    this.nightflies = new NightFlies({ quality });
    this.group.add(this.nightflies.group);
    this.dragonflies = new Dragonflies({ scenery: this.scenery, quality });
    this.group.add(this.dragonflies.group);
    this.beeShadow = new BeeShadow();
    this.group.add(this.beeShadow.mesh);
    this.outdoors = new Outdoors({ audio, pond: this.pond, birds: this.birds, dragonflies: this.dragonflies });
    this._bee = { pos: null, flying: false };
    this.upgrade.swap(world.sky.mesh, 'material', world.sky.exploreMaterial);
    // every lit material in the house takes the light field while exploring
    const extra = this.upgrade.swaps.filter((x) => x.prop === 'material').map((x) => x.explore);
    extra.push(this.upgrade.fernMat, this.upgrade.fernMatIn, this.upgrade.palmMatIn, this.nearfield.matLeaf, this.nearfield.matIvy, this.nearfield.coreMat);
    lightFieldAll([scene], extra, quality.tier === 'low' ? 4 : 8);
    this.lf = LF; // (review hooks: __cg.explore().lf)
    if (sync) this.nearfield.finish();
    this.bells.onRing = (b, k) => {
      this.audio?.bell(b.note, 0.045 * k, clamp((b.pivot.x - this.camera.position.x) * 0.02, -0.8, 0.8));
      this.stats.bells++;
      this._emit('bell', b);
    };

    const w = world;
    this.cull = new DetailCull([w.flower.group, w.crown.group, w.escapement.group, w.roots.group, w.skep.group, w.pods.group, w.lily.group, w.blossom.group, w.reed.group, w.tree.group, w.garden.group, this.bells.group]);
    for (const c of this.ambient.group.children) this.cull.addGroup(c, 3);
    this.actor = new BeeActor({ bee: world.creatures.hero, bounds: this.bounds, skep: this.skep, events: (n, d) => this._actorEvent(n, d) });
    // APX-9's recent path (explore clock) for the wing-wash on the foliage
    this.trail = new WashTrail();
    this.wash = { reset: () => this.trail.reset(), record: (t, a) => this.trail.record(t, a.pos, this._wing()) };
    this.pilot = new Pilot({ bounds: this.bounds, world, skep: this.skep });
    this.chase = new ChaseCam(this.bounds);
    this.follow = new FollowCam(this.bounds);
    this.photoCam = new PhotoCam(this.bounds);
    this.view = { pos: V(), target: V(), fov: 50, roll: 0, focus: 10, aperture: 0 };
    this.stats = { pollinated: 0, deposits: 0, winds: 0, lanterns: 0, bells: 0 };
    // start APX-9 on its landing board
    this.actor.place(this.skep.board.clone(), Math.atan2(out.x, out.z), 'fly');
    this.actor.state = 'walk-out';
    this.actor.seq = { dur: 0.01, from: this.skep.board.clone(), to: this.skep.board.clone() };
  }

  // where the bee can settle out in the garden: the pool's lilies (a flower gives a little pollen, a bare pad only a rest), the flower beds along the walks (pollen), the temple's statue and finial, the lamp posts
  _outdoorLandables() {
    const B = this.bounds;
    const add = (l) => B.addLandable({ outdoor: true, ...l });
    this._pondLandables = [];
    for (const [x, z, s] of this.pond.lotusSpots) this._pondLandables.push(add({ kind: 'lotus', name: 'the water lily', spot: V(x, WATER_Y + 0.5 + 0.28 * s * 2.2 + 0.7, z), radius: Math.max(3, 0.34 * s), pollen: 0.2 }));
    for (const [x, z, s] of this.pond.padSpots) this._pondLandables.push(add({ kind: 'pad', name: 'a lily pad', spot: V(x, WATER_Y + 0.35 + 1.1, z), radius: Math.max(3, 0.5 * s), pollen: 0 }));
    const G = GARDEN;
    const G0 = GARDEN;
    for (const b of (this.outside.beds || []).filter((q) => q.x > G0.x0 + 90 && q.x < G0.x1 - 90 && q.z > G0.z1 + 90 && q.z < G0.z0 - 90)) add({ kind: 'bed', name: 'a flower bed', spot: V(b.x, b.y + 0.8, b.z), radius: b.r, pollen: 0.15 });
    for (const f of this.gardenscape.landableSpots) add({ kind: 'bed', name: 'a garden flower', spot: V(f.x, f.y, f.z), radius: f.r, pollen: 0.15 });
    for (const p of (this.outside.perches || []).filter((q) => q.x > G.x0 + 90 && q.x < G.x1 - 90 && q.z > G.z1 + 90 && q.z < G.z0 - 90)) add({ kind: 'perch', name: p.name, spot: V(p.x, p.y + 1.2, p.z), radius: p.r, pollen: 0 });
  }

  on(name, fn) { (this.listeners[name] ||= []).push(fn); }
  _emit(name, data) { for (const fn of this.listeners[name] || []) fn(data, this); }

  _actorEvent(name, data) {
    if (name === 'touchdown') {
      this.interactions.touchdown(data, this.mode === 'fly' ? 'player' : 'apx9');
      if (data.kind !== 'pad' && data.kind !== 'perch' && !this.interactions._counted?.has(data.id)) {
        (this.interactions._counted ||= new Set()).add(data.id);
        this.stats.pollinated++;
        save.get().pollinated++;
        if (performance.now() - (this._flushAt || 0) > 8000) { this._flushAt = performance.now(); save.flush(); }
      }
    }
    if (name === 'deposit') {
      this.interactions.deposit(data.amount, this.mode === 'fly' ? 'player' : 'apx9');
      this.ambient.onDeposit();
      this.stats.deposits++;
      const sv = save.get();
      sv.deposits++;
      sv.grown = this.growth.grownCount;
      save.flush();
      if (!this.finished && this.growth.grownCount >= this.growth.sites.length) this._startFinale();
    }
    this._emit('actor', { name, data });
  }

  // ---- mode switching ------------------------------------------------------------------
  enter(mode) {
    const prev = this.mode;
    this.mode = mode;
    if (mode === 'fly' && this.pilot.excursion) { this.pilot.excursion = null; this.pilot.goal = null; this.pilot.route = null; } // (the player takes the bee: no trip is under way)
    if (!this.active) {
      this.active = true;
      MATRICES.skipHidden = true;
      this.group.visible = true;
      this.beeLights.setActive(true);
      const C = this.world.creatures;
      if (!NOBEE) this.pond.mirrorBee(C.hero.group, true);
      // hide the film's cast; APX-9 stays (the explore controller drives it)
      for (const c of C.group.children) c.visible = c === C.hero.group;
      C.hero.group.visible = true;
      this.world.setFarShadows(false);
      this.cull.begin();
      // remember the practical lights' film settings
      const Lg = this.world.lighting;
      this._lightSave = ['pulse', 'skep', 'spark', 'fill'].map((k) => [k, Lg[k].color.clone(), Lg[k].distance, Lg[k].decay]);
      // the film's sculpting beam: no shadow pass while exploring (but its map
      // must exist: materials sample it, and the film may not have run yet)
      this.world.lighting.beam.shadow.autoUpdate = false;
      if (!this.world.lighting.beam.shadow.map) this.world.lighting.beam.shadow.needsUpdate = true;
      this.interactions.install();
      this.upgrade.apply(true);
      this.pipeline.scenePass.material.uniforms.uSteps.value = this.quality.tier === 'high' ? 36 : Math.min(30, this.quality.dofSteps);
      this.world.atmosphere.shaftUniforms.uInside.value = 1;
      this.world.atmosphere.shaftUniforms.uNear.value.set(60, 300);
      this.follow.reset(this.actor);
      setLightField(true);
    }
    if (mode === 'fly' && prev !== 'fly') {
      // take over from wherever APX-9 is, looking the way it faces
      this.chase.reset(this.actor, this.actor.yaw, -0.12);
      this.pilot.route = null;
      this.pilot.goal = null;
    }
    if (mode === 'follow' && prev !== 'follow') {
      this.follow.reset(this.actor);
      this.pilot.route = null;
      this.pilot.goal = null;
    }
  }

  // compile every material's light-field variant in the background (parallel
  // shader compile), so flying somewhere new never hitches; main.js calls it
  // once the page is up and an interactive mode is showing
  // (without KHR_parallel_shader_compile a program compiles when first drawn, as before)
  compileAll() {
    if (this._compiled || !this.active) return;
    this._compiled = true;
    const r = this.renderer;
    if (!r.extensions.has('KHR_parallel_shader_compile')) return;
    // (for the scene pass's own target: compiled for the screen, every
    // program would be an output variant that is never drawn)
    const rt = r.getRenderTarget();
    r.setRenderTarget(this.pipeline.scenePass.rtA);
    r.compileAsync(this.scene, this.camera).catch(() => {});
    r.setRenderTarget(rt);
  }

  exit() {
    if (!this.active) return;
    this.active = false;
    MATRICES.skipHidden = false;
    this.photo = false;
    this.group.visible = false;
    this.beeLights.setActive(false);
    if (!NOBEE) this.pond.mirrorBee(this.world.creatures.hero.group, false);
    this.interactions.uninstall();
    this.upgrade.apply(false);
    this.cull.restore();
    const Lg = this.world.lighting;
    Lg.beam.shadow.autoUpdate = true;
    Lg.beam.shadow.needsUpdate = true;
    Lg.sun.shadow.autoUpdate = true;
    for (const [k, c, d, dc] of this._lightSave || []) { Lg[k].color.copy(c); Lg[k].distance = d; Lg[k].decay = dc; Lg[k].intensity = 0; }
    this.pipeline.scenePass.material.uniforms.uSteps.value = this.quality.dofSteps;
    this.world.atmosphere.shaftUniforms.uInside.value = 0;
    this.world.atmosphere.shaftUniforms.uNear.value.set(25, 190);
    this.night.exit();
    this._restoreSun();
    setPushers([]);
    FADE.uSightK.value.x = 0;
    this.world.flora.view = null;
    setLightField(false);
    if (this.swapFade) this._finishSwap();
    // the film re-derives creature visibility and every world state from t
  }

  // spawn for a fresh flight: hovering just out of the skep, facing the bloom
  spawnAtSkep() {
    const s = this.skep;
    const p = s.board.clone().addScaledVector(s.out, 9).add(V(0, 4, 0));
    const head = this.world.flower.head.getWorldPosition(V());
    const yaw = Math.atan2(head.x - p.x, head.z - p.z);
    this.actor.place(p, yaw, 'fly');
    this.chase.reset(this.actor, yaw, -0.08);
  }

  get worldTime() { return WORLD_T0 + this.clock; }

  // the hour glides to its new value (TimeOfDay.step); `tod.value = x` jumps
  // (choosing an hour yourself ends anything that was moving it: the clock, the finale's day)
  setTime(v) {
    this._cancelAuto();
    this.tod.target = clamp(v, 0, 1);
    this._emit('time', this.tod.target);
  }

  // rain on or off (the menu, `R`, ?rain=1); it builds over a few seconds and clears more slowly
  // APX-9's navigation lights (L or the menu)
  setLights(on, { persist = true } = {}) {
    on = !!on;
    this.beeLights.setOn(on);
    if (persist) save.set({ lights: on });
    this._emit('lights', on);
  }

  // snow (N or the menu), fog (V): never together with rain or with each other
  setSnow(on, { jump = false } = {}) {
    on = !!on;
    const rainWas = this.weather.on, fogWas = this.weather.fogOn;
    this.weather.setSnow(on, jump);
    if (on && rainWas) this._emit('rain', false);
    if (on && fogWas) this._emit('fog', false);
    this._emit('snow', on);
  }

  setFog(on, { jump = false } = {}) {
    on = !!on;
    const rainWas = this.weather.on, snowWas = this.weather.snowOn;
    this.weather.setFog(on, jump);
    if (on && rainWas) this._emit('rain', false);
    if (on && snowWas) this._emit('snow', false);
    this._emit('fog', on);
  }

  setRain(on, { jump = false } = {}) {
    on = !!on;
    const snowWas = this.weather.snowOn, fogWas = this.weather.fogOn;
    this.weather.set(on);
    if (on && snowWas) this._emit('snow', false);
    if (on && fogWas) this._emit('fog', false);
    if (on) this.weather.nextBolt = 6;
    if (jump) { this.weather.k = on ? 1 : 0; this.weather.wet = on ? 1 : 0; }
    this._emit('rain', on);
  }

  // The key light's place for the hour: the sun along its path (the moon by night), moved in place so
  // the sky, the beams, the shadows, the iron's cookie (and the stained pools in it) and the
  // reflections all follow. The solar hour is eased, so a jump of the hour sweeps the sun through the sky.
  _moveSun(dt) {
    const d = this.tod.value;
    const target = this.live ? hourOfClock() : hourOfTod(d, this.sunMorning);
    if (dt <= 0 || this._sunH === undefined) this._sunH = target;
    else this._sunH += (target - this._sunH) * (1 - Math.exp(-dt / 0.6));
    const T = keyDirection(d, this._sunH, this._T ||= new THREE.Vector3());
    SUN_DIR.copy(T).negate();
    LF.u.cgToL.value.copy(T);
    this.world.sky.uniforms.uSunDir.value.copy(T);
    this.world.atmosphere.setSun(SUN_DIR);
    this.tod.sunEl = elevation(T);
    // the reflections: their maps hold the sun where the afternoon path puts it at their hour; turn them to meet the actual one
    const Te = keyDirection(d, hourOfTod(d, false), this._Te ||= new THREE.Vector3());
    this.scene.environmentRotation.y = azimuth(T) - azimuth(Te);
  }

  // the film's sun again
  _restoreSun() {
    SUN_DIR.copy(SUN_DEFAULT);
    LF.u.cgToL.value.copy(SUN_DEFAULT).negate();
    this.world.sky.uniforms.uSunDir.value.copy(SUN_DEFAULT).negate();
    this.world.atmosphere.setSun(SUN_DEFAULT);
    this.scene.environmentRotation.y = 0;
    this._sunH = undefined;
  }

  // the hour follows the viewer's own clock (read every few seconds; the hour glides to it)
  setLive(on, { jump = false, persist = true } = {}) {
    on = !!on;
    if (on && this.finale?.cycle) { this.finale.cycle = false; this.finale.cycleDone = true; }
    this.live = on;
    this._liveAt = -1e9;
    if (on && jump) { this.tod.value = todFromClock(); this._emit('time', this.tod.value); }
    if (persist) save.set({ live: on });
    this._emit('live', on);
  }

  _cancelAuto() {
    if (this.finale?.cycle) { this.finale.cycle = false; this.finale.cycleDone = true; }
    if (this.live) { this.live = false; save.set({ live: false }); this._emit('live', false); }
  }
  cycleTime() {
    const v = this.tod.target;
    const i = TIMES.findIndex((x) => x > v + 0.02);
    const stop = STOPS[i < 0 ? 0 : i];
    this.setTime(stop.v);
    this._emit('hint', stop.name);
  }

  // the bee-scale planting has dissolved in: the film's foliage it replaces goes
  _finishSwap() {
    this.swapFade = null;
    FADE.uSwapK.value = 1;
    this.upgrade.replace();
    if (this.scenery.endDomes) this.scenery.endDomes.visible = false;
  }

  // the frame governor's main-thread levels (render/governor.js): 1 redraws
  // the key light's shadow map every other frame (its matrix is kept with the
  // map, so still shadows stay exact; swaying ones move at half rate), 2 also
  // culls small details and creature parts a little sooner, 3 sooner still
  setPerfLevel(level) {
    this.perfLevel = level;
    this.weather.setPerfLevel(level);
    this.pond.on = level < 2; // (the pool's mirror pass is among the first things to go)
    this.nightflies.setPerfLevel(level);
    // the garden's close-range detail (the grass and daisies, the hedges' leaves, the bark) and the lamps' light are the first things a struggling device gives up: off from level 2, and never on `low`
    const det = this.quality.tier !== 'low' && level < 2 ? 1 : 0;
    OUT.uDetail.value = det;
    if (this.scenery.grassU) this.scenery.grassU.value = det;
    this.scenery.lampCap = [7, 7, 4, 2][level];
    this.gardenscape?.setLevel(level);
    this.cull.pixels = [3, 3, 5, 8][level];
    this.cull.shadowPixels = [5, 5, 10, 16][level];
    this.cull.partPixels = [1.1, 1.1, 2, 3][level];
    if (level < 1) this.world.lighting.sun.shadow.autoUpdate = true;
  }

  togglePhoto(on = !this.photo) {
    this.photo = on;
    if (on) this.photoCam.from(this.view);
    this._emit('photo', on);
  }

  // ---- the finale ---------------------------------------------------------------------------------
  // The twelfth bed grows: the whole house answers with a bloom wave, the title
  // card rises, and the day turns once (sunset, the lanterns' night, a golden
  // morning). Choosing an hour yourself (T, the slider, the clock) ends the day's turning.
  _startFinale() {
    this.finished = true;
    save.set({ finished: true, grown: this.growth.grownCount });
    this.finale = { t0: this.clock, wave: false, banner: false, cycle: false, cycleDone: false, cycleT: 0, tod0: this.tod.target, path: null };
  }

  _finaleUpdate(dt) {
    const f = this.finale;
    if (!f) return;
    const t = this.clock - f.t0;
    // the wave goes out once the last bed is unfurling (it waits if the garden was only just wound)
    if (!f.wave && t > 5.5 && (this.interactions.windUp('finale') || t > 40)) {
      f.wave = true;
      this.audio?.chord([62, 69, 74, 78, 81, 86], 0.035, 0.16);
      this._emit('finale', { phase: 'wave' });
    }
    if (f.wave && !f.banner && t > 9.5) {
      f.banner = true;
      const sv = save.get();
      this._emit('finale', { phase: 'banner', beds: this.growth.sites.length, deposits: sv.deposits, pollinated: sv.pollinated, winds: sv.winds });
    }
    if (f.banner && !f.cycle && !f.cycleDone && t > 15) {
      f.cycle = true;
      f.cycleT = 0;
      f.tod0 = this.tod.value;
      // by day: down through dusk to the lanterns' night, then a golden morning; by night: straight to the morning
      f.path = f.tod0 > 0.45 ? [[16, 0], [10, 0], [26, 0.86]] : [[4, f.tod0], [26, 0.86]];
      f.upAt = f.tod0 > 0.45 ? 26 : 4; // (when the morning begins: the sun then rises in the east)
      this.live = false;
    }
    if (f.cycle) { f.cycleT += dt; this.sunMorning = f.cycleT >= f.upAt; }
    else if (this.sunMorning) this.sunMorning = false;
  }

  // the finale's hour at its time (null once the day has turned)
  _finaleTod() {
    const f = this.finale;
    let t = f.cycleT, from = f.tod0;
    for (const [d, to] of f.path) {
      if (t <= d) return lerp(from, to, sseg(t, 0, d));
      t -= d;
      from = to;
    }
    return null;
  }

  // ---- per frame -------------------------------------------------------------------------------------
  // input: a frame from Input (or null when no interaction, e.g. under the landing screen)
  update(dt, input) {
    dt = Math.min(dt, 1 / 20);
    const simDt = this.photo ? 0 : dt;
    this.clock += simDt;
    const a = this.actor;
    // intent
    let intent = { vel: V(), face: null, boost: false, lift: 0 };
    if (this.photo) {
      // the world holds still for the photographer
    } else if (this.mode === 'fly' && input) {
      intent = this._playerIntent(input);
    } else if (this.mode !== 'fly') {
      this._excursion(a);
      const ex = this.pilot.excursion;
      if (a.state === 'fly' && this.bounds.isOutside(a.pos) && (!ex || ex.stage === 'return')) intent = this._homeward(a); // (it was flown out into the garden, then handed back: home through the north doors)
      else {
        this.pilot.buildOK = this.nearfield.ready;
        intent = this.pilot.step(simDt, a, { isPollinated: (l) => this.interactions.isPollinated(l), wind: (s) => this.interactions.windUp(s), windBusy: () => this.interactions.windBusy() });
      }
    }
    // the first time it flies out into the garden
    {
      const out = this.mode === 'fly' && this.bounds.isOutside(a.pos);
      if (out && !this._wasOut && !this._outHint) { this._outHint = true; this._emit('hint', 'Out in the garden: the pool is to the west, the temple to the south, the manor beyond the north gate'); }
      this._wasOut = out;
    }
    if (simDt > 0) a.step(simDt, intent);
    a.apply(this.reduced);
    if (simDt > 0) this.trail.record(this.clock, a.pos, this._wing());
    // triggers the bee can set off by flying into things
    if (simDt > 0) this._triggers();
    if (simDt > 0) this._finaleUpdate(simDt);
    this._dt = simDt;
    this._input = input;
  }

  // how hard the wings are working (the wash): beating wings, a little from the body when still
  _wing() {
    const a = this.actor;
    return clamp(0.25 + 0.75 * (a.flap ?? 1));
  }

  // Follow's own trips into the garden: now and then, when it is flying about the house and the weather is kind, APX-9 goes out by the north doors to the pool, settles on a water lily for a while and
  // comes home (pilot.startExcursion); a few minutes between. A watchdog turns it round if it has been out too long.
  _excursion(a) {
    const P = this.pilot, ex = P.excursion;
    if (!ex) {
      this._exAt ??= this.clock + 70;
      if (this.mode === 'follow' && !this.photo && this.clock > this._exAt && this.nearfield.ready && a.state === 'fly' && !this.bounds.isOutside(a.pos) && this.weather.k < 0.3 && this.weather.snow < 0.3 && !this.finale?.cycle) {
        // where to: the pool's lilies; a flower bed or a lamp's cap along the north avenue (by night, the lamps, which are lit)
        const L2 = this.bounds.landables, pick = (list) => list[Math.floor(Math.random() * list.length)];
        const av = (l) => l.enabled !== false && Math.abs(l.spot.x - AXIS_X) < 110 && l.spot.z > 330 && l.spot.z < 1100;
        const night = OUT.uNight.value > 0.5 || this.weather.overcast > 0.5;
        const r = Math.random();
        const kind = night ? (r < 0.62 ? 'lamp' : r < 0.82 ? 'temple' : 'lotus') : r < 0.42 ? 'lotus' : r < 0.7 ? 'bed' : r < 0.88 ? 'lamp' : 'temple';
        let dest = null, where = 'the pool';
        if (kind === 'lamp') { const c = L2.filter((l) => l.kind === 'perch' && l.name === 'a lamp post' && av(l)); if (c.length) { dest = pick(c); where = 'the lamps'; } }
        else if (kind === 'temple') { const c = L2.filter((l) => l.kind === 'perch' && l.name === "the temple's copper finial"); if (c.length) { dest = c[0]; where = 'the temple'; } }
        else if (kind === 'bed') { const c = L2.filter((l) => l.kind === 'bed' && av(l)); if (c.length) { dest = pick(c); where = 'the flower beds'; } }
        if (!dest) { const c = L2.filter((l) => l.kind === 'lotus' && l.enabled !== false); if (c.length) dest = pick(c); }
        if (dest) {
          P.startExcursion(dest, where);
          P.excursion.t0 = this.clock;
        }
        this._exAt = this.clock + 240 + Math.random() * 120;
      }
      return;
    }
    if (ex.t0 === null) ex.t0 = this.clock;
    if (ex.stage !== 'return' && this.clock - ex.t0 > (ex.limit ?? 170)) { ex.stage = 'return'; P.goal = null; P.route = null; } // (stuck or slow: home)
    if (ex.stage === 'return' && !this.bounds.isOutside(a.pos) && a.pos.z < 225) { P.excursion = null; P.goal = null; P.route = null; }
    if (a.state === 'landed' && ex.stage === 'return') P.status = 'resting on a water lily';
  }

  // the autopilot's way home from the garden: through the north doors (over the roof first if it is west, east or south of the house)
  _homeward(a) {
    const p = a.pos, vel = this._homeV || (this._homeV = V());
    let tgt;
    if (p.z > 240 && Math.abs(p.x - 70) < 32 && p.y < 138) tgt = this._t1 || (this._t1 = V(70, 78, 120)); // lined up with the doorway: straight in
    else if (p.z > 262) tgt = (this._t2 ||= V(70, 90, 345)); // north of the house: line up with the door
    else if (p.z < -1000 && p.z > -3000 && Math.abs(p.x - 70) < 260) tgt = (this._t7 ||= V(70, 200, -950)); // down at the temple: back up the south avenue, over its hedges
    else if (p.z < L.house.z1 - 40 && p.z > -3000) tgt = (this._t6 ||= V(390, 130, L.house.z1 + 30)); // south of the house: up its east side, low
    else if ((p.x < L.house.x0 - 20 || p.x > L.house.x1 + 20) && p.z < 262) tgt = p.x < 0 ? (this._t4 ||= V(-340, 80, 335)) : (this._t5 ||= V(410, 80, 335)); // beside the house: round its north corner, low
    else if (p.y < 600) tgt = vel.set(p.x, 640, p.z).clone(); // elsewhere (south of it): up over the ridge
    else tgt = (this._t3 ||= V(70, 640, 360)); // and across to the north side
    vel.copy(tgt).sub(p);
    const d = vel.length();
    vel.multiplyScalar(Math.min(48, 14 + d * 0.5) / Math.max(d, 1e-3));
    return { vel, face: null, boost: false, lift: 0 };
  }

  _playerIntent(input) {
    const a = this.actor;
    const c = this.chase;
    // the bee flies where you look: thrust along the view (left/right input
    // arrives as turning, so move.x is only non-zero from other sources)
    const f = lookDir(c.yaw, c.pitch * 0.85, V());
    const right = V(-Math.cos(c.yaw), 0, Math.sin(c.yaw));
    const boost = input.boost && input.move.y > 0.1;
    const sp = boost ? SPEED.boost : SPEED.cruise;
    const vel = f.multiplyScalar(input.move.y * sp).addScaledVector(right, input.move.x * sp * 0.75);
    vel.y += input.lift * SPEED.climb;
    if (a.state === 'landed' && a.stateT > 0.4 && (input.lift > 0.2 || Math.abs(input.move.y) > 0.3 || Math.abs(input.move.x) > 0.3)) {
      a.takeoff();
      if (!a.gather?.done) this._hud?.flashHint('Took off early — part of the pollen gathered', 2.5);
    }
    if (a.state === 'grounded' && input.lift > 0.2) vel.y = Math.max(vel.y, 8);
    // face the view direction (bees hover and strafe without turning)
    return { vel, face: c.yaw, boost, lift: input.lift };
  }

  _triggers() {
    const a = this.actor;
    if (a.busy) return;
    const p = a.pos;
    // the skep door
    const door = this.skep.entrance.clone().addScaledVector(this.skep.out, 1.2);
    const dDoor = p.distanceTo(door);
    if (dDoor < 6.5 && a.state === 'fly') {
      if (a.pollen > 0.05) { if (this.mode === 'fly') a.dock(); }
      else if (this.mode === 'fly' && (this._doorHint ?? -10) < this.clock - 6) { this._doorHint = this.clock; this._emit('hint', 'The skep is waiting for pollen: visit some blooms first'); }
    }
    // winding: touch the escapement
    const esc = L.escapement.clone().add(V(0, 1.2, 0));
    if (p.distanceTo(esc) < 6.5 && (this.mode === 'fly' || this.pilot.goal?.kind === 'wind')) {
      if (this.interactions.windUp(this.mode === 'fly' ? 'player' : 'apx9')) { this.stats.winds++; save.get().winds++; }
    }
    // settle on a bloom (fly mode: descend gently onto it)
    if (this.mode === 'fly' && a.state === 'fly') {
      const l = this.bounds.nearestLandable(p, 16);
      this.candidate = null;
      if (l) {
        const dh = Math.hypot(l.spot.x - p.x, l.spot.z - p.z);
        const dy = p.y - l.spot.y;
        const near = dh < l.radius + 2.5 && dy > -1.5 && dy < 9;
        if (near) this.candidate = l;
        const input = this._input;
        const descending = (input?.lift ?? 0) < -0.2 || a.vel.y < -1.5;
        const slow = a.speed < 18;
        if (near && slow && dh < l.radius + 0.8 && dy < 5 && (descending || (a.speed < 5 && dy < 3)) && (input?.lift ?? 0) <= 0.1) {
          a.land(l);
          this.candidate = null;
        }
      }
    } else this.candidate = null;
  }

  // ---- render ------------------------------------------------------------------------------
  render(dtReal = 1 / 60) {
    const t = this.worldTime;
    const fin = this.finale;
    if (fin?.cycle) {
      const v = this._finaleTod();
      if (v === null) { fin.cycle = false; fin.cycleDone = true; } else { this.tod.value = v; this._emit('time', v); }
    } else if (this.live && !this.photo) {
      const now = performance.now();
      if (now - (this._liveAt ?? 0) > 15000) { this._liveAt = now; this.tod.target = todFromClock(); }
    }
    this.tod.step(dtReal);
    this._moveSun(this.photo ? 0 : dtReal);
    if (this.swapFade) {
      this.swapFade.k += dtReal / 0.6;
      FADE.uSwapK.value = smooth(clamp(this.swapFade.k));
      if (this.swapFade.k >= 1) this._finishSwap();
    }
    const ctx = this.tod.context(t, this.pixelRatio);
    // weather: eased rain and lightning, then the hour's phases as the rain makes them (lamps lit, blooms glowing)
    this.weather.update(this.photo ? 0 : dtReal, this.clock, this.camera, this.reduced);
    this.tod.rain = this.weather.overcast; // (a snowy sky closes over too)
    this.tod.snow = this.weather.snow;
    this.tod.fog = this.weather.fog;
    this.tod.flash = this.weather.flash;
    const wild = clamp(this.weather.k + 1.5 * this.weather.snow + 0.55 * this.weather.fog); // (the birds and the insects keep indoors in rain, in snow and in the thick of fog)
    // a rainbow forms once the storm clears (opposite the sun): say where to look
    {
      const seen = this.weather.bow * sseg(this.tod.value, 0.32, 0.46) * (this.tod.sunEl > 2 && this.tod.sunEl < 40 ? 1 : 0);
      if (seen > 0.5 && !this._bowHint) { this._bowHint = true; this._emit('hint', 'A rainbow has formed: look away from the sun'); }
      else if (seen < 0.05) this._bowHint = false;
    }
    const phases = this.weather.phases(this.tod.phases());
    this.fountain.update(this.clock, { pos: this.actor.pos, speed: this.actor.speed }, phases);
    // light shafts thin out as the camera rises into them under the glazing
    ctx.shaftGain = (1 - 0.8 * clamp((this.camera.position.y - 190) / 150)) * (1 - 0.95 * this.weather.overcast) * (1 + 0.9 * this.weather.fog); // (no sun beams under rain or snow cloud; in fog they stand out in the air)
    const a = this.actor;
    const dt = this._dt ?? 0;
    const body = { pos: a.pos, vel: a.vel, speed: a.speed, flying: a.state === 'fly', yaw: a.yaw, landedOn: a.state === 'landed' || a.state === 'landing' ? (a.state === 'landed' ? a.lastLanding : a.seq?.landable) : null };
    // the breeze runs on the explore clock; APX-9's wash follows its trail
    setWindTime(t);
    const clock = this.clock;
    setWash((age, out) => this.trail.at(clock - age, out), a.pos, 1.9);
    this.interactions.pre(this.clock, dt, ctx, [body]);
    this.night.pre(ctx, phases, this.clock);
    this.world.flora.view = this.debugView || this.photo ? null : { camera: this.camera, frustum: this.frustum };
    this.world.update(t, ctx);
    this.world.lighting.baseSun = this.world.lighting.sun.intensity;
    this.growth.update(this.clock, body);
    this.bells.update(this.clock, dt, [body]);
    this.interactions.post(dt, [body], ctx, this.mode === 'fly' ? this.candidate : null);
    this.scenery.update(t, ctx, this.camera);
    this.outside.update(t, dt, { stormGlow: this.weather.overcast * 0.8, pixelRatio: this.pixelRatio, camera: this.camera });
    this.gardenscape.update(this.outside.duskK ?? 0, this.pixelRatio ?? 1, this.camera.position);
    this.pond.update(this.clock, dt, phases, { pos: a.pos, speed: a.speed });
    if (this._iceWas !== this.pond.iceOn) { this._iceWas = this.pond.iceOn; for (const l of this._pondLandables) l.enabled = !this.pond.iceOn; } // (under ice there are no pads to settle on)
    this.birds.update(this.clock, ctx.dawn, wild);
    this.nightflies.update(this.clock, phases, wild);
    this.dragonflies.update(this.clock, dt, ctx.dawn, wild, { pos: a.pos }, (k, x, z, c, am) => this.pond.ring(k, x, z, c, am));
    if (!NOBEE) this.beeShadow.update(a, this.bounds, !!this.debugView || this.mode !== 'fly' && !this.bounds.isOutside(a.pos));
    this._bee.pos = a.pos;
    this._bee.flying = a.state === 'fly';
    this.outdoors.update(this.photo ? 0 : dtReal, this.clock, { camera: this.camera, bee: this._bee, d: ctx.dawn, rain: this.weather.k, snow: this.weather.snow, fog: this.weather.fog, bow: this.weather.bow, outside: this.bounds.isOutside(this.camera.position) });
    // camera
    const input = this._input;
    let v;
    if (this.debugView) {
      const d = this.debugView;
      v = { pos: d.pos, target: d.target, fov: d.fov ?? 50, roll: 0, focus: d.pos.distanceTo(d.target), aperture: d.aperture ?? 0 };
    } else if (this.photo) v = this.photoCam.update(dtReal, input || this._noInput());
    else if (this.mode === 'fly') v = this.chase.update(dtReal, a, input, this.reduced);
    else v = this.follow.update(dtReal, a, this.mode === 'follow' ? input : null, { outside: this.bounds.isOutside(a.pos), reduced: this.reduced, skep: this.skep, ambient: this.mode === 'follow' ? this.ambient : null, nearfield: this.nearfield, night: phases.night, weaving: !!this.pilot.route?.weave, goalDist: this.pilot.goal ? a.pos.distanceTo(this.pilot.goal.to) : 0, aspect: this.aspect, route: this.pilot.route, world: this.world });
    this.view = { pos: v.pos.clone(), target: v.target.clone(), fov: v.fov, roll: v.roll || 0, focus: v.focus, aperture: v.aperture };
    applyPose(this.camera, { pos: v.pos, target: v.target, fov: v.fov, roll: v.roll || 0 }, this.aspect, 0.05, 9000);
    this.weather.uniforms.uCam.value.copy(this.camera.position);
    // while APX-9 settles and gathers on a bloom, petals and leaves that come
    // between it and the lens are thinned where they cover it (upgrade.js);
    // so are any across a creature Follow cuts away to, while it holds on it
    const cut = this.mode !== 'fly' && !this.debugView && !this.photo && this.follow.cut?.phase === 'hold' ? this.follow.cut : null;
    const sightOn = !this.debugView && !this.photo && (cut || ((a.state === 'landing' || a.state === 'landed' || a.state === 'takeoff') && !(this.mode !== 'fly' && this.follow.subject)));
    const SK = FADE.uSightK.value;
    SK.x += ((sightOn ? 1 : 0) - SK.x) * (1 - Math.exp(-dtReal * (sightOn ? 6 : 4)));
    if (SK.x < 0.002) SK.x = 0;
    // (fading out, the window stays where its subject last was)
    const W = (this._sight ||= { p: new THREE.Vector3(), r: SIGHT_R, keep: 0.9 });
    if (sightOn) {
      if (cut) W.p.copy(cut.c.pos); else W.p.copy(a.pos).add(SIGHT_UP);
      W.r = cut ? cut.c.size * 1.1 : SIGHT_R;
      W.keep = cut ? cut.c.size * 0.4 : 0.9;
    }
    if (SK.x > 0) {
      this.camera.updateMatrixWorld();
      const sv = (this._sightV ||= new THREE.Vector3()).copy(W.p).applyMatrix4(this.camera.matrixWorldInverse);
      FADE.uSight.value.set(sv.x, sv.y, sv.z, W.r);
      SK.y = W.keep;
    }
    // the camera pushes the foliage aside (and nothing comes inside the lens)
    setCamera(this.camera.position, 5.5, 1.5, this.debugView || this.photo ? null : (this.mode !== 'fly' && this.follow.subject) || a.pos);
    this.nearfield.update(this.camera);
    this.frustum.setFromProjectionMatrix((this._projView || (this._projView = new THREE.Matrix4())).multiplyMatrices(this.camera.projectionMatrix, this.camera.matrixWorldInverse));
    this.cull.update(this.camera, this.renderer.getDrawingBufferSize(this._vp || (this._vp = new THREE.Vector2())).y, this.debugView || this.photo ? null : this.frustum);
    this.ambient.sightTarget = this.mode !== 'fly' ? this.follow.subject : null;
    if (dt > 0 || this.photo) setPushers(this.ambient.pushers(this.camera.position, 4));
    if (dt > 0) this.ambient.update(dt, body, this.camera, this.frustum);
    if (dt > 0) this.butterflies.update(dt, this.clock, 1 - phases.night, body, this.camera);
    // light: shadows round what we're looking at, practicals
    const fwd = this.camera.getWorldDirection(V());
    // (in a cutaway the shadows gather round the creature being shown)
    const subject = (this.mode !== 'fly' && this.follow.subject) || a.pos;
    const center = this.debugView ? v.target.clone() : subject.clone().lerp(this.camera.position, 0.3).addScaledVector(fwd, this.follow.subject && this.mode !== 'fly' ? 4 : 14);
    this.focus.center.copy(center);
    this.focus.radius = this.debugView?.shadowRadius ?? (this.quality.tier === 'low' ? 55 : 70);
    this.tod.apply(this.scene, this.world, this.focus, this.camera);
    LF.u.cgGoboK.value.w = this.clock; // (the clouds' drift)
    this._practicals(ctx);
    // the night: the light field's sources, haloes, glows, fireflies (after the camera is placed)
    this.camera.updateMatrixWorld();
    GLOW.uGlowT.value = this.clock;
    GLOW.uGlassGlow.value.set(1.0, 0.62, 0.32, 0.02 + 0.14 * phases.blooms);
    this.growth.petals.material.emissiveIntensity = 0.08 + 0.5 * phases.blooms;
    this.beeLights.update(this.clock, dtReal, { flap: a.flap, boost: a.boostK || 0, dark: Math.max(phases.night, phases.lamps * 0.7, this.weather.overcast * 0.5), flying: a.state === 'fly' });
    this.scenery.setPointLights(this.camera.position, this.outside.lampPos, this.outside.duskK ?? 0, this.beeLights.active ? this.beeLights : null, this.outside.extraLamps); // (the lamps and the bee's lights, on the land after dark)
    this.night.post(dt, this.camera, { pos: a.pos, vel: a.vel, speed: a.speed, boost: a.boostK || 0 }, this.pixelRatio, ctx);
    const look = { ...this.tod.look(), time: t, dt: this.photo ? 0 : dtReal, refract: this.weather.k > 0.02 || this.weather.fog > 0.02, sunDir: SUN_DIR, fade: this.mode !== 'fly' && !this.photo ? this.follow.fade : 0 };
    if (this.perfLevel >= 1 && !this.photo) {
      const sh = this.world.lighting.sun.shadow;
      sh.autoUpdate = false;
      sh.needsUpdate = (this._shadowFrame = (this._shadowFrame || 0) + 1) % 2 === 0;
    } else this.world.lighting.sun.shadow.autoUpdate = true;
    this.wet.set(phases);
    this.wet.render(this.scene, this.camera, this._vp.x, this._vp.y);
    this.pond.render(this.renderer, this.scene, this.camera, this.frustum, this._vp.x, this._vp.y);
    this.pipeline.render({ camera: this.camera, focus: v.focus, aperture: this.quality.dof ? v.aperture : 0 }, null, 0, look);
    // audio follows the bee
    if (this.audio?.enabled) {
      const near = 1 / (1 + Math.max(0, this.camera.position.distanceTo(a.pos) - 6) / 14);
      this.audio.frame({ flap: a.flap, speed: a.speed, boost: a.boostK, collect: a.collect || 0, near, tod: this.tod.value, rain: this.weather.k });
    }
  }

  // ---- interface state --------------------------------------------------------------------------
  hudState() {
    const a = this.actor;
    return {
      pollen: a.pollen,
      honey: this.interactions.honey,
      grown: this.growth.grownCount,
      total: this.growth.sites.length,
      arrow: this.mode === 'fly' && !this.photo && a.pollen > 0.3 && !a.busy ? this._arrow() : null,
      photo: this.photo,
      photoText: this.touch ? 'Photo mode · drag to look, joystick to move' : 'Photo mode · drag/WASD to frame · wheel to zoom · Enter saves · P exits',
      hint: this.photo ? '' : this.standingHint(),
    };
  }

  // a chevron at the screen edge pointing home to the skep when it's out of view
  _arrow() {
    const p = this.skep.entrance.clone().project(this.camera);
    const behind = this.camera.getWorldDirection(V()).dot(this.skep.entrance.clone().sub(this.camera.position)) < 0;
    if (!behind && Math.abs(p.x) < 0.92 && Math.abs(p.y) < 0.92) return null;
    let x = p.x, y = p.y;
    if (behind) { x = -x; y = -y; }
    const a = Math.atan2(-y, x);
    const w = window.innerWidth, h = window.innerHeight;
    const k = 1 / Math.max(Math.abs(x) / 0.86, Math.abs(y) / 0.8, 1e-3);
    return { x: (x * k * 0.5 + 0.5) * w - 14, y: (-y * k * 0.5 + 0.5) * h - 14, a };
  }

  standingHint() {
    const a = this.actor, s = a.state, touch = this.touch;
    if (this.mode !== 'fly') return this.follow.caption || (this.pilot.status ? `APX-9 is ${this.pilot.status}` : 'APX-9 is going about its day');
    if (s === 'landed') {
      if (a.lastLanding?.kind === 'pad' || a.lastLanding?.kind === 'perch') return `Perched on ${a.lastLanding.name}. ${touch ? 'Press ▲' : 'Space'} to take off`;
      if (a.gather && !a.gather.done) return 'Gathering pollen…';
      if (a.pollen > 0.97) return `Full. ${touch ? 'Press ▲' : 'Space'} to take off and carry it home to the skep`;
      return `Gathered. ${touch ? 'Press ▲' : 'Space'} to take off`;
    }
    if (s === 'grounded') return `Resting on the ground. ${touch ? 'Press ▲' : 'Space'} to fly`;
    if (s === 'docking' || s === 'walk-in' || s === 'inside') return 'Depositing pollen in the skep…';
    if (s === 'walk-out' || s === 'takeoff') return '';
    if (this.candidate) return `Settle on ${this.candidate.name}: ${touch ? 'press ▼ to' : 'descend gently to'} land`;
    if (this.bounds.isOutside(a.pos)) return `Out in the garden · ${touch ? 'Autopilot' : 'C'} sends APX-9 home through the north doors`;
    if (a.pollen > 0.97) return 'Your pollen baskets are full: carry them home to the skep';
    if (a.pollen > 0.3) return 'Carry the pollen home to the skep, or gather more';
    if (this.interactions.honey === 0 && this.stats.pollinated === 0) return 'Fly to a bloom and settle on it to gather pollen';
    const tips = [
      'Touch the escapement beside the great bloom to wind the garden',
      'Brush the porcelain bellflowers to ring them',
      touch ? 'The menu can bring the rain' : 'R brings the rain',
      'Fly through the armillary rings above the fountain',
      'The north doors stand open: fly out through them into the garden',
      'The lanterns under the vault kindle as you pass',
      'Fly fast down the path: the globes light up ahead of you',
      touch ? 'The menu changes the hour and takes photographs' : 'T changes the hour · P takes photographs',
      touch ? 'Autopilot hands APX-9 back to its day' : 'C hands APX-9 back to its autopilot',
    ];
    const slot = Math.floor(this.clock / 9);
    // until the garden has been wound, the escapement comes up two slots in three
    if (!this.stats.winds && !save.get().winds && slot % 3 !== 2) return tips[0];
    return tips[slot % tips.length];
  }

  _noInput() {
    return { move: { x: 0, y: 0 }, lift: 0, look: { dx: 0, dy: 0 }, orbit: { dx: 0, dy: 0 }, zoom: 1, boost: false, actions: [] };
  }

  _practicals(ctx) {
    const Lg = this.world.lighting;
    const a = this.actor;
    // the skep glows from its doorway
    Lg.skep.position.copy(this.skep.entrance).add(V(0, 0.5, 0)).addScaledVector(this.skep.out, 0.8);
    Lg.skep.intensity = (3.5 + (ctx.skepFlare || 0) * 10) * (1.2 - this.tod.value * 0.4);
    Lg.skep.distance = 26;
    // APX-9's pollen load casts a little amber on what it lands on
    Lg.fill.color.set('#ffb35a');
    Lg.fill.position.copy(a.pos).add(V(0, -0.6, 0));
    Lg.fill.intensity = a.pollen * 1.4 + (a.collect || 0) * 1.2;
    Lg.fill.distance = 7;
    Lg.fill.decay = 2;
    // every lantern, lamp and glow lights the garden through the light field
    // (night.js), so the old single nearest-lantern light is off
    Lg.spark.intensity = 0;
  }
}
