import { RNG } from '../core/rng.js';

// Live, synthesised sound for the interactive modes (the film keeps its
// pre-rendered score). Nothing plays until the viewer turns sound on.
//   wing buzz that follows wingbeat and speed · pollen-drum whirr ·
//   music-box bells (FM, as in the score) · escapement ticks by distance ·
//   ratchet and root swell when the garden is wound · a soft pad whose
//   chord follows the time of day · songbird chirps.
// And the world beyond the glass (driven by explore/outdoors.js): an outdoor bus that thins
// sounds with distance and dulls them through the glazing, voices for ducks, geese, swallows,
// songbirds, starlings, frogs, crickets and an owl, and beds for the wind in the trees, the
// pool's lapping and the reeds.

const N = (m) => 440 * Math.pow(2, (m - 69) / 12);
const clamp = (x, a, b) => (x < a ? a : x > b ? b : x);
const rnd = (a, b) => a + (b - a) * Math.random();

export class LiveAudio {
  constructor() {
    this.enabled = false;
    this.ctx = null;
  }

  async enable() {
    if (!this.ctx) this._build();
    if (this.ctx.state === 'suspended') await this.ctx.resume();
    this.enabled = true;
    const t = this.ctx.currentTime;
    this.master.gain.cancelScheduledValues(t);
    this.master.gain.setTargetAtTime(0.9, t, 0.25);
    return true;
  }

  disable() {
    this.enabled = false;
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    this.master.gain.cancelScheduledValues(t);
    this.master.gain.setTargetAtTime(0, t, 0.08);
  }

  async toggle() {
    if (this.enabled) { this.disable(); return false; }
    return this.enable();
  }

  _build() {
    const ctx = (this.ctx ||= new (window.AudioContext || window.webkitAudioContext)()); // (a context may be handed in: the tests render offline)
    const rng = new RNG('live-audio');
    this.master = ctx.createGain();
    this.master.gain.value = 0;
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -16; comp.ratio.value = 3; comp.attack.value = 0.01; comp.release.value = 0.25;
    this.master.connect(comp).connect(ctx.destination);
    // glasshouse reverb from decaying noise
    const len = Math.floor(ctx.sampleRate * 2.6);
    const ir = ctx.createBuffer(2, len, ctx.sampleRate);
    for (let c = 0; c < 2; c++) {
      const d = ir.getChannelData(c);
      for (let i = 0; i < len; i++) { const k = i / len; d[i] = (rng.float() * 2 - 1) * Math.pow(1 - k, 3) * (1 - Math.exp(-i / 250)); }
    }
    this.verb = ctx.createConvolver();
    this.verb.buffer = ir;
    const vg = ctx.createGain();
    vg.gain.value = 0.35;
    this.verb.connect(vg).connect(this.master);
    this.noiseBuf = ctx.createBuffer(1, ctx.sampleRate * 2, ctx.sampleRate);
    { const d = this.noiseBuf.getChannelData(0); for (let i = 0; i < d.length; i++) d[i] = rng.float() * 2 - 1; }

    // wing buzz: sawtooth + square octave through a lowpass, with vibrato
    const bz = (this.buzzNodes = {});
    bz.o1 = ctx.createOscillator(); bz.o1.type = 'sawtooth'; bz.o1.frequency.value = 180;
    bz.o2 = ctx.createOscillator(); bz.o2.type = 'square'; bz.o2.frequency.value = 361;
    bz.lfo = ctx.createOscillator(); bz.lfo.frequency.value = 7;
    bz.lfoG = ctx.createGain(); bz.lfoG.gain.value = 4;
    bz.lfo.connect(bz.lfoG); bz.lfoG.connect(bz.o1.frequency); bz.lfoG.connect(bz.o2.frequency);
    bz.g2 = ctx.createGain(); bz.g2.gain.value = 0.25;
    bz.f = ctx.createBiquadFilter(); bz.f.type = 'lowpass'; bz.f.frequency.value = 900; bz.f.Q.value = 3;
    bz.g = ctx.createGain(); bz.g.gain.value = 0;
    bz.o1.connect(bz.f); bz.o2.connect(bz.g2).connect(bz.f); bz.f.connect(bz.g);
    this._out(bz.g, 0.12, 0);
    bz.o1.start(); bz.o2.start(); bz.lfo.start();
    // pollen drum whirr
    const wh = (this.whirr = {});
    wh.src = ctx.createBufferSource(); wh.src.buffer = this.noiseBuf; wh.src.loop = true;
    wh.f = ctx.createBiquadFilter(); wh.f.type = 'bandpass'; wh.f.frequency.value = 2600; wh.f.Q.value = 6;
    wh.g = ctx.createGain(); wh.g.gain.value = 0;
    wh.src.connect(wh.f).connect(wh.g);
    this._out(wh.g, 0.3, 0);
    wh.src.start();
    // pad
    this.pad = [];
    for (let i = 0; i < 4; i++) {
      const o = ctx.createOscillator(); o.type = 'triangle';
      const o2 = ctx.createOscillator(); o2.type = 'triangle'; o2.detune.value = 7;
      const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 1100;
      const g = ctx.createGain(); g.gain.value = 0;
      o.connect(f); o2.connect(f); f.connect(g);
      this._out(g, 0.6, (i - 1.5) * 0.3);
      o.start(); o2.start();
      this.pad.push({ o, o2, g });
    }
    this._padChord = null;
    // garden air
    const air = ctx.createBufferSource(); air.buffer = this.noiseBuf; air.loop = true;
    const af = ctx.createBiquadFilter(); af.type = 'bandpass'; af.frequency.value = 5200; af.Q.value = 1.8;
    this.airG = ctx.createGain(); this.airG.gain.value = 0.004;
    air.connect(af).connect(this.airG);
    this._out(this.airG, 0.6, 0);
    air.start();
    // rain on the glass: a hiss and a slower patter (filtered noise), silent until it rains
    const rn = (this.rainNodes = {});
    rn.s1 = ctx.createBufferSource(); rn.s1.buffer = this.noiseBuf; rn.s1.loop = true;
    rn.f1 = ctx.createBiquadFilter(); rn.f1.type = 'highpass'; rn.f1.frequency.value = 3300;
    rn.f2 = ctx.createBiquadFilter(); rn.f2.type = 'lowpass'; rn.f2.frequency.value = 9500;
    rn.g1 = ctx.createGain(); rn.g1.gain.value = 0;
    rn.s1.connect(rn.f1).connect(rn.f2).connect(rn.g1);
    this._out(rn.g1, 0.4, 0);
    rn.s1.start();
    rn.s2 = ctx.createBufferSource(); rn.s2.buffer = this.noiseBuf; rn.s2.loop = true; rn.s2.playbackRate.value = 0.62;
    rn.f3 = ctx.createBiquadFilter(); rn.f3.type = 'bandpass'; rn.f3.frequency.value = 1500; rn.f3.Q.value = 0.8;
    rn.gm = ctx.createGain(); rn.gm.gain.value = 0.7;
    rn.lfo = ctx.createOscillator(); rn.lfo.frequency.value = 0.37;
    rn.lfoG = ctx.createGain(); rn.lfoG.gain.value = 0.3;
    rn.lfo.connect(rn.lfoG).connect(rn.gm.gain);
    rn.g2 = ctx.createGain(); rn.g2.gain.value = 0;
    rn.s2.connect(rn.f3).connect(rn.gm).connect(rn.g2);
    this._out(rn.g2, 0.5, 0);
    rn.s2.start(); rn.lfo.start();

    // beyond the glass: one bus for everything outdoors (the glazing dulls it, the house's reverb carries it)
    this.outBus = ctx.createGain();
    const glass = this.glass = ctx.createBiquadFilter(); glass.type = 'lowpass'; glass.frequency.value = 7200; glass.Q.value = 0.4;
    // (a soft clip first, linear below ~0.06 and never above ~0.12: a flock passing close overhead should not jump out of the mix.
    // Not a compressor node: those add make-up gain)
    const pre = ctx.createGain(); pre.gain.value = 4;
    this.outLim = ctx.createWaveShaper(); this.outLim.oversample = '2x';
    this.outLim.curve = Float32Array.from({ length: 2049 }, (_, i) => 0.125 * Math.tanh(2 * ((i / 1024) - 1)));
    this.outBus.connect(pre); pre.connect(this.outLim); this.outLim.connect(glass); glass.connect(this.master);
    const og = ctx.createGain(); og.gain.value = 0.45;
    glass.connect(og).connect(this.verb);
    // the world's beds: filtered noise, each with its own slow swell and place in the stereo field (levels set per frame)
    const beds = (this.beds = {});
    const mkBed = (name, rate, filters, trem = null) => {
      const src = ctx.createBufferSource(); src.buffer = this.noiseBuf; src.loop = true; src.playbackRate.value = rate;
      let n = src;
      for (const [type, f, q] of filters) { const b = ctx.createBiquadFilter(); b.type = type; b.frequency.value = f; b.Q.value = q; n.connect(b); n = b; }
      if (trem) {
        const gm = ctx.createGain(); gm.gain.value = 1 - trem.depth;
        const l = ctx.createOscillator(); l.frequency.value = trem.rate;
        const lg = ctx.createGain(); lg.gain.value = trem.depth;
        l.connect(lg).connect(gm.gain); l.start();
        n.connect(gm); n = gm;
      }
      const g = ctx.createGain(); g.gain.value = 0; n.connect(g);
      const p = ctx.createStereoPanner(); g.connect(p); p.connect(this.outBus);
      src.start();
      beds[name] = { g, p };
    };
    mkBed('wind', 0.55, [['lowpass', 1100, 0.5], ['bandpass', 420, 0.6]], { rate: 0.11, depth: 0.35 }); // the breeze in the crowns
    mkBed('leaves', 1.0, [['bandpass', 3400, 0.7]], { rate: 8.5, depth: 0.3 }); // the leaves' rustle
    mkBed('lap', 0.5, [['lowpass', 700, 0.7]], { rate: 0.42, depth: 0.45 }); // water at the pool's stone
    mkBed('trickle', 1.0, [['bandpass', 2300, 3.5]], { rate: 1.7, depth: 0.7 }); // its small tinkling
    mkBed('reeds', 1.0, [['highpass', 5500, 0.5]]); // reeds hissing in a gust
    mkBed('star', 1.3, [['bandpass', 3600, 0.8]], { rate: 6.2, depth: 0.5 }); // a murmuration's wings
    mkBed('dragon', 1.0, [['bandpass', 2900, 2.5]], { rate: 38, depth: 0.75 }); // a dragonfly's wings, a dry whirr
    mkBed('hush', 0.35, [['lowpass', 260, 0.5]], { rate: 0.17, depth: 0.35 }); // the hush of a snowfall: a very low, breathing murmur
  }

  _out(node, wet = 0.3, pan = 0) {
    const p = this.ctx.createStereoPanner();
    p.pan.value = pan;
    node.connect(p);
    p.connect(this.master);
    const s = this.ctx.createGain();
    s.gain.value = wet;
    p.connect(s).connect(this.verb);
    return p;
  }

  // per frame: wings and drum
  frame({ flap = 0, speed = 0, boost = 0, collect = 0, near = 1, tod = 0.8, rain = 0 }) {
    if (!this.enabled || !this.ctx) return;
    const t = this.ctx.currentTime;
    const bz = this.buzzNodes;
    const f0 = 165 + Math.min(speed, 70) * 1.5 + boost * 35;
    bz.o1.frequency.setTargetAtTime(f0, t, 0.05);
    bz.o2.frequency.setTargetAtTime(f0 * 2.005, t, 0.05);
    bz.f.frequency.setTargetAtTime(700 + speed * 22 + boost * 600, t, 0.05);
    bz.g.gain.setTargetAtTime(flap * (0.035 + Math.min(speed, 60) * 0.0006 + boost * 0.012) * near, t, 0.06);
    this.whirr.g.gain.setTargetAtTime(collect * 0.03 * near, t, 0.08);
    // pad chord drifts with the hour: midnight minor colour → golden major
    const chord = tod < 0.35 ? [38, 45, 53, 60] : tod < 0.7 ? [38, 45, 54, 61] : [38, 50, 57, 66];
    const key = chord.join();
    if (key !== this._padChord) {
      this._padChord = key;
      this.pad.forEach((v, i) => { v.o.frequency.setTargetAtTime(N(chord[i]), t, 1.2); v.o2.frequency.setTargetAtTime(N(chord[i]), t, 1.2); v.g.gain.setTargetAtTime(0.012, t, 2.5); });
    }
    this.airG.gain.setTargetAtTime(0.002 + tod * 0.004 * (1 - rain), t, 1);
    const rn = this.rainNodes;
    rn.g1.gain.setTargetAtTime(rain * 0.03, t, 0.9);
    rn.g2.gain.setTargetAtTime(rain * 0.05, t, 0.9);
  }

  bell(m, gain = 0.05, pan = 0, when = 0) {
    if (!this.enabled || !this.ctx) return;
    const ctx = this.ctx, t = ctx.currentTime + when;
    const car = ctx.createOscillator(); car.frequency.value = N(m);
    const mod = ctx.createOscillator(); mod.frequency.value = N(m) * 3.5;
    const mg = ctx.createGain();
    mg.gain.setValueAtTime(N(m) * 2.2, t);
    mg.gain.setTargetAtTime(0, t, 0.25);
    mod.connect(mg).connect(car.frequency);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(gain, t + 0.004);
    g.gain.setTargetAtTime(0, t + 0.004, 0.7);
    car.connect(g);
    this._out(g, 0.5, pan);
    car.start(t); mod.start(t);
    car.stop(t + 4); mod.stop(t + 4);
  }

  chord(notes, gain = 0.035, spread = 0.06) {
    notes.forEach((m, i) => this.bell(m, gain, (i / Math.max(1, notes.length - 1) - 0.5) * 0.6, i * spread));
  }

  _noise(t, dur, { freq = 3000, q = 6, gain = 0.2, decay = 0.006, type = 'bandpass', pan = 0, wet = 0.2, attack = 0.001, sp = null } = {}) {
    const ctx = this.ctx;
    const src = ctx.createBufferSource(); src.buffer = this.noiseBuf;
    const f = ctx.createBiquadFilter(); f.type = type; f.frequency.value = freq; f.Q.value = q;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(gain, t + attack);
    g.gain.setTargetAtTime(0, t + attack, decay);
    src.connect(f).connect(g);
    if (sp) this._outdoor(g, sp);
    else this._out(g, wet, pan);
    src.start(t, Math.random() * 1.5);
    src.stop(t + dur + decay * 8);
  }

  tick(tock, gain = 0.3, pan = -0.1) {
    if (!this.enabled || !this.ctx || gain < 0.005) return;
    const t = this.ctx.currentTime;
    this._noise(t, 0.012, { freq: tock ? 2400 : 3400, gain: gain * 0.5, pan });
    this._noise(t + 0.024, 0.006, { freq: 5200, q: 10, gain: gain * 0.15, decay: 0.004, pan });
  }

  ratchet(n = 14, gain = 0.25) {
    if (!this.enabled || !this.ctx) return;
    const t0 = this.ctx.currentTime;
    for (let i = 0; i < n; i++) this._noise(t0 + i * 0.055 * (1 - i / (n * 2.2)), 0.008, { freq: 2900 + (i % 3) * 180, q: 7, gain, decay: 0.005 });
  }

  swell(f0 = 110, f1 = 440, dur = 1.8, gain = 0.06) {
    if (!this.enabled || !this.ctx) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const o = ctx.createOscillator(); o.type = 'triangle';
    o.frequency.setValueAtTime(f0, t);
    o.frequency.exponentialRampToValueAtTime(f1, t + dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(gain, t + dur * 0.3);
    g.gain.linearRampToValueAtTime(0, t + dur + 0.4);
    o.connect(g);
    this._out(g, 0.5, 0);
    o.start(t); o.stop(t + dur + 0.5);
  }

  chirp(pan = 0, gain = 0.02) {
    if (!this.enabled || !this.ctx) return;
    const ctx = this.ctx;
    let t = ctx.currentTime;
    const n = 2 + Math.floor(Math.random() * 4);
    for (let i = 0; i < n; i++) {
      const o = ctx.createOscillator();
      const f0 = 2600 + Math.random() * 1600;
      o.frequency.setValueAtTime(f0, t);
      o.frequency.exponentialRampToValueAtTime(f0 * (1.2 + Math.random() * 0.4), t + 0.08);
      o.frequency.exponentialRampToValueAtTime(f0 * 0.9, t + 0.15);
      const g = ctx.createGain();
      g.gain.setValueAtTime(0, t);
      g.gain.linearRampToValueAtTime(gain, t + 0.015);
      g.gain.linearRampToValueAtTime(0, t + 0.16);
      o.connect(g);
      this._out(g, 0.6, pan);
      o.start(t); o.stop(t + 0.2);
      t += 0.12 + Math.random() * 0.1;
    }
  }

  // thunder: a crack, then a rolling rumble (after `delay` seconds, as the sound of a distant flash arrives)
  thunder(delay = 1, gain = 0.5) {
    if (!this.enabled || !this.ctx) return;
    const t = this.ctx.currentTime + delay;
    this._noise(t, 0.3, { freq: 950, q: 0.7, gain: gain * 0.22, decay: 0.06, type: 'bandpass', wet: 0.55, attack: 0.004 });
    for (let i = 0; i < 4; i++) {
      this._noise(t + i * 0.34 + Math.random() * 0.16, 3, { freq: 95 + i * 28, q: 0.6, gain: gain * (0.36 - i * 0.06), decay: 0.7 + i * 0.28, type: 'lowpass', wet: 0.7, attack: 0.07, pan: (i % 2 ? 0.3 : -0.3) });
    }
  }

  // ---- the world beyond the glass ------------------------------------------------------------------
  // the listener: the camera's place and which way is right on the ground (sounds are panned and thinned from it)
  listen(x, y, z, rx, rz) { this.L = { x, y, z, rx, rz }; }

  // a place in the world as the ear has it: pan; level (half at `ref` units, falling away beyond); and how dull the air has made it
  spatial(x, y, z, ref = 300) {
    const L = this.L || { x: 0, y: 0, z: 0, rx: 1, rz: 0 };
    const dx = x - L.x, dz = z - L.z, d = Math.hypot(dx, y - L.y, dz), h = Math.hypot(dx, dz) || 1;
    return {
      d,
      pan: clamp((dx * L.rx + dz * L.rz) / h, -1, 1) * Math.min(1, h / 60) * 0.85,
      gain: 1 / (1 + Math.pow(d / ref, 1.35)),
      lp: clamp(14000 * Math.exp(-d / 2200), 1100, 12000),
    };
  }

  // snow on the ground and in the air deadens the outdoors: the glazing's low-pass closes (0 clear … 1 muffled)
  muffle(k, open = 0) {
    if (!this.glass || !this.ctx) return;
    this.glass.frequency.setTargetAtTime(7200 + 8000 * open - 4900 * clamp(k, 0, 1), this.ctx.currentTime, 1.2);
  }

  // a bed's level and where it sits in the stereo field
  bed(name, gain, pan = 0) {
    const b = this.beds?.[name];
    if (!b || !this.ctx) return;
    const t = this.ctx.currentTime;
    b.g.gain.setTargetAtTime(gain, t, 0.7);
    b.p.pan.setTargetAtTime(clamp(pan, -1, 1), t, 0.5);
  }

  _outdoor(node, sp) {
    const lp = this.ctx.createBiquadFilter();
    lp.type = 'lowpass'; lp.frequency.value = sp.lp; lp.Q.value = 0.4;
    const p = this.ctx.createStereoPanner();
    p.pan.value = sp.pan;
    node.connect(lp); lp.connect(p); p.connect(this.outBus);
  }

  // one voiced note. contour: [[fraction of dur, Hz], ...] (exponential glides); partials: [[multiple, level], ...];
  // formants: [[Hz, Q, level], ...] shape a buzzy source into a throat; vib: depth in Hz at vibRate
  _note(t, { type = 'sine', contour, dur = 0.2, gain = 0.1, attack = 0.01, hold = 0.45, partials = null, formants = null, vib = 0, vibRate = 7, detune = 0, makeup = 1 }, sp) {
    const ctx = this.ctx;
    const env = ctx.createGain();
    env.gain.setValueAtTime(0, t);
    env.gain.linearRampToValueAtTime(gain * makeup, t + attack);
    env.gain.setTargetAtTime(0, t + attack + dur * hold, dur * 0.2);
    const mix = ctx.createGain();
    for (const [m, lv] of partials ? [[1, 1], ...partials] : [[1, 1]]) {
      const o = ctx.createOscillator();
      o.type = type; o.detune.value = detune;
      o.frequency.setValueAtTime(contour[0][1] * m, t);
      for (let i = 1; i < contour.length; i++) o.frequency.exponentialRampToValueAtTime(contour[i][1] * m, t + contour[i][0] * dur);
      if (vib) {
        const l = ctx.createOscillator(); l.frequency.value = vibRate;
        const lg = ctx.createGain(); lg.gain.value = vib * m;
        l.connect(lg).connect(o.frequency); l.start(t); l.stop(t + dur * 1.5 + 0.1);
      }
      const pg = ctx.createGain(); pg.gain.value = lv;
      o.connect(pg).connect(mix);
      o.start(t); o.stop(t + dur * 1.5 + 0.1);
    }
    if (formants) for (const [f, q, lv] of formants) {
      const b = ctx.createBiquadFilter(); b.type = 'bandpass'; b.frequency.value = f; b.Q.value = q;
      const fg = ctx.createGain(); fg.gain.value = lv;
      mix.connect(b); b.connect(fg); fg.connect(env);
    } else mix.connect(env);
    this._outdoor(env, sp);
  }

  _hears(sp, gain) { return this.enabled && this.ctx && sp.gain * gain > 0.0006; }

  // a hen mallard: a run of descending, nasal quacks
  quack(sp, gain = 0.1, n = 0) {
    if (!this._hears(sp, gain)) return;
    const t0 = this.ctx.currentTime;
    n = n || 2 + Math.floor(Math.random() * 5);
    let f = rnd(400, 520), g = gain * sp.gain, t = t0;
    for (let i = 0; i < n; i++) {
      this._note(t, { type: 'sawtooth', contour: [[0, f * 1.12], [0.85, f * 0.74]], dur: 0.17 - i * 0.006, gain: g, attack: 0.012, makeup: 3.2, formants: [[950, 3.2, 1], [2250, 5, 0.45], [3300, 6, 0.15]] }, sp);
      this._noise(t, 0.12, { freq: 1700, q: 1.2, gain: g * 0.3, decay: 0.05, sp });
      t += rnd(0.15, 0.2) + i * 0.012;
      f *= rnd(0.95, 0.985); g *= 0.82;
    }
  }

  // a goose: a short low "ah" and a longer, rising and falling, rough "honk" (one bird; a flock calls through several)
  honk(sp, gain = 0.1, when = 0) {
    if (!this._hears(sp, gain)) return;
    const t = this.ctx.currentTime + when, g = gain * sp.gain, f = rnd(300, 430);
    const formants = [[640, 3, 1], [1350, 4, 0.55], [2400, 5, 0.18]];
    this._note(t, { type: 'sawtooth', contour: [[0, f * 0.8], [1, f * 1.0]], dur: 0.11, gain: g * 0.55, attack: 0.02, hold: 0.5, makeup: 2.3, formants, vib: 10, vibRate: 30 }, sp);
    this._note(t + 0.12, { type: 'sawtooth', contour: [[0, f * 1.0], [0.3, f * 1.4], [1, f * 1.05]], dur: rnd(0.2, 0.3), gain: g, attack: 0.025, hold: 0.55, makeup: 2.3, formants, vib: 12, vibRate: 31 }, sp);
  }

  // swallows: a quick, bubbling twitter
  twitter(sp, gain = 0.06) {
    if (!this._hears(sp, gain)) return;
    let t = this.ctx.currentTime, f = rnd(3000, 4800);
    const n = 5 + Math.floor(Math.random() * 5), g = gain * sp.gain;
    for (let i = 0; i < n; i++) {
      this._note(t, { type: 'sine', contour: [[0, f], [0.45, f * rnd(1.15, 1.35)], [1, f * rnd(0.78, 0.95)]], dur: rnd(0.028, 0.045), gain: g * rnd(0.6, 1), attack: 0.004, hold: 0.25 }, sp);
      t += rnd(0.04, 0.07) + (Math.random() < 0.18 ? 0.06 : 0);
      f = clamp(f * rnd(0.88, 1.14), 2800, 5600);
    }
  }

  // a songbird's phrase: three to five slow, fluting notes
  whistle(sp, gain = 0.06) {
    if (!this._hears(sp, gain)) return;
    let t = this.ctx.currentTime, f = rnd(1700, 3000);
    const n = 3 + Math.floor(Math.random() * 3), g = gain * sp.gain;
    for (let i = 0; i < n; i++) {
      const f2 = clamp(f + (Math.random() - 0.5) * 800, 1400, 3600), dur = rnd(0.1, 0.26);
      this._note(t, { type: 'sine', contour: [[0, f], [0.55, f2], [1, f2 * rnd(0.92, 1.02)]], dur, gain: g * rnd(0.8, 1.2), attack: 0.015, hold: 0.5, vib: 24, vibRate: rnd(6, 9), partials: [[2, 0.14]] }, sp);
      t += dur * 0.9 + rnd(0.05, 0.15);
      f = f2;
    }
  }

  // a robin-like trill: a dozen short notes alternating high and low
  trill(sp, gain = 0.05) {
    if (!this._hears(sp, gain)) return;
    const t = this.ctx.currentTime, f = rnd(2200, 3400), n = 9 + Math.floor(Math.random() * 6), g = gain * sp.gain, ratio = rnd(1.12, 1.24);
    for (let i = 0; i < n; i++) {
      const hi = i % 2;
      this._note(t + i * 0.038, { type: 'sine', contour: [[0, hi ? f * ratio : f], [1, hi ? f * ratio * 0.97 : f * 1.03]], dur: 0.04, gain: g * (0.35 + 0.65 * Math.sin((Math.PI * i) / (n - 1))), attack: 0.004, hold: 0.2 }, sp);
    }
  }

  // a starling: a rising, wheezy whistle that falls away
  starling(sp, gain = 0.05) {
    if (!this._hears(sp, gain)) return;
    const t = this.ctx.currentTime, f = rnd(1700, 2300), g = gain * sp.gain;
    this._note(t, { type: 'sine', contour: [[0, f], [0.5, f * rnd(1.5, 1.9)], [1, f * rnd(1.1, 1.3)]], dur: rnd(0.25, 0.4), gain: g, attack: 0.04, hold: 0.45, vib: 40, vibRate: 11, partials: [[2, 0.2], [3, 0.08]] }, sp);
    this._noise(t, 0.2, { freq: 4200, q: 1, gain: g * 0.12, decay: 0.06, attack: 0.03, sp });
  }

  // something dropped into water, or a duck tipping up: a slap, a gulp, a few bubbles
  splash(sp, gain = 0.1, size = 1) {
    if (!this._hears(sp, gain)) return;
    const t = this.ctx.currentTime, g = gain * sp.gain;
    this._noise(t, 0.2, { freq: rnd(1500, 2100), q: 0.9, gain: g * 0.9, decay: 0.05 * size, attack: 0.004, sp });
    this._noise(t + 0.008, 0.3, { freq: 380, q: 0.7, gain: g * 0.8, decay: 0.09 * size, type: 'lowpass', attack: 0.006, sp });
    const nb = 1 + Math.floor(Math.random() * 3);
    for (let i = 0; i < nb; i++) {
      const f = rnd(380, 880);
      this._note(t + 0.03 + i * 0.045 + Math.random() * 0.04, { type: 'sine', contour: [[0, f], [1, f * 1.9]], dur: 0.07, gain: g * 0.55, attack: 0.004, hold: 0.2 }, sp);
    }
  }

  // a big bronze bell, struck once: the hum (an octave under), the prime, the minor third, the fifth, the octave and the upper partials of a
  // real bell (inharmonic, each dying at its own rate), a short clang at the strike. `n` strokes, `gap` seconds apart.
  toll(sp, gain = 0.1, n = 3, gap = 3.6) {
    if (!this._hears(sp, gain)) return;
    const ctx = this.ctx, g0 = gain * sp.gain, f0 = rnd(150, 175);
    const P = [[0.5, 0.9, 5.2], [1.0, 1.0, 4.2], [1.2, 0.55, 3.0], [1.5, 0.45, 2.2], [2.0, 0.5, 1.9], [2.5, 0.22, 1.2], [3.0, 0.2, 0.9], [4.0, 0.14, 0.6]];
    for (let s = 0; s < n; s++) {
      const t = ctx.currentTime + s * gap + rnd(0, 0.04), a = g0 * (1 - s * 0.08);
      for (const [m, lv, tau] of P) {
        const o = ctx.createOscillator(); o.type = 'sine'; o.frequency.value = f0 * m * (1 + rnd(-0.002, 0.002));
        const e = ctx.createGain();
        e.gain.setValueAtTime(0, t); e.gain.linearRampToValueAtTime(a * lv * 0.5, t + 0.006); e.gain.setTargetAtTime(0, t + 0.006, tau / 3);
        o.connect(e); this._outdoor(e, sp);
        o.start(t); o.stop(t + tau * 1.3 + 0.2);
      }
      this._noise(t, 0.2, { freq: 1500, q: 0.8, gain: a * 0.5, decay: 0.03, attack: 0.002, sp });
    }
  }

  // a koi rising to the surface: a soft, round "bloop" and a few bubbles
  bloop(sp, gain = 0.1) {
    if (!this._hears(sp, gain)) return;
    const t = this.ctx.currentTime, g = gain * sp.gain, f = rnd(190, 260);
    this._note(t, { type: 'sine', contour: [[0, f], [1, f * 2.6]], dur: 0.11, gain: g, attack: 0.012, hold: 0.25, partials: [[2, 0.12]] }, sp);
    this._noise(t, 0.12, { freq: 900, q: 0.8, gain: g * 0.25, decay: 0.03, attack: 0.01, sp });
    const nb = 1 + Math.floor(Math.random() * 3);
    for (let i = 0; i < nb; i++) this._note(t + 0.13 + i * rnd(0.05, 0.09), { type: 'sine', contour: [[0, rnd(500, 900)], [1, rnd(1100, 1700)]], dur: 0.05, gain: g * 0.35, attack: 0.004, hold: 0.2 }, sp);
  }

  // one drop on the pool in rain
  plink(sp, gain = 0.05) {
    if (!this._hears(sp, gain)) return;
    const t = this.ctx.currentTime, f = rnd(1300, 3100);
    this._note(t, { type: 'sine', contour: [[0, f * 1.15], [1, f * 0.8]], dur: 0.06, gain: gain * sp.gain, attack: 0.002, hold: 0.1 }, sp);
  }

  // a frog's croak: a few low, throaty pulses
  croak(sp, gain = 0.1) {
    if (!this._hears(sp, gain)) return;
    const t = this.ctx.currentTime, n = 3 + Math.floor(Math.random() * 3), f = rnd(140, 200), g = gain * sp.gain;
    for (let i = 0; i < n; i++) {
      this._note(t + i * rnd(0.065, 0.085), { type: 'sawtooth', contour: [[0, f * 1.15], [1, f * 0.9]], dur: 0.06, gain: g * (1 - i * 0.07), attack: 0.008, hold: 0.3, makeup: 2.6, formants: [[620, 4, 1], [1400, 5, 0.4]] }, sp);
    }
  }

  // a cricket's chirp: three quick pulses of one high pitch
  cricket(sp, gain = 0.03, freq = 4600) {
    if (!this._hears(sp, gain)) return;
    const t = this.ctx.currentTime;
    for (let i = 0; i < 3; i++) this._note(t + i * 0.045, { type: 'sine', contour: [[0, freq], [1, freq * 0.995]], dur: 0.022, gain: gain * sp.gain, attack: 0.004, hold: 0.4 }, sp);
  }

  // a tawny owl: "hoo ... hu, hoooo"
  hoot(sp, gain = 0.1) {
    if (!this._hears(sp, gain)) return;
    const t = this.ctx.currentTime, g = gain * sp.gain, f = rnd(400, 460);
    this._note(t, { type: 'sine', contour: [[0, f * 1.08], [0.3, f * 1.16], [1, f * 0.96]], dur: 0.55, gain: g, attack: 0.08, hold: 0.5, vib: 6, vibRate: 9, partials: [[2, 0.14]] }, sp);
    this._note(t + 1.0, { type: 'sine', contour: [[0, f * 0.95], [1, f * 0.9]], dur: 0.17, gain: g * 0.7, attack: 0.03, hold: 0.4, partials: [[2, 0.1]] }, sp);
    this._note(t + 1.35, { type: 'sine', contour: [[0, f * 0.98], [0.2, f * 1.06], [1, f * 0.85]], dur: 1.15, gain: g, attack: 0.1, hold: 0.6, vib: 10, vibRate: 11, partials: [[2, 0.14]] }, sp);
  }

  // a soft shutter for photo mode
  shutter() {
    if (!this.enabled || !this.ctx) return;
    const t = this.ctx.currentTime;
    this._noise(t, 0.02, { freq: 1800, q: 2, gain: 0.12, decay: 0.01 });
    this._noise(t + 0.07, 0.02, { freq: 1400, q: 2, gain: 0.08, decay: 0.012 });
  }
}
