import * as THREE from 'three';

// Weather's shared uniforms: read by the fountain's water, the glazing's
// droplets and the sky; written by the weather controller (explore/rain.js).
// `uRain` is 0 dry … 1 a downpour (eased); `uFlash` is the lightning's flash
// (0..1); `uWT` the weather's own clock (the explore clock); `uBow` the rainbow after the rain; `uSnow` snow falling and
// `uCover` snow lying (the white land, the pool's ice, the frost on the glass).
export const WEATHER = {
  uRain: { value: 0 },
  uFlash: { value: 0 },
  uWT: { value: 0 },
  uBow: { value: 0 }, // a rainbow, 0..1: the sky has cleared after a downpour and it has not yet faded (explore/rain.js)
  uSnow: { value: 0 }, // snow falling, 0..1 (eased)
  uFog: { value: 0 }, // fog, 0..1 (eased): thick, pale, still air with the sun in it
  uWet: { value: 0 }, // the ground wet after rain, 0..1: puddles form while it rains (about 20 s) and dry out over a couple of minutes (explore/rain.js)
  uCover: { value: 0 }, // snow lying on the land, the pool and the glass, 0..1: builds slowly while it snows, melts slowly after
};
// What the raindrops on the glass refract: the previous frame, copied small by the lens pass
// (render/pipeline.js) while it rains; the glazing's droplets sample it (world/lightfield.js).
export const REFRACT = {
  tPrev: { value: null },
  uPrevOn: { value: 0 },
  uScreen: { value: new THREE.Vector2(1, 1) },
};
export const V3 = THREE.Vector3;
