import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { Pass, FullScreenQuad } from 'three/addons/postprocessing/Pass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { REFRACT } from '../world/weatherU.js';

// Render pipeline:
//   ScenePass  – renders the scene (MSAA, HDR, depth) for one or two cameras,
//                applies a gather-based bokeh depth of field, and cross-
//                dissolves between shots when needed.
//   Bloom      – restrained; only true highlights (emissive > 1) bloom.
//   LensPass   – (interactive modes) a tiny light meter for eye adaptation
//                (dims over-bright frames, never brightens), and anamorphic
//                streaks and a warm halation round the brightest lights.
//   GradePass  – exposure, split-tone grade, ACES tone map, vignette, fade,
//                fine grain, sRGB output.

const DOF_FRAG = /* glsl */ `
  #include <packing>
  uniform sampler2D tColorA, tDepthA, tColorB, tDepthB;
  uniform vec2 uTexel;
  uniform float uNearA, uFarA, uFocusA, uApertureA;
  uniform float uNearB, uFarB, uFocusB, uApertureB;
  uniform float uMaxBlur, uMix;
  uniform int uSteps;
  varying vec2 vUv;
  const float GOLDEN = 2.39996323;

  float viewDist(sampler2D d, vec2 uv, float n, float f) {
    float z = texture2D(d, uv).x;
    return -perspectiveDepthToViewZ(z, n, f);
  }
  float blurSize(float dist, float focus, float ap) {
    return clamp(abs(1.0 - focus / max(dist, 1e-3)) * ap, 0.0, uMaxBlur);
  }
  vec3 bokeh(sampler2D col, sampler2D dep, float n, float f, float focus, float ap) {
    vec3 center = min(texture2D(col, vUv).rgb, vec3(14.0));
    float cd = viewDist(dep, vUv, n, f);
    float cs = blurSize(cd, focus, ap);
    if (ap < 0.01 || any(isnan(center))) return any(isnan(center)) ? vec3(0.0) : center;
    vec3 acc = center;
    float tot = 1.0;
    float radius = 0.6;
    float ang = 0.0;
    for (int i = 0; i < 160; i++) {
      if (i >= uSteps || radius >= uMaxBlur) break;
      vec2 tc = vUv + vec2(cos(ang), sin(ang)) * uTexel * radius;
      vec3 sc = min(texture2D(col, tc).rgb, vec3(14.0));
      float sd = viewDist(dep, tc, n, f);
      float ss = blurSize(sd, focus, ap);
      if (sd > cd) ss = clamp(ss, 0.0, cs * 2.0);
      float m = smoothstep(radius - 0.5, radius + 0.5, ss);
      // highlights bloom into soft discs (cheap bokeh weighting)
      float lum = dot(sc, vec3(0.299, 0.587, 0.114));
      float w = 1.0 + smoothstep(1.5, 8.0, lum) * 0.6 * m;
      acc += mix(acc / tot, sc, m) * w;
      tot += w;
      radius += 1.0 / radius * 1.6;
      ang += GOLDEN;
    }
    return acc / tot;
  }
  void main() {
    vec3 a = bokeh(tColorA, tDepthA, uNearA, uFarA, uFocusA, uApertureA);
    if (uMix > 0.001) {
      vec3 b = bokeh(tColorB, tDepthB, uNearB, uFarB, uFocusB, uApertureB);
      a = mix(a, b, uMix);
    }
    gl_FragColor = vec4(a, 1.0);
  }
`;

const RAY_TINT = new THREE.Color('#ffd6a0');
const VERT = /* glsl */ `varying vec2 vUv; void main(){ vUv = uv; gl_Position = vec4(position.xy, 0.0, 1.0); }`;

function makeTarget(w, h, samples) {
  const depthTexture = new THREE.DepthTexture(w, h);
  depthTexture.type = THREE.FloatType;
  const rt = new THREE.WebGLRenderTarget(w, h, {
    type: THREE.HalfFloatType,
    samples,
    depthTexture,
    depthBuffer: true,
  });
  return rt;
}

class ScenePass extends Pass {
  constructor(scene, w, h, quality) {
    super();
    this.scene = scene;
    this.quality = quality;
    this.rtA = makeTarget(w, h, quality.msaa);
    this.rtB = makeTarget(w, h, quality.msaa);
    this.material = new THREE.ShaderMaterial({
      uniforms: {
        tColorA: { value: this.rtA.texture },
        tDepthA: { value: this.rtA.depthTexture },
        tColorB: { value: this.rtB.texture },
        tDepthB: { value: this.rtB.depthTexture },
        uTexel: { value: new THREE.Vector2(1 / w, 1 / h) },
        uNearA: { value: 0.1 }, uFarA: { value: 1000 }, uFocusA: { value: 10 }, uApertureA: { value: 0 },
        uNearB: { value: 0.1 }, uFarB: { value: 1000 }, uFocusB: { value: 10 }, uApertureB: { value: 0 },
        uMaxBlur: { value: 20 },
        uMix: { value: 0 },
        uSteps: { value: quality.dofSteps },
      },
      vertexShader: VERT,
      fragmentShader: DOF_FRAG,
      depthTest: false,
      depthWrite: false,
    });
    this.fsQuad = new FullScreenQuad(this.material);
    this.shotA = null;
    this.shotB = null;
    this.mix = 0;
    this.height = h;
  }
  setSize(w, h) {
    this.rtA.setSize(w, h);
    this.rtB.setSize(w, h);
    this.material.uniforms.uTexel.value.set(1 / w, 1 / h);
    this.height = h;
  }
  // view: { camera, focus, aperture } – aperture is blur in px at 1080p for a
  // subject at infinity; scaled to the actual render height.
  setViews(a, b = null, mix = 0) {
    this.shotA = a;
    this.shotB = b;
    this.mix = b ? mix : 0;
  }
  render(renderer, writeBuffer) {
    const u = this.material.uniforms;
    const scale = this.height / 1080;
    u.uMaxBlur.value = Math.max(2, 26 * scale);
    const draw = (view, rt, suffix) => {
      renderer.setRenderTarget(rt);
      renderer.clear();
      renderer.render(this.scene, view.camera);
      u['uNear' + suffix].value = view.camera.near;
      u['uFar' + suffix].value = view.camera.far;
      u['uFocus' + suffix].value = view.focus;
      u['uAperture' + suffix].value = this.quality.dof ? view.aperture * scale : 0;
    };
    if (this.shotA.before) this.shotA.before();
    draw(this.shotA, this.rtA, 'A');
    if (this.shotB && this.mix > 0.001) {
      if (this.shotB.before) this.shotB.before();
      draw(this.shotB, this.rtB, 'B');
      if (this.shotA.before) this.shotA.before();
    }
    u.uMix.value = this.mix;
    renderer.setRenderTarget(this.renderToScreen ? null : writeBuffer);
    this.fsQuad.render(renderer);
  }
}

// Screen-space light shafts: sky visible through the glazing (depth = far)
// is marched toward the sun's screen position; iron ribs and plants occlude.
const RAYS_FRAG = /* glsl */ `
  uniform sampler2D tDiffuse, tDepth;
  uniform vec2 uSun;
  uniform float uIntensity, uDecay, uDensity, uSunVisible;
  uniform vec3 uTint;
  varying vec2 vUv;
  float skyMask(vec2 uv) {
    if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) return 0.0;
    float d = texture2D(tDepth, uv).x;
    vec3 c = min(texture2D(tDiffuse, uv).rgb, vec3(8.0));
    float lum = dot(c, vec3(0.2126, 0.7152, 0.0722));
    float near = exp(-length((uv - uSun) * vec2(1.6, 1.0)) * 1.6);
    return step(0.99999, d) * smoothstep(0.2, 1.4, lum) * near;
  }
  void main() {
    vec3 base = texture2D(tDiffuse, vUv).rgb;
    if (uIntensity <= 0.001) { gl_FragColor = vec4(base, 1.0); return; }
    vec2 delta = (vUv - uSun) * uDensity / 56.0;
    vec2 uv = vUv;
    float illum = 1.0, acc = 0.0;
    float jitter = fract(sin(dot(vUv, vec2(12.9898, 78.233))) * 43758.5453);
    uv -= delta * jitter;
    for (int i = 0; i < 56; i++) {
      uv -= delta;
      acc += skyMask(uv) * illum;
      illum *= uDecay;
    }
    acc /= 56.0;
    gl_FragColor = vec4(base + uTint * acc * uIntensity, 1.0);
  }
`;

const GRADE_FRAG = /* glsl */ `
  uniform sampler2D tDiffuse, tStreak, tHalo;
  uniform float uExposure, uFade, uVignette, uGrain, uTime, uSat, uWarm, uShadowAmt, uGrainLum, uStreakK, uHaloK;
  uniform vec3 uShadowTint, uHighTint, uStreakTint, uHaloTint;
  uniform vec2 uRes;
  varying vec2 vUv;
  vec3 aces(vec3 x) {
    // Hill / Narkowicz fitted ACES (RRT+ODT)
    const mat3 inM = mat3(0.59719, 0.07600, 0.02840, 0.35458, 0.90834, 0.13383, 0.04823, 0.01566, 0.83777);
    const mat3 outM = mat3(1.60475, -0.10208, -0.00327, -0.53108, 1.10813, -0.07276, -0.07367, -0.00605, 1.07602);
    x = inM * x;
    vec3 a = x * (x + 0.0245786) - 0.000090537;
    vec3 b = x * (0.983729 * x + 0.4329510) + 0.238081;
    return clamp(outM * (a / b), 0.0, 1.0);
  }
  vec3 toSRGB(vec3 c) { return mix(c * 12.92, 1.055 * pow(c, vec3(1.0/2.4)) - 0.055, step(0.0031308, c)); }
  float hash(vec2 p){ return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }
  void main() {
    vec2 uv = vUv;
    // whisper of lateral chromatic aberration toward the frame edges
    vec2 dc = uv - 0.5;
    float ca = dot(dc, dc) * 0.0035;
    vec3 col;
    col.r = texture2D(tDiffuse, uv - dc * ca).r;
    col.g = texture2D(tDiffuse, uv).g;
    col.b = texture2D(tDiffuse, uv + dc * ca).b;
    col *= uExposure;
    // the lens: streaks and halation round the brightest lights (interactive modes; 0 otherwise)
    if (uStreakK > 0.0) col += texture2D(tStreak, uv).rgb * uStreakTint * uStreakK;
    if (uHaloK > 0.0) col += texture2D(tHalo, uv).rgb * uHaloTint * uHaloK;
    // split-tone grade in scene-linear: teal in the shadows, gold in highlights
    float lum = dot(col, vec3(0.2126, 0.7152, 0.0722));
    float sh = 1.0 - smoothstep(0.0, 0.35, lum);
    float hi = smoothstep(0.4, 2.5, lum);
    col *= mix(vec3(1.0), uShadowTint, sh * uShadowAmt);
    col *= mix(vec3(1.0), uHighTint, hi * 0.5);
    col = mix(vec3(lum), col, uSat);
    vec3 mapped = aces(col);
    // vignette (in display space)
    float v = smoothstep(0.95, 0.25, length(dc * vec2(uRes.x / uRes.y, 1.0)) * 0.9);
    mapped *= mix(1.0, v, uVignette);
    mapped *= (1.0 - uFade);
    vec3 outc = toSRGB(mapped);
    // fine animated grain, stronger in the mids
    float g = hash(uv * uRes + fract(uTime * 7.31) * 100.0) - 0.5;
    outc += g * uGrain * (0.4 + 0.6 * (1.0 - abs(min(lum, uGrainLum) - 0.5)));
    gl_FragColor = vec4(outc, 1.0);
  }
`;


// ---- the lens -----------------------------------------------------------------------
// Eye adaptation: an 8x8 light meter (the log-average luminance of each cell's
// 36 taps of the frame, scene-linear, before exposure) is read back without a
// stall and averaged with a centre weighting. Exposure is only ever lowered:
// past a threshold it eases down so a copper bloom lit by the low sun, or a lamp
// filling the frame, keeps its detail; frames already in range are untouched.
// Streaks and halation: the lights above a threshold are gathered at a quarter
// of the resolution, stretched sideways with three dilated blurs (the
// anamorphic streak) and softened both ways (the warm halation), and added in
// the grade. The film never runs this (its exposure and look are exact).
const METER_FRAG = /* glsl */ `
  uniform sampler2D tDiffuse;
  varying vec2 vUv;
  void main() {
    vec2 cell = floor(vUv * 8.0);
    float acc = 0.0;
    for (int j = 0; j < 6; j++) for (int i = 0; i < 6; i++) {
      vec2 uv = (cell + (vec2(float(i), float(j)) + 0.5) / 6.0) / 8.0;
      vec3 c = min(texture2D(tDiffuse, uv).rgb, vec3(8.0));
      acc += log2(max(dot(c, vec3(0.2126, 0.7152, 0.0722)), 1e-4));
    }
    float v = clamp((acc / 36.0 + 10.0) / 14.0, 0.0, 1.0) * 65535.0; // -10 .. +4 stops in 16 bits
    float hi = floor(v / 256.0);
    gl_FragColor = vec4(hi / 255.0, (v - hi * 256.0) / 255.0, 0.0, 1.0);
  }
`;
const COPY_FRAG = /* glsl */ `
  uniform sampler2D tDiffuse;
  varying vec2 vUv;
  void main() { gl_FragColor = vec4( texture2D( tDiffuse, vUv ).rgb, 1.0 ); }
`;
const BRIGHT_FRAG = /* glsl */ `
  uniform sampler2D tDiffuse;
  uniform vec2 uTexel;
  uniform float uExposure, uThr;
  varying vec2 vUv;
  void main() {
    vec3 acc = vec3(0.0);
    for (int j = -1; j <= 1; j += 2) for (int i = -1; i <= 1; i += 2) acc += min(texture2D(tDiffuse, vUv + vec2(float(i), float(j)) * uTexel * 1.5).rgb, vec3(10.0));
    vec3 c = acc * 0.25 * uExposure;
    float l = dot(c, vec3(0.2126, 0.7152, 0.0722));
    gl_FragColor = vec4(c * smoothstep(uThr, uThr * 3.0, l), 1.0);
  }
`;
const BLUR_FRAG = /* glsl */ `
  uniform sampler2D tSrc;
  uniform vec2 uStep;
  varying vec2 vUv;
  void main() {
    vec3 acc = texture2D(tSrc, vUv).rgb;
    float norm = 1.0;
    for (int i = 1; i <= 4; i++) {
      float w = exp(-float(i * i) * 0.14);
      acc += (texture2D(tSrc, vUv + uStep * float(i)).rgb + texture2D(tSrc, vUv - uStep * float(i)).rgb) * w;
      norm += 2.0 * w;
    }
    gl_FragColor = vec4(acc / norm, 1.0);
  }
`;

class LensPass extends Pass {
  constructor(w, h, quality, renderer) {
    super();
    this.needsSwap = false; // reads the frame, writes only its own small targets
    this.renderer = renderer;
    this.streaks = quality.tier !== 'low';
    this.sync = false; // capture tools: read the meter back at once
    this.k = 1; // exposure compensation (1 = none)
    this.logL = -3; // the meter's centre-weighted log2 luminance (scene-linear, before exposure)
    this.target = 1;
    this.meterBuf = new Uint8Array(8 * 8 * 4);
    this.pending = false;
    this.frame = 0;
    // (a centre-weighted mean: the middle of the frame is what is being looked at)
    this.wts = new Float32Array(64);
    let tot = 0;
    for (let j = 0; j < 8; j++) for (let i = 0; i < 8; i++) { const d2 = (i - 3.5) ** 2 + (j - 3.5) ** 2; const w0 = Math.exp(-d2 / (2 * 2.6 * 2.6)); this.wts[j * 8 + i] = w0; tot += w0; }
    for (let i = 0; i < 64; i++) this.wts[i] /= tot;
    this.meterRT = new THREE.WebGLRenderTarget(8, 8, { type: THREE.UnsignedByteType, depthBuffer: false, minFilter: THREE.NearestFilter, magFilter: THREE.NearestFilter });
    const mk = (frag, uniforms) => new THREE.ShaderMaterial({ uniforms, vertexShader: VERT, fragmentShader: frag, depthTest: false, depthWrite: false });
    this.meterMat = mk(METER_FRAG, { tDiffuse: { value: null } });
    this.brightMat = mk(BRIGHT_FRAG, { tDiffuse: { value: null }, uTexel: { value: new THREE.Vector2(1 / w, 1 / h) }, uExposure: { value: 1 }, uThr: { value: 1.1 } });
    this.blurMat = mk(BLUR_FRAG, { tSrc: { value: null }, uStep: { value: new THREE.Vector2() } });
    // the frame, kept at half the size for the raindrops on the glass to refract (while it rains)
    this.copyMat = mk(COPY_FRAG, { tDiffuse: { value: null } });
    this.prev = new THREE.WebGLRenderTarget(Math.max(2, w >> 1), Math.max(2, h >> 1), { type: THREE.HalfFloatType, depthBuffer: false, minFilter: THREE.LinearFilter, magFilter: THREE.LinearFilter });
    this.copyPrev = false;
    this.prevValid = false;
    this.quad = new FullScreenQuad(this.meterMat);
    const opts = { type: THREE.HalfFloatType, depthBuffer: false, minFilter: THREE.LinearFilter, magFilter: THREE.LinearFilter };
    this.A = new THREE.WebGLRenderTarget(Math.max(2, w >> 2), Math.max(2, h >> 2), opts);
    this.B = this.A.clone();
    this.C = this.A.clone();
    this.streakTex = this.B.texture; // (the grade samples these)
    this.haloTex = this.A.texture;
    this.exposure = 1; // the exposure the streaks are gathered at (set by the pipeline)
    this.thr = 1.1;
    this.streakOn = false;
    this.w = w;
    this.h = h;
  }

  setSize(w, h) {
    this.w = w; this.h = h;
    this.brightMat.uniforms.uTexel.value.set(1 / w, 1 / h);
    for (const t of [this.A, this.B, this.C]) t.setSize(Math.max(2, w >> 2), Math.max(2, h >> 2));
    this.prev.setSize(Math.max(2, w >> 1), Math.max(2, h >> 1));
    this.prevValid = false;
  }

  // advance the adaptation: lower the exposure toward `target` quickly (the pupil closes),
  // raise it back slowly; dt 0 (photo, capture) jumps to the target
  adapt(dt, exposure, look) {
    const lx = this.logL + Math.log2(Math.max(exposure, 1e-3)); // log2 of the frame's luminance as it will be exposed
    const T = look.autoThreshold ?? -2.3; // (stops: about 0.2 of white: above this, ease down)
    const over = Math.max(0, lx - T);
    this.target = Math.max(look.autoMin ?? 0.5, Math.pow(2, -over * (look.autoGain ?? 0.6)));
    if (dt <= 0) { this.k = this.target; return; }
    const tau = this.target < this.k ? 0.6 : 1.9;
    this.k += (this.target - this.k) * (1 - Math.exp(-dt / tau));
  }

  _decode() {
    const b = this.meterBuf;
    let s = 0;
    for (let i = 0; i < 64; i++) s += this.wts[i] * (b[i * 4] * 256 + b[i * 4 + 1]);
    // (the packed value is v16/257 per channel step: R and G hold bytes of a 16-bit number)
    this.logL = (s / 65535) * 14 - 10;
  }

  render(renderer, writeBuffer, readBuffer) {
    const q = this.quad;
    // the meter, every other frame (a readback is in flight at most once)
    if (this.sync || (this.frame++ & 1) === 0) {
      this.meterMat.uniforms.tDiffuse.value = readBuffer.texture;
      q.material = this.meterMat;
      renderer.setRenderTarget(this.meterRT);
      q.render(renderer);
      if (this.sync) {
        renderer.readRenderTargetPixels(this.meterRT, 0, 0, 8, 8, this.meterBuf);
        this._decode();
      } else if (!this.pending) {
        this.pending = true;
        renderer.readRenderTargetPixelsAsync(this.meterRT, 0, 0, 8, 8, this.meterBuf).then(() => { this._decode(); this.pending = false; }, () => { this.pending = false; });
      }
    }
    // the frame, for the drops on the glass to refract next frame
    if (this.copyPrev) {
      this.copyMat.uniforms.tDiffuse.value = readBuffer.texture;
      q.material = this.copyMat;
      renderer.setRenderTarget(this.prev);
      q.render(renderer);
      this.prevValid = true;
    } else this.prevValid = false;
    if (!this.streakOn || !this.streaks) return;
    // lights above the threshold, at a quarter of the resolution
    const bm = this.brightMat;
    bm.uniforms.tDiffuse.value = readBuffer.texture;
    bm.uniforms.uExposure.value = this.exposure;
    bm.uniforms.uThr.value = this.thr;
    q.material = bm;
    renderer.setRenderTarget(this.A);
    q.render(renderer);
    // the anamorphic streak: three dilated horizontal blurs (A -> B -> C -> B)
    const bl = this.blurMat;
    q.material = bl;
    const pass = (src, dst, dx, dy) => {
      bl.uniforms.tSrc.value = src.texture;
      bl.uniforms.uStep.value.set(dx / src.width, dy / src.height);
      renderer.setRenderTarget(dst);
      q.render(renderer);
    };
    pass(this.A, this.B, 1, 0);
    pass(this.B, this.C, 4, 0);
    pass(this.C, this.B, 16, 0);
    // the halation: soft both ways (A -> C -> A -> C -> A), the bright pass consumed
    pass(this.A, this.C, 3, 0);
    pass(this.C, this.A, 0, 3);
    pass(this.A, this.C, 9, 0);
    pass(this.C, this.A, 0, 9);
  }
}

export class Pipeline {
  constructor(renderer, scene, quality) {
    this.renderer = renderer;
    this.quality = quality;
    const size = renderer.getDrawingBufferSize(new THREE.Vector2());
    this.composer = new EffectComposer(renderer);
    this.composer.setPixelRatio(1);
    this.composer.setSize(size.x, size.y);
    this.scenePass = new ScenePass(scene, size.x, size.y, quality);
    this.composer.addPass(this.scenePass);
    // light shafts through the glazing
    this.rays = new Pass();
    this.rays.material = new THREE.ShaderMaterial({
      uniforms: {
        tDiffuse: { value: null },
        tDepth: { value: this.scenePass.rtA.depthTexture },
        uSun: { value: new THREE.Vector2(0.5, 1.2) },
        uIntensity: { value: 0 },
        uDecay: { value: 0.975 },
        uDensity: { value: 0.85 },
        uSunVisible: { value: 1 },
        uTint: { value: new THREE.Color('#ffd6a0') },
      },
      vertexShader: VERT,
      fragmentShader: RAYS_FRAG,
      depthTest: false,
      depthWrite: false,
    });
    this.rays.fsQuad = new FullScreenQuad(this.rays.material);
    this.rays.render = function (renderer, writeBuffer, readBuffer) {
      this.material.uniforms.tDiffuse.value = readBuffer.texture;
      renderer.setRenderTarget(this.renderToScreen ? null : writeBuffer);
      this.fsQuad.render(renderer);
    };
    if (quality.tier !== 'low') this.composer.addPass(this.rays);
    this.bloom = new UnrealBloomPass(new THREE.Vector2(size.x / 2, size.y / 2), 0.32, 0.55, 1.15);
    if (quality.bloom) this.composer.addPass(this.bloom);
    // the lens: eye adaptation and streaks (interactive modes only: off for the film)
    this.lens = new LensPass(size.x, size.y, quality, renderer);
    this.lens.enabled = false;
    this.composer.addPass(this.lens);
    this.grade = new Pass();
    this.grade.material = new THREE.ShaderMaterial({
      uniforms: {
        tDiffuse: { value: null },
        uExposure: { value: 1 },
        uFade: { value: 0 },
        uVignette: { value: 0.55 },
        uGrain: { value: 0.035 },
        uTime: { value: 0 },
        uSat: { value: 1.05 },
        uWarm: { value: 0 },
        uShadowAmt: { value: 0.6 },
        uGrainLum: { value: 1e6 }, // the interactive modes cap it: glowing petals stay smooth
        uShadowTint: { value: new THREE.Color('#7fb7c0') },
        uHighTint: { value: new THREE.Color('#ffe2b5') },
        tStreak: { value: null },
        tHalo: { value: null },
        uStreakK: { value: 0 },
        uHaloK: { value: 0 },
        uStreakTint: { value: new THREE.Color('#bfe6ea') },
        uHaloTint: { value: new THREE.Color('#ff9a4a') },
        uRes: { value: new THREE.Vector2(size.x, size.y) },
      },
      vertexShader: VERT,
      fragmentShader: GRADE_FRAG,
      depthTest: false,
      depthWrite: false,
    });
    this.grade.fsQuad = new FullScreenQuad(this.grade.material);
    this.grade.render = function (renderer, writeBuffer, readBuffer) {
      this.material.uniforms.tDiffuse.value = readBuffer.texture;
      renderer.setRenderTarget(this.renderToScreen ? null : writeBuffer);
      this.fsQuad.render(renderer);
    };
    this.composer.addPass(this.grade);
  }

  setSize(w, h) {
    this.composer.setSize(w, h);
    this.scenePass.setSize(w, h);
    this.bloom.setSize(w / 2, h / 2);
    this.grade.material.uniforms.uRes.value.set(w, h);
    this.lens.setSize(w, h);
  }

  render(viewA, viewB, mix, look) {
    this.scenePass.setViews(viewA, viewB, mix);
    const u = this.grade.material.uniforms;
    // the lens (interactive modes): adapt the exposure to what the meter saw, add streaks and halation
    const lens = this.lens;
    lens.enabled = !!look.lens;
    let exposure = look.exposure;
    if (look.lens) {
      lens.adapt(look.dt ?? 0, look.exposure, look);
      if (look.autoExposure !== false) exposure *= lens.k;
    } else lens.k = 1;
    // (streaks belong to small lights in a wide frame: they fade as the frame is dimmed)
    const calm = Math.min(1, Math.max(0, (lens.k - 0.7) / 0.25));
    const sk = look.lens && lens.streaks ? (look.streak ?? 0) * calm : 0;
    lens.streakOn = sk > 0.001;
    lens.exposure = exposure;
    // (the drops on the glass refract the last frame while it rains)
    lens.copyPrev = !!look.lens && !!look.refract;
    REFRACT.tPrev.value = lens.prev.texture;
    REFRACT.uPrevOn.value = lens.copyPrev && lens.prevValid ? 1 : 0;
    REFRACT.uScreen.value.set(this.scenePass.rtA.width, this.scenePass.rtA.height);
    lens.thr = look.streakThr ?? 1.1;
    u.tStreak.value = lens.streakTex;
    u.tHalo.value = lens.haloTex;
    u.uStreakK.value = lens.streakOn ? sk : 0;
    u.uHaloK.value = lens.streakOn ? (look.halo ?? 0) * (0.35 + 0.65 * calm) : 0;
    u.uExposure.value = exposure;
    u.uFade.value = look.fade;
    u.uTime.value = look.time;
    u.uVignette.value = look.vignette ?? 0.55;
    u.uSat.value = look.saturation ?? 1.05;
    u.uShadowAmt.value = look.shadowTint ?? 0.5;
    u.uGrainLum.value = look.grainLum ?? 1e6;
    this.bloom.strength = look.bloom ?? 0.32;
    // light shafts: project the sun into screen space for camera A
    const ru = this.rays.material.uniforms;
    ru.uIntensity.value = 0;
    if ((look.godrays ?? 0) > 0.001 && look.sunDir) {
      const cam = viewA.camera;
      const p = cam.position.clone().addScaledVector(look.sunDir, -1000).project(cam);
      const inFront = cam.getWorldDirection(new THREE.Vector3()).dot(look.sunDir) < 0;
      // (look.rayNear: march only when the light is on or near the frame, as the moon's faint rays are)
      if (inFront && (!look.rayNear || (Math.abs(p.x) < look.rayNear && Math.abs(p.y) < look.rayNear))) {
        ru.uSun.value.set(p.x * 0.5 + 0.5, p.y * 0.5 + 0.5);
        ru.uIntensity.value = look.godrays * 0.9;
      }
    }
    // (the interactive modes tint the rays: cool moon rays by night)
    ru.uTint.value.copy(look.rayTint ?? RAY_TINT);
    this.composer.render();
  }
}
