import * as THREE from 'three';
import { SUN_DIR } from '../world/atmosphere.js';
import { WEATHER } from '../world/weatherU.js';
import { clamp, sseg } from '../core/ease.js';
import { OUT } from './scenery.js';

// The bee's shadow on the ground, out in the garden (interactive modes).
//
// Flown low over the lawn the bee had nothing to say how high it was: no shadow fell outside the glass. This is a soft one on the ground
// under it, thrown along the sun (longer as the sun gets lower), cross-shaped (body along its heading, the wings across) and a penumbra that
// widens, and a darkness that fades, with height (a few units off the grass it is dark and sharp, a hundred and fifty up it is gone). It is
// the sun's share of the light that darkens it (a cloud over the garden softens it to a faint pool of shade), and it goes out at night.
// One quad, drawn with the land (not in the pool's mirror); inside the house the real shadows do this, and over the water the reflection does.

const VERT = /* glsl */ `
  varying vec2 vXZ;
  void main() {
    vec4 w = modelMatrix * vec4(position, 1.0);
    vXZ = w.xz;
    gl_Position = projectionMatrix * viewMatrix * w;
  }
`;

const FRAG = /* glsl */ `
  uniform vec2 uC;      // the centre of the shadow (x, z)
  uniform vec2 uAxis;   // the sun's way along the ground
  uniform vec2 uFwd;    // the bee's heading
  uniform float uStretch, uBlur, uAlpha;
  varying vec2 vXZ;
  void main() {
    vec2 d = vXZ - uC;
    // a shadow is the shape stretched along the light by 1 / sin(elevation)
    float a = dot(d, uAxis);
    d += uAxis * (a / uStretch - a);
    float f = dot(d, uFwd), s = dot(d, vec2(-uFwd.y, uFwd.x));
    // the body (long along the heading) and the wings (long across it, thin)
    float e1 = length(vec2(f / 2.2, s / 1.1)), e2 = length(vec2(f / 1.0, s / 2.9));
    float sh = max(1.0 - smoothstep(1.0 - uBlur, 1.0 + uBlur, e1), 0.8 * (1.0 - smoothstep(1.0 - uBlur * 1.6, 1.0 + uBlur * 1.6, e2)));
    gl_FragColor = vec4(0.012, 0.03, 0.012, sh * uAlpha);
  }
`;

export class BeeShadow {
  constructor() {
    const geo = new THREE.PlaneGeometry(1, 1);
    geo.rotateX(-Math.PI / 2);
    this.uni = { uC: { value: new THREE.Vector2() }, uAxis: { value: new THREE.Vector2(1, 0) }, uFwd: { value: new THREE.Vector2(0, 1) }, uStretch: { value: 1 }, uBlur: { value: 0.2 }, uAlpha: { value: 0 } };
    const mat = new THREE.ShaderMaterial({ uniforms: this.uni, vertexShader: VERT, fragmentShader: FRAG, transparent: true, depthWrite: false, fog: false, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2 });
    this.mesh = new THREE.Mesh(geo, mat);
    this.mesh.name = 'beeshadow';
    this.mesh.renderOrder = 2;
    this.mesh.frustumCulled = false;
    this.mesh.visible = false;
  }

  // a: the actor (pos, yaw); bounds: the flight volume (ground height, outside, the pool)
  update(a, bounds, hidden = false) {
    const p = a.pos;
    const gy = bounds.ground(p.x, p.z);
    const h = p.y - gy;
    const pool = bounds.out?.pond;
    const q = pool ? ((p.x - pool.x) / pool.rx) ** 2 + ((p.z - pool.z) / pool.rz) ** 2 : 9;
    const D = SUN_DIR;
    const horiz = Math.hypot(D.x, D.z) || 1;
    const el = Math.asin(clamp(-D.y, 0, 1));
    const sun = OUT.uSunK.value * sseg(el, 0.05, 0.3); // (the direct light on the land: cloud and a low sun thin it)
    const amb = (1 - OUT.uNight.value) * 0.45; // (the sky's own light: a soft pool of shade even when the sun is not shining)
    const strength = 0.2 * amb + 0.6 * sun * (1 - 0.6 * Math.min(1, WEATHER.uCover.value));
    const fade = 1 - sseg(h, 25, 170);
    const alpha = hidden || a.state === 'landed' ? 0 : strength * fade * sseg(q, 0.55, 0.85) * (bounds.isOutside(p) ? 1 : 0);
    this.mesh.visible = alpha > 0.01 && h > 0.5;
    if (!this.mesh.visible) return;
    const u = this.uni, ax = D.x / horiz, az = D.z / horiz;
    const cot = Math.min(horiz / Math.max(-D.y, 0.12), 1.3); // (a low sun throws it a long way: kept near, so that it still reads as this bee's)
    u.uC.value.set(p.x + ax * h * cot, p.z + az * h * cot);
    u.uAxis.value.set(ax, az);
    u.uFwd.value.set(Math.sin(a.yaw), Math.cos(a.yaw));
    u.uStretch.value = Math.min(1 / Math.max(Math.sin(el), 0.5), 2);
    u.uBlur.value = Math.min(0.9, 0.1 + h * 0.006 + (1 - sun) * 0.14);
    u.uAlpha.value = alpha;
    // the quad covers the penumbra (and the stretch)
    const sz = 22 + h * 0.5;
    this.mesh.scale.set(sz, 1, sz);
    this.mesh.position.set(u.uC.value.x, gy + 0.35, u.uC.value.y);
  }
}
