import * as THREE from 'three';
import { lightFieldMaterial } from '../world/lightfield.js';
import { WEATHER } from './weather.js';

// The living fountain (interactive modes; the film keeps its flat basin).
//
// The water: the film's disc becomes a PBR surface whose normal is moved by a
// small height field: a slow swell; rings from drops (the armillary's drips
// by day and night, a downpour's when it rains: one ring per cell per cycle,
// hashed, so there is no state); and wake rings left where APX-9 flies low
// over the basin (a ring buffer of the last few positions). It reflects the
// environment, the vault and the lamps' glints like any other surface; a
// faint caustic web glows in it as if the floor below were sunlit.
// The stone: the column, the basin's wall and rim catch the same caustic web as
// moving light just above the waterline (reflected light playing on stone).

const EM = 6;
// one body of water's uniforms: the clock, a ring buffer of wake rings (x, z, born, amplitude), where its drops are gridded from, its light
export const makeFX = (n = EM) => ({
  uFT: { value: 0 },
  uEm: { value: Array.from({ length: n }, () => new THREE.Vector4(0, 0, -99, 0)) },
  uFC: { value: new THREE.Vector2() },
  uFSun: { value: 1 }, // how sunlit the water is (caustics and glints)
  uFLamp: { value: 0 }, // the lamps' warmth at night
});
export const WATERFX = makeFX(EM);

// the water's height field in GLSL (swell, drop rings, wake rings, caustic web) for a buffer of `EM` wake rings
export const ripplesGLSL = (EM, cell = 11, dens = 0.16) => /* glsl */ `
  uniform float uFT, uFSun, uFLamp, uRain;
  uniform vec2 uFC;
  uniform vec4 uEm[${EM}];
  float cgfH( vec2 p ) { return fract( sin( dot( p, vec2( 127.1, 311.7 ) ) ) * 43758.5453 ); }
  // drop rings: each cell holds a drop that falls every few seconds (with probability dens) and sends out a ring
  vec3 cgfDrops( vec2 p, float t, float dens ) {
    const float CELL = ${cell.toFixed(1)};
    vec2 g = floor( p / CELL );
    vec3 acc = vec3( 0.0 );
    for ( int j = -1; j <= 1; j ++ ) for ( int i = -1; i <= 1; i ++ ) {
      vec2 c = g + vec2( float( i ), float( j ) );
      float h3 = cgfH( c + 3.1 );
      vec2 pos = ( c + vec2( cgfH( c ), cgfH( c + 7.7 ) ) ) * CELL;
      float period = 2.4 + h3 * 2.2;
      float u = t / period + h3 * 13.7;
      float age = fract( u ) * period;
      float on = step( cgfH( c + floor( u ) * 1.37 ), dens );
      vec2 d = p - pos;
      float r = max( length( d ), 1e-3 );
      float x = r - age * 9.0;
      float env = exp( -age * 1.5 ) * on;
      float e = exp( -x * x * 0.07 );
      float h = sin( x * 1.5 ) * e;
      float dh = ( cos( x * 1.5 ) * 1.5 - sin( x * 1.5 ) * 0.14 * x ) * e;
      acc += vec3( h, dh * d.x / r, dh * d.y / r ) * env;
    }
    return acc;
  }
  // wake rings from where the bee flew low over the water
  vec3 cgfWake( vec2 p, float t ) {
    vec3 acc = vec3( 0.0 );
    for ( int k = 0; k < ${EM}; k ++ ) {
      vec4 e = uEm[ k ];
      float age = t - e.z;
      if ( age < 0.0 || age > 2.6 || e.w <= 0.0 ) continue;
      vec2 d = p - e.xy;
      float r = max( length( d ), 1e-3 );
      float x = r - age * 10.0;
      float env = exp( -age * 1.2 ) * e.w * smoothstep( 0.0, 2.5, r );
      float g = exp( -x * x * 0.05 );
      float h = sin( x * 1.3 ) * g;
      float dh = ( cos( x * 1.3 ) * 1.3 - sin( x * 1.3 ) * 0.1 * x ) * g;
      acc += vec3( h, dh * d.x / r, dh * d.y / r ) * env;
    }
    return acc;
  }
  // the water's height (x) and its slope (yz) at a point on the basin
  vec3 cgfWater( vec2 p, float t ) {
    vec2 q = p - uFC;
    vec3 h = cgfDrops( q, t, ${dens.toFixed(3)} + 0.8 * uRain ) * ( 0.8 + 0.5 * uRain ) + cgfWake( p, t ) * 1.4;
    // a slow swell
    vec2 s = q * 0.05 + vec2( t * 0.12, -t * 0.09 );
    float sw = sin( s.x * 3.0 + sin( s.y * 2.0 + t * 0.4 ) * 1.6 );
    h.x += 0.12 * sw;
    h.y += 0.12 * cos( s.x * 3.0 + sin( s.y * 2.0 + t * 0.4 ) * 1.6 ) * 0.15;
    h.z += 0.12 * cos( s.y * 2.3 + t * 0.4 ) * 0.1;
    return h;
  }
  // a caustic web (four folds of an interference pattern), 0 dark … 1 bright thread
  float cgfCaustic( vec2 uv, float t ) {
    vec2 p = mod( uv * 6.28318, 6.28318 ) - 250.0;
    vec2 i = p;
    float c = 1.0;
    for ( int n = 0; n < 4; n ++ ) {
      float tt = t * ( 1.0 - 3.5 / float( n + 1 ) );
      i = p + vec2( cos( tt - i.x ) + sin( tt + i.y ), sin( tt - i.y ) + cos( tt + i.x ) );
      c += 1.0 / length( vec2( p.x / ( sin( i.x + tt ) / 0.005 ), p.y / ( cos( i.y + tt ) / 0.005 ) ) );
    }
    c /= 4.0;
    c = 1.17 - pow( c, 1.4 );
    return pow( abs( c ), 8.0 );
  }
`;

const RIPPLES = ripplesGLSL(EM);
const worldPos = 'vec3 cgfW = ( ( vec4( -vViewPosition, 1.0 ) - viewMatrix[ 3 ] ) * viewMatrix ).xyz;';

function waterMaterial(film) {
  const m = new THREE.MeshPhysicalMaterial({ color: '#0c2a2b', roughness: 0.045, metalness: 0, clearcoat: 0, envMapIntensity: 1.35, specularIntensity: 1 });
  m.userData.noWind = true;
  m.onBeforeCompile = (sh) => {
    Object.assign(sh.uniforms, WATERFX, { uRain: WEATHER.uRain });
    sh.fragmentShader = sh.fragmentShader
      .replace('#include <common>', '#include <common>\n' + RIPPLES)
      .replace('#include <normal_fragment_maps>', `#include <normal_fragment_maps>
        {
          ${worldPos}
          vec3 cgfR = cgfWater( cgfW.xz, uFT );
          vec3 cgfN = normalize( vec3( -cgfR.y * 0.42, 1.0, -cgfR.z * 0.42 ) );
          normal = normalize( ( viewMatrix * vec4( cgfN, 0.0 ) ).xyz );
        }`)
      .replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
        {
          ${worldPos}
          // the floor below, sunlit: a faint web of caustic threads (by night, the lamps' colour)
          float cgfC = cgfCaustic( cgfW.xz * 0.021, uFT * 0.55 ) * 0.7 + cgfCaustic( cgfW.xz * 0.034 + 3.7, uFT * 0.4 ) * 0.5;
          float cgfE = smoothstep( 46.0, 30.0, length( cgfW.xz - uFC ) );
          totalEmissiveRadiance += cgfC * cgfE * ( vec3( 0.20, 0.62, 0.58 ) * uFSun + vec3( 0.55, 0.32, 0.1 ) * uFLamp * 0.5 ) * ( 1.0 - uRain * 0.5 ) * 0.85;
        }`);
  };
  m.customProgramCacheKey = () => 'cg-water-v1';
  return m;
}

// stone near the waterline that the water's light plays on
function causticStone(film) {
  const m = film.clone();
  const prev = m.onBeforeCompile;
  m.onBeforeCompile = (sh, r) => {
    if (prev) prev.call(m, sh, r);
    Object.assign(sh.uniforms, WATERFX, { uRain: WEATHER.uRain });
    sh.fragmentShader = sh.fragmentShader
      .replace('#include <common>', '#include <common>\n' + RIPPLES)
      .replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
        {
          ${worldPos}
          // light thrown up from the water, strongest at the waterline and fading up the stone
          float cgfH2 = clamp( ( cgfW.y - 7.5 ) / 26.0, 0.0, 1.0 );
          float cgfA = ( 1.0 - cgfH2 ) * ( 1.0 - cgfH2 );
          // (it falls on what faces the water: the column most, the rim and the basin's outside only a little)
          cgfA *= mix( 1.0, 0.16, smoothstep( 8.0, 20.0, length( cgfW.xz - uFC ) ) );
          float cgfC = cgfCaustic( vec2( cgfW.x + cgfW.z * 0.3, cgfW.y * 1.6 + cgfW.z * 0.2 ) * 0.03, uFT * 0.6 );
          totalEmissiveRadiance += cgfC * cgfA * ( vec3( 0.16, 0.48, 0.44 ) * uFSun + vec3( 0.5, 0.3, 0.1 ) * uFLamp * 0.45 ) * ( 1.0 - uRain * 0.4 ) * 1.6;
        }`);
  };
  m.customProgramCacheKey = () => 'cg-caustic-stone-v1';
  return m;
}

export class Fountain {
  constructor({ world, upgrade, quality }) {
    const f = world.flora.fountain;
    this.center = new THREE.Vector2(f.x, f.z);
    WATERFX.uFC.value.copy(this.center);
    this.waterY = f.waterY;
    const per = quality?.tier === 'low' ? 4 : 8;
    const water = lightFieldMaterial(waterMaterial(f.water.material), per);
    upgrade.swap(f.water, 'material', water);
    const stone = lightFieldMaterial(causticStone(f.stone), per);
    for (const mesh of f.stoneMeshes) upgrade.swap(mesh, 'material', stone);
    this.emit = 0;
    this.last = 0;
  }

  // bee: { pos, speed }; phases: the hour's phases; clock: the explore clock
  update(clock, bee, phases) {
    WATERFX.uFT.value = clock;
    WEATHER.uWT.value = clock;
    WATERFX.uFSun.value = (1 - phases.night * 0.85) * (1 - WEATHER.uRain.value * 0.6);
    WATERFX.uFLamp.value = Math.max(phases.lamps, phases.night) * 0.9;
    // a wake where APX-9 flies low over the water
    const dx = bee.pos.x - this.center.x, dz = bee.pos.z - this.center.y;
    const h = bee.pos.y - this.waterY;
    if (Math.hypot(dx, dz) < 50 && h < 40 && h > -2 && clock - this.last > 0.16) {
      const amp = THREE.MathUtils.smoothstep(40 - h, 0, 31) * Math.min(1, 0.3 + bee.speed / 22);
      if (amp > 0.06) {
        this.last = clock;
        this.emit = (this.emit + 1) % EM;
        WATERFX.uEm.value[this.emit].set(bee.pos.x, bee.pos.z, clock, amp);
      }
    }
  }
}
