import * as THREE from 'three';
import { WEATHER } from '../world/weatherU.js';
import { L } from '../world/layout.js';
import { clamp } from '../core/ease.js';
import { WIND } from '../world/wind.js';

// Weather (interactive modes, off until asked for: the menu's Rain, `R`, or ?rain=1).
//
// The sky closes over (the sun goes behind cloud, the lamps kindle by day, the
// butterflies roost, the stone and the path go wet); rain falls outside the
// glass as thousands of streaks gathered round the camera (none inside the house);
// droplets bead and run down the panes, catching the lamps (world/lightfield.js);
// ripples ring the fountain; there is the sound of it. In a downpour the sky
// lights now and then, twice in quick succession, and thunder follows; the flash
// lights the vault through the iron, so the rib shadows snap across the beds. The
// flashes are soft (a short rise, no more than two a few seconds apart, never a strobe)
// and are left out entirely when reduced motion is asked for.
//
// Snow is the other weather (`N`, the menu's Snow, `?snow=1`; the two are never on together): flakes drift down slantwise on
// the wind and swirl as they fall (none inside the glasshouse); the sky closes over white, not grey; the land goes white (every
// outdoor surface by how far it faces up: the lawn and the roofs, the crowns' tops, the coping), the pool freezes, the panes frost
// at their edges and corners. The fall builds the cover over about a minute (`cover`), and when it stops the cover lingers, then melts
// (faster in rain). The lamps kindle by day, as in the rain; the birds and the insects keep indoors.
//
// Fog is the third (`V`, the menu's Fog, `?fog=1`; never together with the others): the air thickens to a pale, still wall a few hundred
// units deep, the sun a soft glow in it, the sky one pale brightness; the glasshouse's own air thickens and its sunbeams stand out
// in it; the panes bead with dew; mist lifts off the pool; the lamps kindle by day; and a bell tolls, far off, from the manor.

const H = L.house;
const VERT = /* glsl */ `
  attribute vec4 aSeed;
  attribute float aEnd;
  uniform vec3 uCam;
  uniform float uT, uRain, uFlash;
  uniform vec4 uHouse; // x0, x1, z1 (back), z0 (front)
  uniform vec2 uArch; // wall height, ridge height
  varying float vA;
  void main() {
    const float BOX = 900.0, HH = 520.0;
    vec3 p;
    p.xz = aSeed.xy * BOX;
    p.xz = uCam.xz + mod( p.xz - uCam.xz + 0.5 * BOX, BOX ) - 0.5 * BOX;
    float speed = 300.0 + aSeed.w * 140.0;
    p.y = uCam.y + mod( aSeed.z * HH - uT * speed - uCam.y + 0.5 * HH, HH ) - 0.5 * HH;
    // no rain inside the glasshouse
    float cx = ( uHouse.x + uHouse.y ) * 0.5, hw = ( uHouse.y - uHouse.x ) * 0.5;
    float kx = clamp( ( p.x - cx ) / hw, -1.0, 1.0 );
    float roof = uArch.x + ( uArch.y - uArch.x ) * sqrt( max( 0.0, 1.0 - kx * kx ) );
    bool inside = p.x > uHouse.x - 6.0 && p.x < uHouse.y + 6.0 && p.z < uHouse.w + 6.0 && p.z > uHouse.z - 6.0 && p.y < roof + 6.0;
    vec3 dir = normalize( vec3( 0.2, -1.0, 0.07 ) );
    float len = 13.0 + aSeed.w * 11.0;
    vec3 pos = p - dir * ( aEnd * len );
    float dist = length( p - uCam );
    vA = uRain * ( 0.16 + 0.22 * aSeed.w ) * exp( -dist / 650.0 ) * ( 0.55 + 0.45 * ( 1.0 - aEnd ) ) * ( 1.0 + uFlash * 2.5 );
    gl_Position = inside || p.y < 0.0 ? vec4( 2.0, 2.0, 2.0, 1.0 ) : projectionMatrix * viewMatrix * vec4( pos, 1.0 );
  }
`;
const FRAG = /* glsl */ `
  varying float vA;
  void main() { gl_FragColor = vec4( vec3( 0.74, 0.84, 0.95 ), clamp( vA, 0.0, 0.8 ) ); }
`;

const SNOW_VERT = /* glsl */ `
  attribute vec4 aSeed;
  uniform vec3 uCam;
  uniform float uT, uSnow, uRes;
  uniform vec4 uHouse; // x0, x1, z1 (back), z0 (front)
  uniform vec2 uArch, uWindDir;
  varying float vA;
  void main() {
    const float BOX = 1000.0, HH = 560.0;
    vec3 p;
    p.xz = aSeed.xy * BOX;
    p.xz = uCam.xz + mod( p.xz - uCam.xz + 0.5 * BOX, BOX ) - 0.5 * BOX;
    float speed = 22.0 + aSeed.w * 22.0;
    p.y = uCam.y + mod( aSeed.z * HH - uT * speed - uCam.y + 0.5 * HH, HH ) - 0.5 * HH;
    // slantwise on the wind (more drift the higher the flake), swirling a little as it falls
    float ph = aSeed.x * 40.0 + aSeed.w * 17.0;
    p.xz += uWindDir * ( p.y - uCam.y ) * 0.22 + vec2( sin( uT * 0.9 + ph + p.y * 0.02 ), cos( uT * 0.7 + ph * 1.3 + p.y * 0.017 ) ) * ( 6.0 + 6.0 * aSeed.w );
    float cx = ( uHouse.x + uHouse.y ) * 0.5, hw = ( uHouse.y - uHouse.x ) * 0.5;
    float kx = clamp( ( p.x - cx ) / hw, -1.0, 1.0 );
    float roof = uArch.x + ( uArch.y - uArch.x ) * sqrt( max( 0.0, 1.0 - kx * kx ) );
    bool inside = p.x > uHouse.x - 6.0 && p.x < uHouse.y + 6.0 && p.z < uHouse.w + 6.0 && p.z > uHouse.z - 6.0 && p.y < roof + 6.0;
    vec4 mv = viewMatrix * vec4( p, 1.0 );
    float d = -mv.z;
    float px = ( 1.0 + 1.5 * aSeed.w ) * uRes * 0.5 * projectionMatrix[ 1 ][ 1 ] / max( d, 1.0 );
    gl_PointSize = clamp( px, 1.6 * uRes / 720.0, 15.0 * uRes / 720.0 );
    vA = uSnow * ( 0.5 + 0.5 * aSeed.w ) * exp( -d / 1100.0 ) * smoothstep( 6.0, 40.0, d );
    gl_Position = inside || p.y < -2.0 ? vec4( 2.0, 2.0, 2.0, 1.0 ) : projectionMatrix * mv;
  }
`;
const SNOW_FRAG = /* glsl */ `
  varying float vA;
  void main() {
    float r = length( gl_PointCoord - 0.5 ) * 2.0;
    float a = smoothstep( 1.0, 0.25, r );
    gl_FragColor = vec4( vec3( 0.95, 0.975, 1.0 ), a * clamp( vA, 0.0, 0.95 ) );
  }
`;

export class Weather {
  constructor({ quality, group, audio }) {
    this.audio = audio;
    this.snowTarget = 0;
    this.fogTarget = 0;
    this.fog = 0; // fog, eased 0..1
    this.snow = 0; // flakes falling, eased 0..1
    this.cover = 0; // snow lying: builds while it snows, lingers, melts
    this.wet = 0; // the ground wet: builds in rain (about 20 s), dries over ~110 s (the puddles on the lawn and the gravel)
    this.overcast = 0; // how closed the sky is: the rain's k, or the snow's (a little lighter)
    this.target = 0;
    this.k = 0; // eased 0..1
    this.flash = 0;
    this.shower = 0; // 1 after a downpour, running down over ~90 s once it has gone (a rainbow's cue)
    this.bow = 0; // the rainbow's strength: it forms as the sky clears and fades as the air dries
    this.bolts = []; // pending pulses [{ t0, amp }]
    this.nextBolt = 6;
    this.reduced = false;
    const n = quality.tier === 'low' ? 2600 : quality.tier === 'med' ? 5200 : 8000;
    const seeds = new Float32Array(n * 2 * 4), ends = new Float32Array(n * 2);
    let s = 0x9e3779b9;
    const r = () => { s ^= s << 13; s ^= s >>> 17; s ^= s << 5; return ((s >>> 0) / 4294967296); };
    for (let i = 0; i < n; i++) {
      const a = r(), b = r(), c = r(), d = r();
      for (let e = 0; e < 2; e++) { seeds.set([a, b, c, d], (i * 2 + e) * 4); ends[i * 2 + e] = e; }
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(n * 2 * 3), 3));
    geo.setAttribute('aSeed', new THREE.BufferAttribute(seeds, 4));
    geo.setAttribute('aEnd', new THREE.BufferAttribute(ends, 1));
    this.n = n;
    this.uniforms = {
      uCam: { value: new THREE.Vector3() },
      uT: WEATHER.uWT,
      uRain: WEATHER.uRain,
      uFlash: WEATHER.uFlash,
      uHouse: { value: new THREE.Vector4(H.x0, H.x1, H.z1, H.z0) },
      uArch: { value: new THREE.Vector2(H.wall, H.ridge) },
    };
    this.lines = new THREE.LineSegments(geo, new THREE.ShaderMaterial({ uniforms: this.uniforms, vertexShader: VERT, fragmentShader: FRAG, transparent: true, depthWrite: false, fog: false }));
    this.lines.frustumCulled = false;
    this.lines.renderOrder = 1;
    this.lines.visible = false;
    group.add(this.lines);
    // the flakes: one point sprite each, worked out in the vertex shader (sized from the target being drawn, so the pool's mirror agrees)
    const ns = quality.tier === 'low' ? 2200 : quality.tier === 'med' || quality.tier === 'medium' ? 4500 : 7500;
    const fs = new Float32Array(ns * 4);
    for (let i = 0; i < ns * 4; i++) fs[i] = r();
    const fg = new THREE.BufferGeometry();
    fg.setAttribute('position', new THREE.BufferAttribute(new Float32Array(ns * 3), 3));
    fg.setAttribute('aSeed', new THREE.BufferAttribute(fs, 4));
    this.ns = ns;
    this.snowU = { uCam: this.uniforms.uCam, uT: WEATHER.uWT, uSnow: WEATHER.uSnow, uRes: { value: 720 }, uHouse: this.uniforms.uHouse, uArch: this.uniforms.uArch, uWindDir: { value: WIND.dir } };
    this.flakes = new THREE.Points(fg, new THREE.ShaderMaterial({ uniforms: this.snowU, vertexShader: SNOW_VERT, fragmentShader: SNOW_FRAG, transparent: true, depthWrite: false, fog: false }));
    this.flakes.frustumCulled = false;
    this.flakes.renderOrder = 1;
    this.flakes.visible = false;
    this.flakes.layers.enable(1); // (and in the pool's mirror)
    this.flakes.onBeforeRender = (renderer) => { const rt = renderer.getRenderTarget(); this.snowU.uRes.value = rt ? rt.height : renderer.domElement.height; };
    group.add(this.flakes);
  }

  get on() { return this.target > 0; }

  get snowOn() { return this.snowTarget > 0; }

  get fogOn() { return this.fogTarget > 0; }

  // rain, snow and fog are never on together
  set(on) { this.target = on ? 1 : 0; if (on) { this.snowTarget = 0; this.fogTarget = 0; } }

  setSnow(on, jump = false) {
    this.snowTarget = on ? 1 : 0;
    if (on) { this.target = 0; this.fogTarget = 0; }
    if (jump) { this.snow = on ? 1 : 0; this.cover = on ? 1 : 0; }
  }

  setFog(on, jump = false) {
    this.fogTarget = on ? 1 : 0;
    if (on) { this.target = 0; this.snowTarget = 0; }
    if (jump) this.fog = on ? 1 : 0;
  }

  // a lower draw count when the main thread is struggling
  setPerfLevel(level) {
    this.lines.geometry.setDrawRange(0, Math.round(this.n * [1, 1, 0.7, 0.5][clamp(level, 0, 3)] * 2));
    this.flakes.geometry.setDrawRange(0, Math.round(this.ns * [1, 1, 0.7, 0.5][clamp(level, 0, 3)]));
  }

  // dt: seconds of the world; camera: where the rain is gathered round
  update(dt, clock, camera, reduced) {
    this.reduced = reduced;
    WEATHER.uWT.value = clock;
    const tau = this.target > this.k ? 5 : 3.5;
    this.k += (this.target - this.k) * (1 - Math.exp(-Math.min(dt, 0.1) / tau));
    if (this.target === 0 && this.k < 0.004) this.k = 0;
    WEATHER.uRain.value = this.k;
    // after the storm: once the rain has thinned and the sun is out again, the bow forms opposite the sun, hangs a minute, fades
    if (this.k > 0.55) this.shower = 1;
    else this.shower = Math.max(0, this.shower - Math.min(dt, 0.1) / 90);
    const clear = 1 - clamp((this.k - 0.1) / 0.4);
    const sh = clamp(this.shower / 0.35);
    // (it forms slowly, over several seconds, and fades more slowly still)
    const want = sh * sh * (3 - 2 * sh) * clear * clear * (3 - 2 * clear);
    this.bow += (want - this.bow) * (1 - Math.exp(-Math.min(dt, 0.1) / (want > this.bow ? 7 : 12)));
    if (want === 0 && this.bow < 0.002) this.bow = 0;
    WEATHER.uBow.value = this.bow;
    // snow: falling (eased), lying (builds over about a minute of snow; lingers; melts, faster under rain)
    const sdt = Math.min(dt, 0.1);
    this.snow += (this.snowTarget - this.snow) * (1 - Math.exp(-sdt / (this.snowTarget > this.snow ? 7 : 9)));
    if (this.snowTarget === 0 && this.snow < 0.004) this.snow = 0;
    if (this.snow > 0.3) this.cover = Math.min(1, this.cover + sdt * this.snow / 55);
    else this.cover = Math.max(0, this.cover - sdt * (1 / 80 + this.k / 25));
    if (this.k > 0.25) this.wet = Math.min(1, this.wet + sdt * this.k / 20);
    else this.wet = Math.max(0, this.wet - sdt / (this.snow > 0.3 ? 20 : 110));
    WEATHER.uWet.value = this.wet;
    WEATHER.uSnow.value = this.snow;
    WEATHER.uCover.value = this.cover;
    // fog: it comes in slowly (a dozen seconds) and lifts a little quicker
    this.fog += (this.fogTarget - this.fog) * (1 - Math.exp(-sdt / (this.fogTarget > this.fog ? 9 : 6)));
    if (this.fogTarget === 0 && this.fog < 0.004) this.fog = 0;
    WEATHER.uFog.value = this.fog;
    this.overcast = Math.max(this.k, 0.8 * this.snow, 0.35 * this.fog);
    this.flakes.visible = this.snow > 0.003;
    this.lines.visible = this.k > 0.003;
    if (this.lines.visible || this.flakes.visible) this.uniforms.uCam.value.copy(camera.position);
    // lightning in a downpour: soft, double, with thunder after
    if (this.k > 0.75 && dt > 0) {
      this.nextBolt -= dt;
      if (this.nextBolt <= 0) {
        this.nextBolt = 9 + Math.random() * 14;
        const amp = 0.55 + Math.random() * 0.4;
        if (!reduced) this.bolts.push({ t0: clock, amp }, { t0: clock + 0.13 + Math.random() * 0.06, amp: amp * 0.6 });
        this.audio?.thunder(0.7 + Math.random() * 2.4, 0.5 + amp * 0.4);
      }
    }
    let f = 0;
    for (let i = this.bolts.length - 1; i >= 0; i--) {
      const b = this.bolts[i];
      const a = clock - b.t0;
      if (a > 0.9) { this.bolts.splice(i, 1); continue; }
      if (a < 0) continue;
      f += b.amp * (a < 0.035 ? a / 0.035 : Math.exp(-(a - 0.035) * 12));
    }
    this.flash = Math.min(1, f) * this.k;
    WEATHER.uFlash.value = this.flash;
  }

  // the hour's phases in the rain: the lamps kindle by day, the blooms glow, the butterflies roost
  phases(P) {
    const k = this.overcast;
    if (k <= 0) return P;
    const g = this.fog;
    return { ...P, night: Math.max(P.night, k * 0.35), lamps: Math.max(P.lamps, k * 0.9, g * 0.62), blooms: Math.max(P.blooms, k * 0.65, g * 0.35), flies: P.flies, rain: this.k };
  }
}
