import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { RNG } from '../core/rng.js';
import { clamp, lerp, sseg } from '../core/ease.js';
import { L } from '../world/layout.js';
import { SUN_DIR } from '../world/atmosphere.js';
import { groundY, GARDEN, MANOR, AXIS_X, OUT } from './scenery.js';
import { WIND } from '../world/wind.js';
import { WEATHER } from '../world/weatherU.js';

// What is outside the glass, beyond the lawns, hedges, trees and walls the scenery builds
// (interactive modes only):
//  · shadows on the ground that follow the sun: every tree's, long at evening, and the glasshouse's own;
//  · at the end of the north avenue, past the garden gate, a brick manor: its windows light up as the day goes;
//  · at the end of the south walk a domed temple; iron gates open in the north wall;
//  · lamps along both walks and at the gate, glowing at night, and borders of flowers.
// Everything takes the scenery's haze, cloud shadows and rain through `scenery.ext`.

const V = (x = 0, y = 0, z = 0) => new THREE.Vector3(x, y, z);
const TAU = Math.PI * 2;
const H = L.house;
const XC = (H.x0 + H.x1) / 2;
const ni = (g) => (g.index ? g.toNonIndexed() : g);

export class Outside {
  constructor({ scenery, quality }) {
    this.scenery = scenery;
    this.low = quality.tier === 'low';
    this.group = new THREE.Group();
    this.group.name = 'outside';
    this.rng = new RNG('outside');
    this.lit = []; // materials whose glow follows the night
    this._shadows();
    this._manor();
    this._plinthSkin();
    this._temple();
    this._gate();
    this._lamps();
    this._borders();
    this._leaves();
    this.t = 0;
  }

  // a Lambert box set on the ground (centre x, z; base at y)
  _put(mesh, x, y, z) { mesh.position.set(x, y, z); this.group.add(mesh); return mesh; }

  // ---- shadows -----------------------------------------------------------------------------
  // Trees: one flattened disc each, laid by the vertex shader from the sun's direction (no work on the CPU:
  // the shadow is the crown's, thrown along the light and stretched by 1/sin(elevation)). The glasshouse: the
  // outline of its base and its roof-line thrown the same way (a convex hull, soft edges from three layers).
  // Both only on the garden's level ground, and only while the sun is up and clear of cloud.
  _shadows() {
    const trees = this.scenery.treeInfo.filter((t) => t.x > GARDEN.x0 - 100 && t.x < GARDEN.x1 + 100 && t.z > GARDEN.z1 - 100 && t.z < MANOR.z + MANOR.r);
    const geo = new THREE.CircleGeometry(1, 24);
    geo.rotateX(-Math.PI / 2);
    const n = trees.length;
    const aTree = new Float32Array(n * 4), aBase = new Float32Array(n);
    trees.forEach((t, i) => { aTree.set([t.x, t.z, t.cy * t.s, t.cr * t.s], i * 4); aBase[i] = t.y + 6; });
    const ig = new THREE.InstancedBufferGeometry();
    ig.index = geo.index;
    ig.setAttribute('position', geo.attributes.position);
    ig.setAttribute('aTree', new THREE.InstancedBufferAttribute(aTree, 4));
    ig.setAttribute('aBase', new THREE.InstancedBufferAttribute(aBase, 1));
    ig.instanceCount = n;
    this.shadowU = { uSun: { value: new THREE.Vector4(0, 1, 1, 1) }, uDark: { value: 0 } };
    const common = { transparent: true, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -3, polygonOffsetUnits: -3, fog: false };
    const sm = new THREE.ShaderMaterial({
      uniforms: this.shadowU,
      ...common,
      vertexShader: `
        attribute vec4 aTree; attribute float aBase;
        uniform vec4 uSun; // xy: the way the light travels along the ground (unit), z: cot(elevation), w: 1 / sin(elevation)
        varying vec2 vU;
        void main() {
          vec2 away = uSun.xy, perp = vec2(-uSun.y, uSun.x);
          vU = position.xz;
          vec2 centre = aTree.xy + away * (aTree.z * uSun.z);
          vec2 p = centre + away * (vU.x * aTree.w * uSun.w) + perp * (vU.y * aTree.w);
          gl_Position = projectionMatrix * viewMatrix * vec4(p.x, aBase + 2.0, p.y, 1.0);
        }`,
      fragmentShader: `
        varying vec2 vU; uniform float uDark;
        void main() { float r = length(vU); gl_FragColor = vec4(0.015, 0.04, 0.02, (1.0 - smoothstep(0.3, 1.0, r)) * uDark); }`,
    });
    this.treeShadows = new THREE.Mesh(ig, sm);
    this.treeShadows.frustumCulled = false;
    this.treeShadows.renderOrder = 1;
    this.group.add(this.treeShadows);
    // the glasshouse's shadow: three stacked hulls, each a little larger and lighter, for a soft edge
    this.houseShadow = [0, 1, 2].map((k) => {
      const g = new THREE.BufferGeometry();
      g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(12 * 3), 3));
      g.setIndex([]);
      const m = new THREE.Mesh(g, new THREE.MeshBasicMaterial({ color: '#06120a', transparent: true, opacity: 0, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -3, polygonOffsetUnits: -3, fog: false }));
      m.frustumCulled = false;
      m.renderOrder = 1;
      m.userData.grow = [0, 16, 40][k];
      this.group.add(m);
      return m;
    });
  }

  _updateShadows() {
    const D = SUN_DIR;
    const el = Math.asin(clamp(-D.y, 0, 1));
    const horiz = Math.hypot(D.x, D.z) || 1;
    const sinE = Math.max(0.1, Math.sin(el));
    const dark = 0.34 * OUT.uSunK.value * sseg(el, 0.12, 0.38); // (about 7° to 22°)
    const U = this.shadowU;
    U.uDark.value = dark;
    U.uSun.value.set(D.x / horiz, D.z / horiz, Math.min(horiz / Math.max(-D.y, 0.12), 3.2), Math.min(1 / sinE, 3));
    // the house: hull of its base rectangle and its eave line and ridge, thrown along the light
    const ax = D.x / horiz, az = D.z / horiz, cot = Math.min(horiz / Math.max(-D.y, 0.12), 4);
    const pts = [];
    const add = (x, z, h) => pts.push([x + ax * h * cot, z + az * h * cot]);
    for (const [x, z] of [[H.x0, H.z0], [H.x1, H.z0], [H.x1, H.z1], [H.x0, H.z1]]) { add(x, z, 0); add(x, z, H.wall); }
    add(XC, H.z0, H.ridge); add(XC, H.z1, H.ridge);
    const hull = convexHull(pts);
    const cx = hull.reduce((s, p) => s + p[0], 0) / hull.length, cz = hull.reduce((s, p) => s + p[1], 0) / hull.length;
    for (const m of this.houseShadow) {
      const g = m.geometry.attributes.position;
      const grow = m.userData.grow;
      hull.forEach(([x, z], i) => {
        const dx = x - cx, dz = z - cz, l = Math.hypot(dx, dz) || 1;
        g.setXYZ(i, x + (dx / l) * grow, -1.2, z + (dz / l) * grow);
      });
      const idx = [];
      for (let i = 1; i < hull.length - 1; i++) idx.push(0, i + 1, i);
      m.geometry.setIndex(idx);
      g.needsUpdate = true;
      m.geometry.setDrawRange(0, idx.length);
      m.material.opacity = dark * (m.userData.grow === 0 ? 0.45 : 0.3);
      m.visible = dark > 0.01;
    }
    this.treeShadows.visible = dark > 0.01;
  }

  // ---- the manor ---------------------------------------------------------------------------
  _windowTile(emissive) {
    const s = 256;
    const cv = document.createElement('canvas');
    cv.width = cv.height = s;
    const x = cv.getContext('2d');
    const r = new RNG(emissive ? 'wintile-e' : 'wintile');
    if (emissive) { x.fillStyle = '#000'; x.fillRect(0, 0, s, s); } else {
      x.fillStyle = '#7c4a38';
      x.fillRect(0, 0, s, s);
      // brick courses
      const bh = 12;
      for (let row = 0; row < s / bh; row++) {
        for (let col = -1; col < 9; col++) {
          const ox = (row % 2) * 16;
          x.fillStyle = `hsl(${r.range(8, 20)}, ${r.range(35, 52)}%, ${r.range(26, 38)}%)`;
          x.fillRect(col * 32 + ox + 1, row * bh + 1, 30, bh - 2);
        }
      }
    }
    // the window: a stone surround, a white frame, six panes (two over three)
    const wx = 70, wy = 44, ww = 116, wh = 170;
    if (!emissive) {
      x.fillStyle = '#c9bfa6';
      x.fillRect(wx - 12, wy - 14, ww + 24, wh + 28); // surround
      x.fillStyle = '#d8d2c0';
      x.fillRect(wx - 16, wy + wh + 10, ww + 32, 9); // sill
      x.fillRect(wx - 16, wy - 22, ww + 32, 9); // lintel
      x.fillStyle = '#dcd6c8';
      x.fillRect(wx - 3, wy - 3, ww + 6, wh + 6); // frame
    }
    const pane = (px, py, pw, ph) => {
      if (emissive) { x.fillStyle = '#ffc77a'; } else { const g = x.createLinearGradient(px, py, px, py + ph); g.addColorStop(0, '#2b3a46'); g.addColorStop(1, '#161d24'); x.fillStyle = g; }
      x.fillRect(px, py, pw, ph);
    };
    for (let cx = 0; cx < 2; cx++) for (let cy = 0; cy < 3; cy++) pane(wx + 3 + cx * (ww / 2), wy + 3 + cy * (wh / 3), ww / 2 - 6, wh / 3 - 6);
    const t = new THREE.CanvasTexture(cv);
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.colorSpace = THREE.SRGBColorSpace;
    t.anisotropy = 8;
    return t;
  }

  _manor() {
    const g = this.group;
    const r = this.rng;
    const ext = (p, k, o) => this.scenery.ext(p, k, o);
    const baseY = groundY(MANOR.x, MANOR.z) + 1; // the level forecourt
    const BAY = [80, 70];
    OUT.uMan.value.set(MANOR.x, MANOR.z, baseY);
    // brick walls with a window in every bay; at night most of the windows are lit (a different few each evening hour)
    const wallMat = ext({ map: this._windowTile(false), emissiveMap: this._windowTile(true), emissive: new THREE.Color(1, 0.78, 0.45), color: '#ffffff' }, 'manor');
    this.windowMat = wallMat;
    this.lit.push({ mat: wallMat, scale: 1.6 });
    const roofMat = ext({ color: '#434a54' }, 'roof');
    const stoneMat = ext({ color: '#cfc7b3' }, 'stone'); // (weathered: the manor's columns, pediment, steps and terrace)
    const bayBox = (w, h, d) => {
      const geo = new THREE.BoxGeometry(w, h, d);
      const uv = geo.attributes.uv;
      const f = [[d, h], [d, h], [w, d], [w, d], [w, h], [w, h]]; // +x −x +y −y +z −z
      for (let face = 0; face < 6; face++) for (let i = 0; i < 4; i++) { const k = face * 4 + i; uv.setXY(k, uv.getX(k) * f[face][0] / BAY[0], uv.getY(k) * f[face][1] / BAY[1]); }
      return geo;
    };
    const gableRoof = (w, d, h, ridgeAlongX) => {
      // a prism: base w × d, ridge at height h along x or z
      const a = ridgeAlongX ? d / 2 : w / 2, b = ridgeAlongX ? w / 2 : d / 2;
      const P = (u, y, v) => (ridgeAlongX ? [v, y, u] : [u, y, v]);
      const tri = (p, q, s) => [...p, ...q, ...s];
      const pos = [
        ...tri(P(-a, 0, -b), P(0, h, -b), P(-a, 0, b)), ...tri(P(-a, 0, b), P(0, h, -b), P(0, h, b)), // slope 1
        ...tri(P(a, 0, -b), P(a, 0, b), P(0, h, -b)), ...tri(P(a, 0, b), P(0, h, b), P(0, h, -b)), // slope 2
      ];
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
      geo.computeVertexNormals();
      return geo;
    };
    const gableEnd = (w, h) => {
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.Float32BufferAttribute([-w / 2, 0, 0, w / 2, 0, 0, 0, h, 0], 3));
      geo.setAttribute('uv', new THREE.Float32BufferAttribute([0, 0, w / BAY[0], 0, w / BAY[0] / 2, h / BAY[1]], 2));
      geo.computeVertexNormals();
      return geo;
    };
    const at = (x, y, z) => ({ x: MANOR.x + x, y: baseY + y, z: MANOR.z + z });
    const put = (geo, mat, x, y, z, ry = 0, cast = false) => { const m = new THREE.Mesh(geo, mat); const p = at(x, y, z); m.position.set(p.x, p.y, p.z); m.rotation.y = ry; g.add(m); return m; };
    // the manor faces south, toward the glasshouse (its front at z = -120)
    const W = 480, D = 240, HH = 210;
    put(bayBox(W, HH, D), wallMat, 0, HH / 2, 0);
    for (const sd of [-1, 1]) {
      put(bayBox(160, HH, 240), wallMat, sd * 320, HH / 2, -20);
      put(gableRoof(176, 256, 90, false), roofMat, sd * 320, HH, -20);
      put(gableEnd(176, 90), wallMat, sd * 320, HH, -20 - 128 + 0.5);
    }
    put(gableRoof(W + 24, D + 24, 100, true), roofMat, 0, HH, 0);
    // chimneys with pots
    const chim = [[-170, 40], [-60, 40], [90, 40], [190, 40], [-330, 90], [330, 90]];
    const chimGeo = new THREE.BoxGeometry(22, 64, 22);
    const potGeo = new THREE.CylinderGeometry(5, 6, 14, 8);
    for (const [cx, cz] of chim) {
      put(chimGeo, wallMat, cx, HH + 80 + (Math.abs(cx) > 300 ? -30 : 0), cz);
      put(potGeo, stoneMat, cx, HH + 120 + (Math.abs(cx) > 300 ? -30 : 0), cz);
    }
    // a portico: four columns under a pediment, steps up to the door
    for (const cx of [-48, -16, 16, 48]) put(new THREE.CylinderGeometry(5, 6, 78, 12), stoneMat, cx, 39, -140);
    put(new THREE.BoxGeometry(150, 12, 64), stoneMat, 0, 84, -140);
    put(gableRoof(160, 66, 26, false), stoneMat, 0, 90, -140);
    for (let i = 0; i < 4; i++) put(new THREE.BoxGeometry(180, 5 * (4 - i), 22), stoneMat, 0, 2.5 * (4 - i), -176 - i * 20);
    // a balustraded terrace along the front
    put(new THREE.BoxGeometry(920, 14, 8), stoneMat, 0, 7, -300);
    for (const sd of [-1, 1]) put(new THREE.BoxGeometry(8, 14, 130), stoneMat, sd * 460, 7, -240);
    // gravel forecourt, an avenue from the gate to it, and a lawn island in the sweep
    const gravel = ext({ color: '#c9b894' }, 'gravel');
    const fore = new THREE.Mesh(new THREE.CircleGeometry(300, 40), gravel);
    fore.rotation.x = -Math.PI / 2;
    const fp = at(0, 0.6, -520);
    fore.position.set(fp.x, fp.y, fp.z);
    g.add(fore);
    const island = new THREE.Mesh(new THREE.CircleGeometry(95, 32), ext({ color: '#6e8f3c' }));
    island.rotation.x = -Math.PI / 2;
    island.position.set(fp.x, fp.y + 0.4, fp.z);
    g.add(island);
    this._ribbon(GARDEN.z0 + 20, MANOR.z - 330, 62, gravel);
    // (a few more lamps at the door)
    this.doorLamps = [[-90, -150], [90, -150], [-200, -125], [200, -125]].map(([x, z]) => at(x, 40, z));
  }

  // a strip of gravel along the axis that follows the ground
  _ribbon(z0, z1, hw, mat) {
    const pos = [], idx = [];
    const step = 24;
    let k = 0;
    for (let z = z0; z <= z1 + step; z += step) {
      const zz = Math.min(z, z1);
      for (const sx of [-1, 1]) { const x = AXIS_X + sx * hw; pos.push(x, groundY(x, zz) + 0.8, zz); }
      if (k > 0) { const a = (k - 1) * 2; idx.push(a, a + 1, a + 2, a + 1, a + 3, a + 2); }
      k++;
      if (zz >= z1) break;
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    geo.setIndex(idx);
    geo.computeVertexNormals();
    const m = new THREE.Mesh(geo, mat);
    m.frustumCulled = false;
    this.group.add(m);
  }

  // ---- the glasshouse's stone base, as the garden sees it ------------------------------------------------
  // The plinth the glass stands on (world/greenhouse.js, and the gable plinths in scenery.js) is the interior's material: a dark scanned stone that, from out here, is
  // a black wall seventy units high. Dressed stone is laid over its outer faces (an `ext` material, so it takes the sun, the haze, the wet, the lamps' light), and a thin
  // coping on top of the outer half, which is what the snow lies on.
  _plinthSkin() {
    const g = this.group, H = L.house;
    const mat = this.scenery.ext({ map: this._blockTexture(), color: '#ffffff' }, 'stone');
    const coping = this.scenery.ext({ color: '#cfc3a8' }, 'stone');
    const doorX0 = L.pathX[0] - 8, doorX1 = L.pathX[1] + 8;
    const y0 = -2, y1 = 68, hgt = y1 - y0, cx = (a, b) => (a + b) / 2;
    const face = (w, rotY, x, z) => {
      const geo = new THREE.PlaneGeometry(w, hgt);
      const uv = geo.attributes.uv;
      for (let i = 0; i < uv.count; i++) uv.setXY(i, uv.getX(i) * w / 70, uv.getY(i) * hgt / 70);
      const m = new THREE.Mesh(geo, mat);
      m.position.set(x, y0 + hgt / 2, z);
      m.rotation.y = rotY;
      m.frustumCulled = false;
      g.add(m);
    };
    const len = H.z0 - H.z1, zc = cx(H.z0, H.z1);
    face(len, Math.PI / 2, H.x1 + 9.25, zc);   // east side (faces +x)
    face(len, -Math.PI / 2, H.x0 - 9.25, zc);  // west side (faces -x)
    for (const [a, b] of [[H.x0 + 9, doorX0], [doorX1, H.x1 - 9]]) {
      face(b - a, 0, cx(a, b), H.z0 + 7.25);               // the north end, either side of the doors (faces +z)
      face(b - a, Math.PI, cx(a, b), H.z1 - 1.25);         // the south end (faces -z)
    }
    for (const sx of [-1, 1]) face(18, 0, sx < 0 ? H.x0 : H.x1, H.z0 + 0.25); // (the corners, where the side plinths end short of the gable plinths)
    for (const [x0, x1] of [[H.x0 - 9.3, H.x0 - 1], [H.x1 + 1, H.x1 + 9.3]]) {
      const c = new THREE.Mesh(new THREE.BoxGeometry(x1 - x0, 1.4, len), coping);
      c.position.set(cx(x0, x1), y1 + 0.5, zc);
      c.frustumCulled = false;
      g.add(c);
    }
  }

  // a box whose texture coordinates run in world units (one ashlar tile is 70 across), so that the courses stay the size they are everywhere else
  _ashlarBox(w, h, d) {
    const geo = new THREE.BoxGeometry(w, h, d);
    const n = geo.attributes.normal, uv = geo.attributes.uv;
    for (let i = 0; i < uv.count; i++) {
      const ax = Math.abs(n.getX(i)), ay = Math.abs(n.getY(i));
      const fw = ax > 0.5 ? d : w, fh = ay > 0.5 ? d : h; // (the face's width and height in world units)
      uv.setXY(i, uv.getX(i) * fw / 70, uv.getY(i) * fh / 70);
    }
    return geo;
  }

  // ashlar: four courses to the tile, the joints staggered, each stone its own warm grey-yellow
  _blockTexture() {
    if (this._ashlar) return this._ashlar;
    const s = 256, cv = document.createElement('canvas');
    cv.width = cv.height = s;
    const x = cv.getContext('2d');
    x.fillStyle = '#7d7260';
    x.fillRect(0, 0, s, s);
    const r = new RNG('ashlar');
    const ch = s / 4;
    for (let row = 0; row < 4; row++) {
      const n = row % 2 ? 3 : 2, bw = s / 2, off = row % 2 ? -bw / 2 : 0;
      for (let k = -1; k < 3; k++) {
        const hue = r.range(32, 44), sat = r.range(16, 28), lig = r.range(58, 72);
        x.fillStyle = `hsl(${hue}, ${sat}%, ${lig}%)`;
        x.fillRect(off + k * bw + 2, row * ch + 2, bw - 4, ch - 4);
      }
    }
    for (let i = 0; i < 2600; i++) { const v = r.range(0, 1) < 0.5 ? 255 : 0; x.fillStyle = `rgba(${v},${v},${v},${r.range(0.02, 0.07)})`; x.fillRect(r.range(0, s), r.range(0, s), r.range(1, 3), r.range(1, 3)); }
    for (let i = 0; i < 40; i++) { x.fillStyle = `rgba(40,34,26,${r.range(0.03, 0.09)})`; x.fillRect(r.range(0, s), r.range(0, s), r.range(1, 3), r.range(14, 50)); }
    const t = new THREE.CanvasTexture(cv);
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.colorSpace = THREE.SRGBColorSpace;
    t.anisotropy = 8;
    this._ashlar = t;
    return t;
  }

  // ---- the temple at the end of the south walk -------------------------------------------------
  _temple() {
    const g = this.group;
    const ext = (p, k) => this.scenery.ext(p, k);
    const stone = ext({ color: '#d8d1bf' }, 'stone');
    const shaft = ext({ color: '#d8d1bf' }, 'column');
    const copper = ext({ color: '#5f9c86' }, 'copper');
    const x = AXIS_X, z = -2440, y = -3;
    const add = (geo, mat, px, py, pz) => { const m = new THREE.Mesh(geo, mat); m.position.set(x + px, y + py, z + pz); g.add(m); return m; };
    // stylobate: three steps
    [[118, 5], [108, 5], [98, 5]].forEach(([rad, h], i) => add(new THREE.CylinderGeometry(rad, rad + 2, h, 28), stone, 0, i * 5 + 2.5, 0));
    // eight columns, an entablature, a dome and a lantern
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * TAU;
      add(new THREE.CylinderGeometry(7, 8.5, 128, 32), shaft, Math.cos(a) * 80, 15 + 64, Math.sin(a) * 80);
      add(new THREE.CylinderGeometry(10, 8, 6, 10), stone, Math.cos(a) * 80, 15 + 128 + 3, Math.sin(a) * 80);
    }
    add(new THREE.CylinderGeometry(90, 90, 14, 28), stone, 0, 15 + 128 + 13, 0);
    const dome = new THREE.Mesh(new THREE.SphereGeometry(86, 28, 14, 0, TAU, 0, Math.PI / 2), copper);
    dome.position.set(x, y + 15 + 128 + 20, z);
    g.add(dome);
    add(new THREE.CylinderGeometry(9, 12, 26, 12), stone, 0, 15 + 128 + 20 + 86 + 6, 0);
    add(new THREE.SphereGeometry(7, 12, 8), copper, 0, 15 + 128 + 20 + 86 + 26, 0);
    // a statue on a plinth inside
    add(new THREE.CylinderGeometry(12, 14, 24, 10), stone, 0, 15 + 12, 0);
    add(new THREE.CapsuleGeometry(7, 34, 4, 8), stone, 0, 15 + 24 + 22, 0);
    // a lantern hung from the dome over the statue, lit at dusk (the light on the land is `extraLamps`, the halo and the bulb here)
    this.templeBulb = new THREE.Mesh(new THREE.SphereGeometry(6, 14, 10), new THREE.MeshBasicMaterial({ color: new THREE.Color(1, 0.72, 0.38), fog: false }));
    this.templeBulb.position.set(x, y + 118, z);
    g.add(this.templeBulb);
    add(new THREE.CylinderGeometry(0.8, 0.8, 30, 5), stone, 0, 15 + 128 + 13 - 5, 0);
    (this.extraLamps ||= []).push(V(x, y + 118, z));
    // where a bee can settle: the statue's head and the copper ball on the lantern
    (this.perches ||= []).push({ name: 'the temple statue', x, y: y + 15 + 24 + 22 + 17 + 7, z, r: 5 }, { name: "the temple's copper finial", x, y: y + 15 + 128 + 20 + 86 + 26 + 7, z, r: 4.5 });
  }

  // ---- the north gate -------------------------------------------------------------------------
  _gate() {
    const g = this.group;
    const iron = this.scenery.ext({ color: '#1c1f22' });
    const stone = this.scenery.ext({ map: this._blockTexture(), color: '#ffffff' }, 'stone');
    const x0 = L.pathX[0] - 40, x1 = L.pathX[1] + 40, z = GARDEN.z0;
    const leafW = (x1 - x0) / 2 - 6;
    // one leaf, hinged at its origin and reaching along +x: a frame, round bars with spear heads, a scroll
    const parts = [];
    const bar = (px, py, sx, sy) => parts.push(new THREE.BoxGeometry(sx, sy, 3).translate(px, py, 0));
    const h = 116;
    bar(leafW / 2, 0, leafW, 3.2); bar(leafW / 2, h, leafW, 3.2); bar(0, h / 2, 3.2, h); bar(leafW, h / 2, 3.2, h); bar(leafW / 2, h * 0.5, leafW, 2);
    for (let u = 12; u < leafW - 6; u += 11) {
      parts.push(new THREE.CylinderGeometry(0.9, 0.9, h, 5).translate(u, h / 2, 0));
      parts.push(new THREE.ConeGeometry(2, 7, 5).translate(u, h + 3, 0));
    }
    const arc = new THREE.TorusGeometry(leafW / 4, 1.1, 5, 14, Math.PI);
    parts.push(arc.clone().translate(leafW / 4, h * 0.82, 0), arc.clone().translate(leafW * 0.75, h * 0.82, 0));
    const leafGeo = mergeGeometries(parts.map(ni));
    // both leaves stand open toward the manor (the hinges on the piers)
    const open = 1.2;
    const left = new THREE.Mesh(leafGeo, iron);
    left.position.set(x0 + 14, groundY(x0, z) + 1, z + 3);
    left.rotation.y = -open;
    const right = new THREE.Mesh(leafGeo, iron);
    right.position.set(x1 - 14, groundY(x1, z) + 1, z + 3);
    right.scale.x = -1;
    right.rotation.y = open;
    g.add(left, right);
    // stone piers carry lanterns (lit at night)
    this.gateLamps = [];
    for (const px of [x0, x1]) {
      const gy = groundY(px, z);
      const pier = new THREE.Mesh(this._ashlarBox(46, 190, 46), stone);
      pier.position.set(px, gy + 95, z);
      const cap = new THREE.Mesh(this._ashlarBox(60, 14, 60), stone);
      cap.position.set(px, gy + 197, z);
      const ball = new THREE.Mesh(new THREE.SphereGeometry(13, 12, 8), stone);
      ball.position.set(px, gy + 214, z);
      g.add(pier, cap, ball);
      this.gateLamps.push(V(px, gy + 238, z));
    }
  }

  // ---- lamps ------------------------------------------------------------------------------------
  _lamps() {
    const g = this.group;
    const r = this.rng;
    const iron = this.scenery.ext({ color: '#1a1d20' });
    const pos = [];
    // along the north walk (from the house to the gate and on to the manor) and the south walk
    for (let z = H.z0 + 130; z < GARDEN.z0 - 40; z += 170) for (const sx of [-1, 1]) pos.push(V(AXIS_X + sx * 38, groundY(AXIS_X + sx * 38, z), z));
    for (let z = GARDEN.z0 + 140; z < MANOR.z - 420; z += 200) for (const sx of [-1, 1]) pos.push(V(AXIS_X + sx * 78, groundY(AXIS_X + sx * 78, z), z));
    for (let z = H.z1 - 130; z > -2300; z -= 170) for (const sx of [-1, 1]) pos.push(V(AXIS_X + sx * 38, groundY(AXIS_X + sx * 38, z), z));
    this.lampPos = pos;
    for (const p of pos) (this.perches ||= []).push({ name: 'a lamp post', x: p.x, y: p.y + 83, z: p.z, r: 3.5 }); // (the cap of the lantern: somewhere to settle)
    // pole, collar, lantern cage
    const poleGeo = mergeGeometries([
      ni(new THREE.CylinderGeometry(1.4, 2.2, 56, 7).translate(0, 28, 0)),
      ni(new THREE.CylinderGeometry(4.5, 4.5, 3, 8).translate(0, 57, 0)),
      ni(new THREE.ConeGeometry(7, 7, 8).translate(0, 79, 0)),
      ni(new THREE.BoxGeometry(3.6, 2.4, 3.6).translate(0, 59, 0)),
    ]);
    const poles = new THREE.InstancedMesh(poleGeo, iron, pos.length);
    pos.forEach((p, i) => poles.setMatrixAt(i, new THREE.Matrix4().makeTranslation(p.x, p.y, p.z)));
    poles.computeBoundingSphere();
    g.add(poles);
    // the glow: a small lamp, and a halo that blooms in the lens
    const lampGeo = new THREE.SphereGeometry(5, 18, 12);
    const lampMat = new THREE.MeshBasicMaterial({ color: new THREE.Color(1, 0.72, 0.38), fog: false });
    const lamps = new THREE.InstancedMesh(lampGeo, lampMat, pos.length);
    pos.forEach((p, i) => lamps.setMatrixAt(i, new THREE.Matrix4().makeTranslation(p.x, p.y + 68, p.z)));
    lamps.computeBoundingSphere();
    g.add(lamps);
    this.lampMat = lampMat;
    this.glow = this._glow([...pos.map((p) => V(p.x, p.y + 68, p.z)), ...(this.extraLamps || []), ...this.gateLamps, ...this.doorLamps.map((p) => V(p.x, p.y, p.z))]);
  }

  // additive halos at the lamp positions: soft round sprites sized in world units, faded out close to the
  // lens (a lamp beside the camera is a lamp, not a disc) and clamped in pixels
  _glow(points) {
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(points.flatMap((p) => [p.x, p.y, p.z]), 3));
    const mat = new THREE.ShaderMaterial({
      uniforms: { uColor: { value: new THREE.Color(1, 0.7, 0.35) }, uOpacity: { value: 0 }, uPix: { value: 1 } },
      vertexShader: `
        uniform float uPix; varying float vNear;
        void main() {
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          float d = -mv.z;
          gl_PointSize = clamp(46.0 * 700.0 * uPix / max(d, 1.0), 2.0, 150.0 * uPix);
          vNear = smoothstep(60.0, 380.0, d);
          gl_Position = projectionMatrix * mv;
        }`,
      fragmentShader: `
        uniform vec3 uColor; uniform float uOpacity; varying float vNear;
        void main() {
          float r = length(gl_PointCoord - 0.5) * 2.0;
          float a = pow(max(1.0 - r, 0.0), 2.2);
          gl_FragColor = vec4(uColor * a * uOpacity * vNear, 1.0);
        }`,
      transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, fog: false,
    });
    const pts = new THREE.Points(geo, mat);
    pts.frustumCulled = false;
    pts.renderOrder = 3;
    this.group.add(pts);
    return mat;
  }

  // ---- flower borders ---------------------------------------------------------------------------
  _borders() {
    const g = this.group;
    const r = this.rng;
    const c = new THREE.Color();
    const spots = [];
    // along both walks outside the hedges
    for (let z = H.z0 + 100; z < GARDEN.z0 - 60; z += 12) for (const sx of [-1, 1]) spots.push([AXIS_X + sx * 66 + r.range(-4, 4), z]);
    for (let z = H.z1 - 100; z > -2250; z -= 12) for (const sx of [-1, 1]) spots.push([AXIS_X + sx * 66 + r.range(-4, 4), z]);
    // round the glasshouse's foot
    for (let z = H.z1 + 20; z < H.z0 - 10; z += 15) for (const x of [H.x0 - 60, H.x1 + 60]) spots.push([x, z]);
    for (let x = H.x0 - 40; x < H.x1 + 40; x += 15) for (const z of [H.z0 + 60, H.z1 - 60]) if (x < L.pathX[0] - 50 || x > L.pathX[1] + 50) spots.push([x, z]);
    const blob = ni(new THREE.IcosahedronGeometry(1, 1));
    blob.translate(0, 0.35, 0);
    const im = new THREE.InstancedMesh(blob, this.scenery.ext({ color: '#ffffff' }, 'foliage'), spots.length);
    const PAL = [[0.96, 0.75, 0.5], [0.98, 0.8, 0.55], [0.75, 0.55, 0.45], [0.07, 0.95, 0.52], [0.14, 0.95, 0.55], [0.0, 0.0, 0.9], [0.66, 0.6, 0.4], [0.02, 0.85, 0.42]];
    this.beds = []; // (where a bee can settle: the crown of each mound)
    spots.forEach(([x, z], i) => {
      const s = r.range(5, 9);
      const jx = r.range(-4, 4), jz = r.range(-4, 4), ang = r.range(0, TAU), sx = s * r.range(1, 1.5), sy = s * r.range(0.7, 1.1), sz = s * r.range(1, 1.5);
      const gy = groundY(x, z) - 1;
      this.beds.push({ x: x + jx, y: gy + 1.35 * sy, z: z + jz, r: Math.max(3, 0.4 * Math.min(sx, sz)) });
      im.setMatrixAt(i, new THREE.Matrix4().compose(V(x + jx, gy, z + jz), new THREE.Quaternion().setFromAxisAngle(V(0, 1, 0), ang), V(sx, sy, sz)));
      const p = PAL[Math.floor(r.range(0, PAL.length))];
      im.setColorAt(i, c.setHSL(p[0] + r.range(-0.02, 0.02), p[1], p[2] * r.range(0.8, 1.1)));
    });
    im.computeBoundingSphere();
    g.add(im);
  }

  // ---- autumn leaves, drifting down outside the glass -----------------------------------------------
  // Quads wrapped round the camera (none inside the house), turning and tumbling as they fall, carried by the breeze.
  _leaves() {
    if (this.low) { this.leaves = null; return; }
    const n = 220;
    const quad = new THREE.PlaneGeometry(1, 1);
    const ig = new THREE.InstancedBufferGeometry();
    ig.index = quad.index;
    ig.setAttribute('position', quad.attributes.position);
    ig.setAttribute('uv', quad.attributes.uv);
    const r = new RNG('leaves');
    const seed = new Float32Array(n * 4), col = new Float32Array(n * 3);
    const c = new THREE.Color();
    for (let i = 0; i < n; i++) {
      seed.set([r.float(), r.float(), r.float(), r.float()], i * 4);
      const hue = [0.14, 0.115, 0.085, 0.05, 0.02][Math.floor(r.range(0, 5))];
      c.setHSL(hue + r.range(-0.01, 0.01), r.range(0.6, 0.85), r.range(0.3, 0.45));
      col.set([c.r, c.g, c.b], i * 3);
    }
    ig.setAttribute('aSeed', new THREE.InstancedBufferAttribute(seed, 4));
    ig.setAttribute('aCol', new THREE.InstancedBufferAttribute(col, 3));
    ig.instanceCount = n;
    this.leafU = {
      uCam: { value: new THREE.Vector3() }, uT: WEATHER.uWT, uWind: WIND.u.uWind, uVis: { value: 1 }, uLight: { value: 1 },
      uHouse: { value: new THREE.Vector4(H.x0, H.x1, H.z1, H.z0) }, uArch: { value: new THREE.Vector2(H.wall, H.ridge) },
    };
    const mat = new THREE.ShaderMaterial({
      uniforms: this.leafU,
      vertexShader: `
        attribute vec4 aSeed; attribute vec3 aCol;
        uniform vec3 uCam; uniform float uT, uVis; uniform vec4 uWind, uHouse; uniform vec2 uArch;
        varying vec2 vUv; varying vec3 vCol; varying float vA;
        void main() {
          const float BOX = 1000.0, HH = 520.0;
          float drift = 12.0 + 10.0 * aSeed.w, fall = 15.0 + 11.0 * aSeed.w;
          vec3 p;
          p.xz = uCam.xz + mod( aSeed.xy * BOX + uWind.xy * uT * drift - uCam.xz + 0.5 * BOX, BOX ) - 0.5 * BOX;
          p.y = uCam.y + mod( aSeed.z * HH - uT * fall - uCam.y + 0.5 * HH, HH ) - 0.5 * HH;
          p.xz += vec2( sin( uT * 1.3 + aSeed.w * 30.0 ), cos( uT * 1.1 + aSeed.z * 20.0 ) ) * 16.0;
          // none inside the glasshouse
          float cx = ( uHouse.x + uHouse.y ) * 0.5, hw = ( uHouse.y - uHouse.x ) * 0.5;
          float kx = clamp( ( p.x - cx ) / hw, -1.0, 1.0 );
          float roof = uArch.x + ( uArch.y - uArch.x ) * sqrt( max( 0.0, 1.0 - kx * kx ) );
          bool inside = p.x > uHouse.x - 8.0 && p.x < uHouse.y + 8.0 && p.z < uHouse.w + 8.0 && p.z > uHouse.z - 8.0 && p.y < roof + 8.0;
          float ang = uT * ( 1.0 + aSeed.w * 2.0 ) + aSeed.z * 6.2832;
          vec2 q = position.xy * ( 11.0 + 8.0 * aSeed.w );
          q.x *= 0.25 + 0.75 * abs( cos( uT * ( 1.4 + aSeed.w ) + aSeed.x * 20.0 ) ); // (tumbling)
          q = mat2( cos( ang ), -sin( ang ), sin( ang ), cos( ang ) ) * q;
          vec4 mv = viewMatrix * vec4( p, 1.0 );
          mv.xy += q;
          vUv = uv; vCol = aCol;
          vA = inside || p.y < 0.0 ? 0.0 : uVis * smoothstep( 40.0, 120.0, -mv.z );
          gl_Position = vA > 0.0 ? projectionMatrix * mv : vec4( 2.0, 2.0, 2.0, 1.0 );
        }`,
      fragmentShader: `
        uniform float uLight; varying vec2 vUv; varying vec3 vCol; varying float vA;
        void main() {
          // a leaf: pointed at both ends, widest a little below the middle, a pale rib down it
          vec2 q = ( vUv - 0.5 ) * 2.0;
          float lw = 0.55 * pow( max( 1.0 - q.y * q.y, 0.0 ), 0.75 ) * ( 1.0 - 0.25 * q.y );
          float shape = 1.0 - smoothstep( lw * 0.8, lw, abs( q.x ) );
          float rib = 1.0 + 0.25 * ( 1.0 - smoothstep( 0.0, 0.06, abs( q.x ) ) );
          if ( shape * vA < 0.04 ) discard;
          gl_FragColor = vec4( vCol * rib * uLight, shape * vA );
        }`,
      transparent: true, depthWrite: false, side: THREE.DoubleSide, fog: false,
    });
    this.leaves = new THREE.Mesh(ig, mat);
    this.leaves.frustumCulled = false;
    this.leaves.renderOrder = 2;
    this.group.add(this.leaves);
  }

  // ---- per frame ---------------------------------------------------------------------------------
  update(t, dt, ctx) {
    this.t = t;
    const night = OUT.uNight.value;
    // the lamps glow at dusk and through the night (and in a storm); the manor's windows with them
    const dusk = clamp(Math.max(night, ctx.stormGlow ?? 0));
    this.duskK = dusk;
    this.lampMat.color.setRGB(1, 0.72, 0.38).multiplyScalar(0.25 + 2.4 * dusk);
    this.templeBulb?.material.color.setRGB(1, 0.72, 0.38).multiplyScalar(0.25 + 2.4 * dusk);
    this.glow.uniforms.uOpacity.value = 1.5 * dusk * dusk;
    this.glow.visible = dusk > 0.02;
    for (const l of this.lit) l.mat.emissiveIntensity = (0.04 + l.scale * dusk) * 1.0;
    this._updateShadows();
    this.glow.uniforms.uPix.value = ctx.pixelRatio ?? 1;
    if (this.leaves && ctx.camera) {
      this.leafU.uCam.value.copy(ctx.camera.position);
      this.leafU.uVis.value = (1 - WEATHER.uRain.value) * (1 - Math.min(1, WEATHER.uSnow.value * 2)); // (no leaves in rain or snow)
      this.leafU.uLight.value = 0.22 + 0.78 * OUT.uSunK.value;
    }
  }
}

// the convex hull of 2-D points (monotone chain), counter-clockwise
function convexHull(points) {
  const p = points.slice().sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const cross = (o, a, b) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
  const lower = [];
  for (const q of p) { while (lower.length >= 2 && cross(lower[lower.length - 2], lower[lower.length - 1], q) <= 0) lower.pop(); lower.push(q); }
  const upper = [];
  for (let i = p.length - 1; i >= 0; i--) { const q = p[i]; while (upper.length >= 2 && cross(upper[upper.length - 2], upper[upper.length - 1], q) <= 0) upper.pop(); upper.push(q); }
  upper.pop(); lower.pop();
  return lower.concat(upper);
}
