import * as THREE from 'three';
import { SUN_DIR } from './atmosphere.js';
import { WEATHER } from './weatherU.js';

// The sky beyond the glass: midnight teal with a few stars, warming to a
// golden morning. A large inside-out sphere, unaffected by fog.

export class Sky {
  constructor() {
    this.uniforms = {
      uDawn: { value: 0 },
      uSunDir: { value: SUN_DIR.clone().negate() },
      uClouds: { value: 0 }, // interactive modes: drifting clouds and a moon
      uTime: { value: 0 },
      uStorm: WEATHER.uRain, // (the explore variant only: weather)
      uFlash: WEATHER.uFlash,
      uBow: WEATHER.uBow,
      uSnow: WEATHER.uSnow,
      uFog: WEATHER.uFog,
    };
    this.mesh = new THREE.Mesh(
      new THREE.SphereGeometry(6000, 48, 24),
      new THREE.ShaderMaterial({
        side: THREE.BackSide,
        depthWrite: false,
        fog: false,
        uniforms: this.uniforms,
        vertexShader: `varying vec3 vDir; void main(){ vDir = normalize(position); vec4 p = projectionMatrix * modelViewMatrix * vec4(position, 1.0); gl_Position = p.xyww; }`,
        fragmentShader: `
          uniform float uDawn; uniform vec3 uSunDir; uniform float uClouds, uTime; varying vec3 vDir;
          #ifdef CG_EXPLORE_NIGHT
          uniform float uStorm, uFlash, uBow, uSnow, uFog;
          // a rainbow's colours across its band: 0 violet … 1 red (pastel, as the real thing is)
          vec3 cgSpectrum(float t) {
            float h = (1.0 - t) * 0.76;
            vec3 k = clamp(abs(mod(h * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
            return mix(vec3(1.0), k, 0.8) * (0.5 + 0.5 * smoothstep(0.0, 0.3, t));
          }
          #endif
          float hash(vec3 p){ return fract(sin(dot(p, vec3(12.9898,78.233,37.719))) * 43758.5453); }
          float h2(vec2 p){ return fract(sin(dot(p, vec2(41.3, 289.1))) * 43758.5453); }
          float n2(vec2 p){ vec2 i = floor(p), f = fract(p); f = f*f*(3.0-2.0*f);
            return mix(mix(h2(i), h2(i+vec2(1,0)), f.x), mix(h2(i+vec2(0,1)), h2(i+vec2(1,1)), f.x), f.y); }
          float fbm(vec2 p){ float s = 0.0, a = 0.5; for (int i = 0; i < 5; i++){ s += a * n2(p); p = p * 2.03 + 17.1; a *= 0.5; } return s; }
          #ifdef CG_EXPLORE_NIGHT
          // a shooting star: one streak per slot every "period" seconds, lasting about a second (the other 95% of the time this is a compare and a return);
          // it starts somewhere on the upper sky, runs along a random great circle, and leaves a thin, bright trail with a soft glow for the bloom to take up
          vec3 cgMeteor( vec3 v, float t, float period, float seed ) {
            float ph = t / period + seed;
            float n = floor( ph ), f = fract( ph ), dur = 0.05;
            if ( f > dur ) return vec3( 0.0 );
            float u = f / dur;
            float h1 = hash( vec3( n, seed, 1.0 ) ), h2 = hash( vec3( n, seed, 2.0 ) ), h3 = hash( vec3( n, seed, 3.0 ) ), h4 = hash( vec3( n, seed, 4.0 ) );
            float az = h1 * 6.2831853, el = 0.3 + 0.95 * h2;
            vec3 p0 = vec3( cos( el ) * sin( az ), sin( el ), cos( el ) * cos( az ) );
            if ( dot( v, p0 ) < 0.93 ) return vec3( 0.0 );
            vec3 e1 = normalize( cross( p0, vec3( 0.0, 1.0, 0.0 ) ) ), e2 = cross( p0, e1 );
            float ang = h3 * 6.2831853;
            vec3 td = e1 * cos( ang ) + e2 * sin( ang );
            float L = 0.26, head = u * 1.15 * L;
            float along = dot( v, td );
            float side = length( v - p0 * dot( v, p0 ) - td * along );
            float tail = smoothstep( head - 0.5 * L, head, along ) * ( 1.0 - smoothstep( head, head + 0.004, along ) ) * step( -0.02, along );
            float env = sin( 3.14159265 * u );
            float core = exp( -side * side / 3.0e-6 ), glow = exp( -side * side / 5.0e-5 );
            vec3 col = mix( vec3( 0.75, 0.88, 1.0 ), vec3( 1.0, 0.82, 0.6 ), h4 );
            return col * ( core * 4.0 + glow * 0.6 ) * tail * env * ( 0.5 + 0.5 * tail );
          }
          #endif
          void main(){
            float y = clamp(vDir.y, -0.2, 1.0);
            vec3 nightTop = vec3(0.004, 0.018, 0.024), nightHor = vec3(0.018, 0.06, 0.07);
            vec3 dayTop = vec3(0.1, 0.25, 0.3), dayHor = vec3(0.92, 0.6, 0.3);
            vec3 top = mix(nightTop, dayTop, uDawn), hor = mix(nightHor, dayHor, uDawn);
            vec3 c = mix(hor, top, pow(max(y, 0.0), 0.5));
            float s = max(dot(vDir, normalize(uSunDir)), 0.0);
            c += vec3(1.6, 1.05, 0.55) * (pow(s, 600.0) * 30.0 + pow(s, 6.0) * 1.1 + pow(s, 2.0) * 0.15) * uDawn;
            // stars fade with the dawn
            vec3 q = floor(vDir * 420.0);
            float st = step(0.9975, hash(q)) * (1.0 - smoothstep(0.0, 0.35, uDawn)) * smoothstep(0.05, 0.4, y);
            c += vec3(0.7, 0.85, 0.9) * st * 0.8;
            if (uClouds > 0.0) {
              // a moon where the night key light comes from
              vec3 sd = normalize(uSunDir);
              float night = 1.0 - smoothstep(0.1, 0.45, uDawn);
              float m = max(dot(vDir, sd), 0.0);
              #ifdef CG_EXPLORE_NIGHT
              // blue hour (dusk): deep indigo overhead, a last warm band low on the far side
              float blue = smoothstep(0.08, 0.27, uDawn) * (1.0 - smoothstep(0.3, 0.5, uDawn));
              vec3 indigo = mix(vec3(0.05, 0.06, 0.13), vec3(0.008, 0.02, 0.07), pow(max(y, 0.0), 0.45));
              c = mix(c, indigo, blue * 0.85);
              float away = 0.4 + 0.6 * max(dot(normalize(vDir.xz + 1e-4), -normalize(sd.xz)), 0.0);
              c += vec3(0.34, 0.13, 0.06) * pow(1.0 - max(y, 0.0), 7.0) * blue * away;
              // dawn: a rose band under the gold
              float rose = smoothstep(0.36, 0.5, uDawn) * (1.0 - smoothstep(0.54, 0.74, uDawn));
              c += vec3(0.3, 0.12, 0.15) * pow(1.0 - max(y, 0.0), 4.0) * rose;
              // more stars at night and dusk, twinkling, a few warm or blue
              vec3 q2 = floor(vDir * 760.0);
              float h2s = hash(q2 + 3.1);
              float st2 = step(0.9982, h2s) * (1.0 - smoothstep(0.24, 0.42, uDawn)) * smoothstep(0.02, 0.3, y);
              float tw = 0.6 + 0.4 * sin(uTime * (1.3 + h2s * 40.0) + h2s * 300.0);
              vec3 sc = mix(vec3(0.75, 0.85, 1.0), vec3(1.0, 0.85, 0.65), step(0.9993, h2s));
              c += sc * st2 * tw * 1.6;
              c += vec3(0.7, 0.85, 0.9) * st * 0.6 * night;
              #ifdef CG_EXPLORE_NIGHT
              {
                // shooting stars, on clear nights only (not under a storm, snow or fog)
                float clearK = ( 1.0 - smoothstep( 0.0, 0.3, uStorm ) ) * ( 1.0 - smoothstep( 0.0, 0.3, uSnow ) ) * ( 1.0 - smoothstep( 0.0, 0.3, uFog ) );
                float nm = night * smoothstep( 0.04, 0.3, y ) * clearK;
                if ( nm > 0.01 ) c += ( cgMeteor( vDir, uTime, 19.0, 0.13 ) + cgMeteor( vDir, uTime, 27.0, 0.55 ) + cgMeteor( vDir, uTime, 37.0, 0.81 ) ) * nm;
              }
              #endif
              float disc = smoothstep(0.99955, 0.99975, m);
              float mare = 0.82 + 0.18 * n2(vDir.xy * 900.0);
              c += vec3(0.85, 0.92, 0.95) * (disc * 3.6 * mare + pow(m, 120.0) * 0.2 + pow(m, 14.0) * 0.05) * max(night, blue * 0.7);
              #else
              float disc = smoothstep(0.99955, 0.99975, m);
              float mare = 0.82 + 0.18 * n2(vDir.xy * 900.0);
              c += vec3(0.85, 0.92, 0.95) * (disc * 2.2 * mare + pow(m, 120.0) * 0.12 + pow(m, 12.0) * 0.03) * night;
              #endif
              // flattened cloud deck drifting slowly; lit gold by day, moon-rimmed by night
              float yy = max(vDir.y, 0.0);
              vec2 uv = vDir.xz / (yy + 0.08) * 0.9 + vec2(uTime * 0.004, uTime * 0.0015);
              float cl = smoothstep(0.48, 0.78, fbm(uv * 1.3));
              float wisp = smoothstep(0.55, 0.85, fbm(uv * 3.1 + 5.0)) * 0.5;
              float k = clamp(cl + wisp, 0.0, 1.0) * smoothstep(0.0, 0.12, yy) * uClouds;
              float sunSide = pow(max(dot(vDir, sd), 0.0), 3.0);
              vec3 dayCl = mix(vec3(1.0, 0.86, 0.66), vec3(1.7, 1.15, 0.6), sunSide) * mix(0.55, 1.0, uDawn);
              vec3 nightCl = vec3(0.05, 0.09, 0.11) + vec3(0.25, 0.3, 0.32) * pow(m, 8.0);
              vec3 cc = mix(nightCl, dayCl, smoothstep(0.15, 0.7, uDawn));
              c = mix(c, cc * (0.75 + 0.25 * fbm(uv * 6.0)), k * 0.85);
            }
            #ifdef CG_EXPLORE_NIGHT
            // a storm: the sky closes over, heavy and grey, darker low down; the lightning lights it from within
            if (uStorm > 0.002 || uSnow > 0.002) {
              vec2 suv = vDir.xz / (max(vDir.y, 0.0) + 0.14) * 0.7 + vec2(uTime * 0.012, uTime * 0.005);
              float deck = 0.5 + 0.5 * fbm(suv * 1.7);
              vec3 stormCol = mix(vec3(0.05, 0.062, 0.07), vec3(0.3, 0.33, 0.36), uDawn) * deck * (1.0 - 0.45 * pow(1.0 - max(y, 0.0), 3.0));
              c = mix(c, stormCol, smoothstep(0.0, 0.55, uStorm) * 0.94);
              c += vec3(0.66, 0.78, 1.0) * uFlash * (0.3 + 0.7 * fbm(suv * 3.2 + 4.0)) * 1.5;
              // snow cloud: low, even and pale (lighter than a storm's, a little warmer toward the horizon, its own soft mottle), lit from above by day
              vec3 snowCol = mix(vec3(0.045, 0.06, 0.08), vec3(0.74, 0.77, 0.82), uDawn) * ( 0.82 + 0.3 * deck ) * ( 1.0 + 0.18 * pow( 1.0 - max( y, 0.0 ), 2.0 ) );
              c = mix(c, snowCol, smoothstep(0.0, 0.6, uSnow) * 0.93);
            }
            // fog: the whole sky is the fog, one pale brightness, a little brighter and warmer toward the horizon and round the sun (which is a
            // soft glow in it, no disc), tinted by the hour; the stars and the moon go
            if (uFog > 0.002) {
              vec3 fs = normalize( uSunDir );
              float sunN = pow( max( dot( vDir, fs ), 0.0 ), 5.0 );
              vec3 fogDay = mix( vec3( 0.62, 0.66, 0.68 ), vec3( 0.92, 0.82, 0.62 ), smoothstep( 0.5, 1.0, uDawn ) * 0.5 + 0.25 * smoothstep( 0.36, 0.5, uDawn ) );
              vec3 fogCol = mix( vec3( 0.03, 0.055, 0.07 ), fogDay, smoothstep( 0.05, 0.6, uDawn ) ) * ( 0.88 + 0.22 * pow( 1.0 - max( y, 0.0 ), 2.0 ) );
              fogCol += vec3( 1.0, 0.82, 0.55 ) * sunN * 0.65 * smoothstep( 0.2, 0.7, uDawn ) + vec3( 0.12, 0.2, 0.26 ) * sunN * ( 1.0 - smoothstep( 0.1, 0.5, uDawn ) ) * 0.4;
              c = mix( c, fogCol, smoothstep( 0.0, 0.45, uFog ) * 0.97 );
            }
            // a rainbow, once the storm has cleared: a primary bow 42 degrees round the point opposite the sun (violet inside, red
            // outside), a faint secondary at 51 (reversed), the sky brighter inside the first and darker between them (Alexander's band)
            if (uBow > 0.002) {
              vec3 sdn = normalize(uSunDir);
              float elev = degrees(asin(clamp(sdn.y, -1.0, 1.0)));
              float vis = uBow * smoothstep(0.32, 0.46, uDawn) * smoothstep(-1.0, 4.0, elev) * (1.0 - smoothstep(30.0, 46.0, elev)) * (1.0 - smoothstep(0.2, 0.6, uStorm)) * (1.0 - smoothstep(0.1, 0.4, uSnow)) * (1.0 - smoothstep(0.1, 0.4, uFog));
              if (vis > 0.002) {
                float ang = degrees(acos(clamp(dot(vDir, -sdn), -1.0, 1.0)));
                float az = atan(vDir.x, vDir.z);
                float tp = (ang - 39.7) / 3.0;
                float prim = smoothstep(0.0, 0.14, tp) * (1.0 - smoothstep(0.86, 1.0, tp));
                float ts = 1.0 - (ang - 49.6) / 4.6;
                float sec = smoothstep(0.0, 0.16, ts) * (1.0 - smoothstep(0.84, 1.0, ts));
                float inner = 1.0 - smoothstep(36.0, 41.0, ang);
                float dark = smoothstep(43.0, 45.5, ang) * (1.0 - smoothstep(48.5, 50.0, ang));
                // the shower itself: a dark rain cloud behind the bow (which is what makes a bow stand out), thinning toward the sun
                float shower = (1.0 - smoothstep(46.0, 66.0, ang)) * (0.55 + 0.45 * fbm(vec2(az * 3.0 + uTime * 0.01, vDir.y * 6.0)));
                // (rain curtains are patchy: the bow is brighter in places, and thins toward the ground)
                float curtain = 0.72 + 0.28 * n2(vec2(az * 5.0, uTime * 0.03));
                float low = smoothstep(-0.03, 0.09, vDir.y);
                c *= 1.0 - (0.2 * dark + 0.38 * shower) * vis * low;
                c += vec3(0.1, 0.1, 0.11) * inner * vis * low;
                c += (cgSpectrum(clamp(tp, 0.0, 1.0)) * prim * 1.15 + cgSpectrum(clamp(ts, 0.0, 1.0)) * sec * 0.3) * vis * curtain * low;
              }
            }
            #endif
            gl_FragColor = vec4(c, 1.0);
          }`,
      })
    );
    this.mesh.frustumCulled = false;
    this.mesh.renderOrder = -10;
    // the interactive modes' sky (dusk, dawn, twinkling stars, a brighter
    // moon): the same shader with a define, swapped in while exploring, so the
    // film's sky program is unchanged
    const fm = this.mesh.material;
    this.exploreMaterial = new THREE.ShaderMaterial({ side: fm.side, depthWrite: false, fog: false, uniforms: this.uniforms, vertexShader: fm.vertexShader, fragmentShader: fm.fragmentShader, defines: { CG_EXPLORE_NIGHT: '' } });
  }
  update(t, ctx) {
    this.uniforms.uDawn.value = ctx.dawn;
    this.uniforms.uClouds.value = ctx.explore ? 1 : 0;
    this.uniforms.uTime.value = t;
  }
}
