import * as THREE from 'three';
import { RNG } from '../core/rng.js';
import { sseg, clamp } from '../core/ease.js';
import { SUN_DIR } from '../world/atmosphere.js';
import { OUT, POND } from './scenery.js';
import { WATER_Y } from './pond.js';

// Dragonflies over the pool (interactive modes, by day).
//
// A dragonfly hangs in the air, wings a blur, then dashes to somewhere else and hangs again; now and then it drops to the water and
// touches it (a ring, a small sound) before it goes. Each is a leg at a time: a place it is leaving, a place it is going to, how far
// through it is. The path is worked out here (a few vectors a frame); the pose, the four wings' beat (a pair against a pair) and
// the shading are worked out in the shader from the position and heading handed to it. They are blue emperors and red darters,
// glint in the sun, thin into the haze, and are reflected in the pool with the rest of the outdoors.

const TAU = Math.PI * 2;
const V = (x = 0, y = 0, z = 0) => new THREE.Vector3(x, y, z);

// a dragonfly of length 1: z forward, wings out along x
function bodyGeometry() {
  const P = [];
  const tri = (a, b, c) => P.push(...a, ...b, ...c);
  const sections = [[0.5, 0.0], [0.47, 0.03], [0.42, 0.04], [0.34, 0.048], [0.26, 0.05], [0.2, 0.034], [0.1, 0.02], [-0.05, 0.016], [-0.2, 0.015], [-0.35, 0.014], [-0.5, 0.01]];
  const ring = (z, r) => [[-r, 0, z], [0, r, z], [r, 0, z], [0, -r * 0.9, z]];
  for (let i = 0; i < sections.length - 1; i++) {
    const A = ring(...sections[i]), B = ring(...sections[i + 1]);
    for (let k = 0; k < 4; k++) { const k2 = (k + 1) % 4; tri(A[k], A[k2], B[k]); tri(A[k2], B[k2], B[k]); }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(P, 3));
  g.computeVertexNormals();
  return g;
}
function wingGeometry() {
  const P = [], W = [];
  const quad = (a, b, c, d, w) => { P.push(...a, ...b, ...c, ...a, ...c, ...d); W.push(w, w, w, w, w, w); };
  for (const s of [-1, 1]) {
    // forewing (aW = 1) and hindwing (aW = 2): root at the thorax, tip out and slightly back, the hindwing broader
    quad([s * 0.03, 0.04, 0.42], [s * 0.03, 0.04, 0.25], [s * 0.57, 0.05, 0.16], [s * 0.55, 0.05, 0.36], 1);
    quad([s * 0.03, 0.035, 0.30], [s * 0.03, 0.035, 0.09], [s * 0.55, 0.04, -0.04], [s * 0.52, 0.04, 0.17], 2);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(P, 3));
  g.setAttribute('aW', new THREE.Float32BufferAttribute(W, 1));
  g.computeVertexNormals();
  return g;
}

const COMMON_VERT = /* glsl */ `
  attribute vec4 aPos; // x, y, z, seed
  attribute vec4 aDir; // heading (unit), how hard it is flying (0 hovering … 1 dashing)
  attribute vec4 aCol; // colour, length in world units
  uniform float uT, uVis;
  varying vec3 vN; varying vec3 vWorld; varying vec3 vCol; varying float vLocalZ;
  const float TAU = 6.2831853;
  vec3 cgPose( vec3 p, out vec3 right, out vec3 up, out vec3 fwd ) {
    fwd = normalize( aDir.xyz );
    right = normalize( cross( vec3( 0.0, 1.0, 0.0 ), fwd ) + vec3( 1e-5, 0.0, 0.0 ) );
    up = cross( fwd, right );
    return p;
  }
`;
const BODY_VERT = /* glsl */ `${COMMON_VERT}
  void main() {
    vec3 right, up, fwd;
    cgPose( position, right, up, fwd );
    float size = aCol.w * uVis;
    vec3 world = aPos.xyz + ( right * position.x + up * position.y + fwd * position.z ) * size;
    vWorld = world; vCol = aCol.rgb; vLocalZ = position.z;
    vN = right * normal.x + up * normal.y + fwd * normal.z;
    gl_Position = projectionMatrix * viewMatrix * vec4( world, 1.0 );
  }
`;
const WING_VERT = /* glsl */ `${COMMON_VERT}
  attribute float aW;
  void main() {
    vec3 right, up, fwd;
    cgPose( position, right, up, fwd );
    // the pairs beat against each other; hovering is a blur, a dash a steadier beat
    float rate = mix( 42.0, 34.0, aDir.w );
    float ph = uT * rate + aPos.w * TAU + ( aW > 1.5 ? 3.14159 : 0.0 );
    vec3 p = position;
    float arm = abs( p.x ) - 0.03;
    float ang = sin( ph ) * 0.55 + 0.1;
    p.y += ang * arm * ( 0.9 + 0.3 * aW );
    p.z -= abs( sin( ph ) ) * arm * 0.06;
    float size = aCol.w * uVis;
    vec3 world = aPos.xyz + ( right * p.x + up * p.y + fwd * p.z ) * size;
    vWorld = world; vCol = aCol.rgb; vLocalZ = position.z;
    vN = up;
    gl_Position = projectionMatrix * viewMatrix * vec4( world, 1.0 );
  }
`;
const HEAD = /* glsl */ `
  uniform vec3 uHaze, uSun, uSunCol; uniform float uHazeDensity, uSunK, uNight;
  varying vec3 vN; varying vec3 vWorld; varying vec3 vCol; varying float vLocalZ;
`;
const BODY_FRAG = /* glsl */ `${HEAD}
  void main() {
    vec3 V = normalize( cameraPosition - vWorld );
    vec3 N = normalize( vN ); if ( dot( N, V ) < 0.0 ) N = -N;
    vec3 toSun = -uSun;
    // thorax dark and metallic, abdomen the colour of the fly; a glint where the sun is on it
    vec3 base = mix( vCol * 0.35 + vec3( 0.02, 0.05, 0.03 ), vCol, smoothstep( 0.3, 0.12, vLocalZ ) );
    base = mix( base, vec3( 0.04, 0.05, 0.05 ), smoothstep( 0.42, 0.5, vLocalZ ) ); // eyes
    float lit = max( dot( N, toSun ), 0.0 );
    vec3 col = base * ( 0.35 + 0.65 * N.y * 0.5 + 0.5 ) * 0.7 + base * uSunCol * uSunK * lit * 0.9;
    col += uSunCol * uSunK * pow( max( dot( reflect( -toSun, N ), V ), 0.0 ), 24.0 ) * 0.7;
    col *= 1.0 - 0.6 * uNight;
    float d = length( cameraPosition - vWorld );
    col = mix( col, uHaze, 1.0 - exp( -uHazeDensity * uHazeDensity * d * d ) );
    gl_FragColor = vec4( col, 1.0 );
  }
`;
const WING_FRAG = /* glsl */ `${HEAD}
  void main() {
    vec3 V = normalize( cameraPosition - vWorld );
    vec3 N = normalize( vN ); if ( dot( N, V ) < 0.0 ) N = -N;
    vec3 toSun = -uSun;
    // a thin film: faintly tinted, clearer face on, brighter and glinting at a slant and against the sun
    float edge = pow( 1.0 - abs( dot( N, V ) ), 2.0 );
    float back = pow( max( dot( -V, toSun ), 0.0 ), 4.0 );
    float vein = 0.7 + 0.3 * sin( vLocalZ * 90.0 );
    vec3 col = vec3( 0.55, 0.7, 0.8 ) * ( 0.25 + 0.55 * uSunK ) + uSunCol * uSunK * ( 0.5 * edge + 1.0 * back );
    col *= 1.0 - 0.6 * uNight;
    float a = ( 0.2 + 0.22 * edge + 0.25 * back ) * vein;
    float d = length( cameraPosition - vWorld );
    col = mix( col, uHaze, 1.0 - exp( -uHazeDensity * uHazeDensity * d * d ) );
    gl_FragColor = vec4( col, clamp( a, 0.0, 0.7 ) );
  }
`;

export class Dragonflies {
  constructor({ scenery, quality }) {
    this.group = new THREE.Group();
    this.group.name = 'dragonflies';
    this.rng = new RNG('dragonflies');
    this.n = quality?.tier === 'low' ? 2 : 4;
    const n = this.n, r = this.rng;
    const mk = (geo) => {
      const g = new THREE.InstancedBufferGeometry();
      g.setAttribute('position', geo.attributes.position);
      g.setAttribute('normal', geo.attributes.normal);
      if (geo.attributes.aW) g.setAttribute('aW', geo.attributes.aW);
      g.instanceCount = n;
      return g;
    };
    const bg = mk(bodyGeometry()), wg = mk(wingGeometry());
    this.aPos = new THREE.InstancedBufferAttribute(new Float32Array(n * 4), 4);
    this.aDir = new THREE.InstancedBufferAttribute(new Float32Array(n * 4), 4);
    this.aCol = new THREE.InstancedBufferAttribute(new Float32Array(n * 4), 4);
    for (const g of [bg, wg]) { g.setAttribute('aPos', this.aPos); g.setAttribute('aDir', this.aDir); g.setAttribute('aCol', this.aCol); }
    this.uni = {
      uT: { value: 0 }, uVis: { value: 0 }, uHaze: scenery.haze.uHaze, uHazeDensity: scenery.haze.uHazeDensity, uSun: { value: SUN_DIR },
      uSunCol: { value: new THREE.Color(1.0, 0.8, 0.5) }, uSunK: OUT.uSunK, uNight: OUT.uNight,
    };
    const body = new THREE.Mesh(bg, new THREE.ShaderMaterial({ uniforms: this.uni, vertexShader: BODY_VERT, fragmentShader: BODY_FRAG, side: THREE.DoubleSide, fog: false }));
    const wings = new THREE.Mesh(wg, new THREE.ShaderMaterial({ uniforms: this.uni, vertexShader: WING_VERT, fragmentShader: WING_FRAG, side: THREE.DoubleSide, transparent: true, depthWrite: false, fog: false }));
    wings.renderOrder = 2;
    // (their paths are on the CPU and their poses in the shader, so the geometry's own bounds mean nothing: they range over the pool and a little
    // beyond, up to a few dozen units high; culled with that, not drawn when the pool is behind the camera)
    const range = new THREE.Sphere(V(POND.x, WATER_Y + 30, POND.z), Math.max(POND.rx, POND.rz) * 1.5);
    bg.boundingSphere = range; wg.boundingSphere = range;
    for (const m of [body, wings]) { m.visible = false; m.layers.enable(1); this.group.add(m); }
    this.meshes = [body, wings];
    // the flies: two blue emperors and two red darters (more on the better tiers' count of four, fewer on low)
    this.flies = Array.from({ length: n }, (_, i) => ({
      p0: V(POND.x + r.range(-80, 80), WATER_Y + r.range(14, 40), POND.z + r.range(-200, 200)), p1: V(), t0: -99, T: 1, dip: false, dipped: false,
      pos: V(), fwd: V(0, 0, 1), seed: r.float(), len: r.range(15, 19), blue: i % 2 === 0, hover: V(), flying: 0,
    }));
    this.flies.forEach((f, i) => {
      f.pos.copy(f.p0);
      const c = f.blue ? [0.1, 0.38, 0.95] : [0.85, 0.1, 0.05];
      this.aCol.array.set([...c, f.len], i * 4);
    });
    this.onDip = null; // (x, z): one touched the water
    this.vis = 0;
    this._d = V();
  }

  _leg(f, clock) {
    const r = this.rng;
    f.p0.copy(f.pos);
    f.t0 = clock;
    f.T = r.range(2.2, 4.8);
    f.dip = r.chance(0.3);
    f.dipped = false;
    // somewhere over or beside the pool, favouring its margin (where reeds and insects are)
    const a = r.range(0, TAU), k = r.chance(0.7) ? r.range(0.7, 1.15) : r.range(0.1, 0.7);
    f.p1.set(POND.x + Math.cos(a) * POND.rx * k, f.dip ? WATER_Y + 4 : WATER_Y + r.range(10, 46), POND.z + Math.sin(a) * POND.rz * k);
    if (f.dip) { f.p1.x = POND.x + Math.cos(a) * POND.rx * Math.min(k, 0.9); f.p1.z = POND.z + Math.sin(a) * POND.rz * Math.min(k, 0.9); }
  }

  // clock: the explore clock; d: the hour; rain 0..1; bee: { pos } (they keep clear of APX-9)
  update(clock, dt, d, rain, bee, pondRing) {
    const v = sseg(d, 0.5, 0.62) * (1 - sseg(rain, 0.1, 0.4));
    this.vis = v;
    this.uni.uVis.value = v;
    this.uni.uT.value = clock;
    for (const m of this.meshes) m.visible = v > 0.02;
    if (v < 0.02) return;
    for (let i = 0; i < this.flies.length; i++) {
      const f = this.flies[i];
      if (clock - f.t0 >= f.T) this._leg(f, clock);
      const u = (clock - f.t0) / f.T;
      // hang about, then dash (the last third of the leg, eased)
      const move = (() => { const q = clamp((u - 0.68) / 0.3); return q * q * (3 - 2 * q); })();
      f.hover.set(Math.sin(clock * 1.7 + f.seed * 40) * 1.6, Math.sin(clock * 2.3 + f.seed * 17) * 1.1, Math.cos(clock * 1.3 + f.seed * 29) * 1.6);
      const hoverK = 1 - move;
      f.pos.copy(f.p0).lerp(f.p1, move).addScaledVector(f.hover, hoverK * 0.9 + 0.2);
      // keep clear of the bee
      if (bee && bee.pos) {
        const dx = f.pos.x - bee.pos.x, dy = f.pos.y - bee.pos.y, dz = f.pos.z - bee.pos.z, dd = Math.hypot(dx, dy, dz);
        if (dd < 70 && dd > 0.01) f.pos.addScaledVector(this._d.set(dx, dy, dz).multiplyScalar(1 / dd), (70 - dd) * 0.6);
      }
      // heading: toward where it is going; nose a little up when hanging
      const dir = this._d.copy(f.p1).sub(f.p0);
      const dist = Math.hypot(dir.x, dir.z) || 1;
      f.flying = move > 0 && move < 1 ? 1 : 0;
      const pitch = f.dip ? 0 : 0.28 * hoverK - 0.05;
      f.fwd.set(dir.x / dist * Math.cos(pitch), Math.sin(pitch) + (move > 0 && move < 1 ? (f.p1.y - f.p0.y) / (dist + 1) * 0.6 : 0), dir.z / dist * Math.cos(pitch)).normalize();
      // touching down: a ring and a sound as it reaches the water
      if (f.dip && !f.dipped && u > 0.94) {
        f.dipped = true;
        pondRing?.('misc', f.p1.x, f.p1.z, clock, 0.35);
        this.onDip?.(f.p1.x, f.p1.z);
      }
      this.aPos.array.set([f.pos.x, f.pos.y, f.pos.z, f.seed], i * 4);
      this.aDir.array.set([f.fwd.x, f.fwd.y, f.fwd.z, f.flying], i * 4);
    }
    this.aPos.needsUpdate = true;
    this.aDir.needsUpdate = true;
  }
}
