import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { RNG } from '../core/rng.js';
import { clamp, smooth } from '../core/ease.js';
import { WEATHER } from '../world/weatherU.js';
import { ripplesGLSL, makeFX } from './fountain.js';
import { POND, inPond } from './scenery.js';
import { WIND } from '../world/wind.js';

// The reflecting pool on the west lawn (interactive modes): a raised oval of still water in a stone coping,
// seen through the glasshouse's west wall.
//
//  · The water reflects what is really there. A second, small render of the outdoors (the land's trees, walls,
//    hills and the sky, nothing of the glasshouse) from the camera mirrored in the water's plane, clipped to what
//    stands above the water, is read back in the water's shader through a Fresnel term and bent by its ripples; so the
//    far bank's trees stand upside down in it, with the clouds and the evening sky. The pass is skipped when the pool
//    is out of view, small (a third of the screen's width) and absent on `low` (the sky's own reflection stands in).
//  · The surface is the fountain's: a slow swell, rings from drops (a downpour's when it rains), wake rings where the
//    ducks go (a ring buffer of the last two dozen).
//  · Water lilies on their pads, reeds swaying in the breeze at the margin, and a few mallards that drift about,
//    now and then tip up to dabble.
//  · Koi swim under the surface (drawn in the water's own shader, seen where the water is not mirroring: bent by the
//    ripples and displaced as the water refracts the line of sight), and now and then one rises with a ring.
//  · The koi are shy: APX-9 skimming low over them sends them darting away (a ring, a splash), and they drift back to their loops.
//  · Autumn leaves from the trees come down on the water and drift across it on the breeze, upwind to downwind, a couple of dozen at a time.
//  · APX-9 flying low over the water leaves a wake, as it does over the fountain; a dragonfly dipping, or a koi rising,
//    leaves a ring too (the ring buffer is shared out: ducks, the bee, and these).

const V = (x = 0, y = 0, z = 0) => new THREE.Vector3(x, y, z);
const TAU = Math.PI * 2;
const EMN = 40; // wake rings in the buffer: the ducks' (0-23), the bee's (24-35), the rest (36-39)
export const WATER_Y = 4;
const COPE_TOP = 7, BASE_Y = -3;

// the pool's outline: an oval with a few soft lobes; `grow` widens it (coping, margins)
function outline(grow = 0, n = 120) {
  const pts = [];
  for (let i = 0; i < n; i++) {
    const a = (i / n) * TAU;
    const k = 1 + 0.06 * Math.sin(3 * a + 0.6) + 0.045 * Math.sin(5 * a + 2.1) + 0.03 * Math.sin(8 * a + 4.0);
    pts.push([POND.x + (POND.rx * k + grow) * Math.cos(a), POND.z + (POND.rz * k + grow) * Math.sin(a)]);
  }
  return pts;
}
const toShape = (pts) => new THREE.Shape(pts.map(([x, z]) => new THREE.Vector2(x, -z))); // (flat XY, turned to lie on XZ: world z = −shape y)

export class Pond {
  constructor({ scenery, outside, world, scene, quality }) {
    this.scenery = scenery;
    this.low = quality.tier === 'low';
    this.group = new THREE.Group();
    this.group.name = 'pond';
    this.rng = new RNG('pond');
    this.fx = makeFX(EMN);
    this.fx.uFC.value.set(POND.x, POND.z);
    this.emit = 0;
    this.cursor = { bee: 24, misc: 36 };
    this.lastBee = 0;
    this.on = true;
    this.onRise = null; // (x, z): a koi rose to the surface
    this.onStartle = null; // (x, z): a koi bolted from the bee
    this.inView = true; this._leafDt = 0;
    this.onDabble = null; // (x, z, size): a duck tipped up or came back up (the sound listens)
    const ext = (p, k, o) => scenery.ext(p, k, o);

    // the mirror: a small target, a virtual camera, and the layer the outdoors are drawn on (1)
    this.scale = quality.tier === 'high' ? 0.4 : 0.3;
    this.rt = new THREE.WebGLRenderTarget(8, 8, { type: THREE.HalfFloatType, depthBuffer: true });
    this.rt.texture.generateMipmaps = false;
    this.mirror = { tMirror: { value: this.rt.texture }, uMirrorMat: { value: new THREE.Matrix4() }, uMirrorOn: { value: 0 }, uMirrorTexel: { value: new THREE.Vector2(0.002, 0.002) } };
    this.cam = new THREE.PerspectiveCamera();
    this.cam.layers.set(1);
    this._pl = new THREE.Plane(); this._clip = new THREE.Vector4(); this._q4 = new THREE.Vector4(); // (the oblique near plane)
    this._hide = null; this._frames = 0; // (what the mirror pass leaves out, built on the first pass)
    for (const root of [scenery.extGroup, outside.group, world.sky.mesh]) root.traverse((o) => o.layers.enable(1));
    scene.traverse((o) => { if (o.isLight) o.layers.enable(1); }); // (the mirror pass lights the land as the main pass does)
    this.sphere = new THREE.Sphere(V(POND.x, WATER_Y, POND.z), Math.max(POND.rx, POND.rz) + 40);
    this._v = V(); this._t = V(); this._la = V(); this._r = new THREE.Matrix4();

    // the coping: two courses of stone round the water
    const cope = (outerGrow, innerGrow, h, y0) => {
      const sh = toShape(outline(outerGrow));
      sh.holes.push(new THREE.Path(outline(innerGrow).map(([x, z]) => new THREE.Vector2(x, -z))));
      const geo = new THREE.ExtrudeGeometry(sh, { depth: h, bevelEnabled: false, curveSegments: 1 });
      geo.rotateX(-Math.PI / 2);
      geo.translate(0, y0, 0);
      return geo;
    };
    const stone = ext({ color: '#d4cbb6' });
    this.group.add(new THREE.Mesh(cope(44, 20, 4.5, BASE_Y), stone), new THREE.Mesh(cope(20, 0, COPE_TOP - BASE_Y, BASE_Y), stone));
    // the water
    const wg = new THREE.ShapeGeometry(toShape(outline(1.5)), 1);
    wg.rotateX(-Math.PI / 2);
    this._koi(quality);
    this._leaves(ext, quality);
    this.waterMat = this._waterMaterial();
    this.water = new THREE.Mesh(wg, this.waterMat);
    this.water.position.y = WATER_Y;
    this.water.renderOrder = 0;
    this.group.add(this.water);
    this._lilies(ext);
    this._reeds(ext);
    this._ducks(ext);
    this._mist(quality);
    // what stands at the water's edge is reflected in it: the coping, the reeds, the ducks (not the water itself, not the pads)
    for (const o of [...this.group.children]) if (o !== this.water && !o.userData.pads) o.traverse((c) => c.layers.enable(1));
  }

  _waterMaterial() {
    const fx = this.fx, mirror = this.mirror;
    const haze = this.scenery.haze;
    const m = new THREE.MeshPhysicalMaterial({ color: '#142119', roughness: 0.04, metalness: 0, clearcoat: 0, envMapIntensity: 1.3, specularIntensity: 1 });
    m.userData.noWind = true;
    m.userData.noLightField = true; // outside the glass
    const K = this.fish.length, fishU = { uFish: this.uFish, uFishC: this.uFishC, uFishVis: this.uFishVis, uIce: WEATHER.uCover };
    m.onBeforeCompile = (sh) => {
      Object.assign(sh.uniforms, fx, mirror, haze, fishU, { uRain: WEATHER.uRain });
      sh.fragmentShader = sh.fragmentShader
        .replace('#include <common>', `#include <common>
          uniform sampler2D tMirror; uniform mat4 uMirrorMat; uniform float uMirrorOn; uniform vec2 uMirrorTexel;
          uniform vec3 uHaze; uniform float uHazeDensity;
          uniform vec4 uFish[ ${K} ]; uniform vec4 uFishC[ ${K} ]; uniform float uFishVis, uIce;
          ${ripplesGLSL(EMN, 15, 0.03)}
          float cgpN( vec2 p ) { vec2 i = floor( p ), u = fract( p ); u = u * u * ( 3.0 - 2.0 * u ); return mix( mix( cgfH( i ), cgfH( i + vec2( 1.0, 0.0 ) ), u.x ), mix( cgfH( i + vec2( 0.0, 1.0 ) ), cgfH( i + vec2( 1.0 ) ), u.x ), u.y ); }`)
        .replace('#include <color_fragment>', `#include <color_fragment>
          vec3 cgpW = ( ( vec4( -vViewPosition, 1.0 ) - viewMatrix[ 3 ] ) * viewMatrix ).xyz;
          vec3 cgpR = cgfWater( cgpW.xz, uFT );
          {
            // koi under the surface: where the line of sight goes down into the water it bends (toward the vertical), so the fish
            // seen at a point lie a little farther along it; the ripples bend it too
            vec3 cgpV = cameraPosition - cgpW;
            float cgpSin = clamp( length( cgpV.xz ) / max( length( cgpV ), 1e-3 ), 0.0, 0.97 );
            float cgpTan = cgpSin / sqrt( 1.7689 - cgpSin * cgpSin );
            vec2 cgpFp = cgpW.xz - normalize( cgpV.xz + vec2( 1e-4 ) ) * 4.5 * cgpTan + cgpR.yz * 2.2;
            vec3 cgpAcc = vec3( 0.0 ); float cgpCov = 0.0;
            for ( int i = 0; i < ${K}; i ++ ) {
              vec4 f = uFish[ i ];
              vec2 d = cgpFp - f.xy;
              if ( dot( d, d ) > f.w * f.w * 1.2 ) continue;
              float c = cos( f.z ), s = sin( f.z );
              vec2 q = vec2( d.x * c + d.y * s, -d.x * s + d.y * c ) / f.w; // x along the fish, head at +x
              q.y -= sin( uFT * 5.5 + f.x * 0.2 ) * 0.1 * smoothstep( 0.15, -0.55, q.x ) * ( 0.5 - q.x );
              float wBody = 0.14 * pow( max( 1.0 - pow( abs( q.x - 0.04 ) / 0.56, 2.0 ), 0.0 ), 0.55 );
              float body = ( 1.0 - smoothstep( wBody * 0.55, wBody * 1.15, abs( q.y ) ) ) * smoothstep( -0.58, -0.5, q.x ) * ( 1.0 - smoothstep( 0.5, 0.58, q.x ) );
              float tx = ( -0.5 - q.x ) / 0.32;
              float wTail = 0.035 + 0.17 * tx;
              float tail = step( 0.0, tx ) * ( 1.0 - smoothstep( 0.85, 1.0, tx ) ) * ( 1.0 - smoothstep( wTail * 0.6, wTail * 1.1, abs( q.y ) ) ) * 0.75;
              float fin = ( 1.0 - smoothstep( 0.02, 0.07, abs( abs( q.y ) - 0.17 ) ) ) * ( 1.0 - smoothstep( 0.05, 0.12, abs( q.x - 0.18 ) ) ) * 0.6; // pectoral fins
              float m = clamp( max( max( body, tail ), fin ), 0.0, 1.0 );
              if ( m <= 0.001 ) continue;
              vec4 pc = uFishC[ i ];
              float n1 = cgpN( q * vec2( 2.4, 5.0 ) + pc.y ), n2 = cgpN( q * vec2( 5.0, 9.0 ) + pc.y * 3.1 + 7.0 );
              vec3 orange = vec3( 0.95, 0.36, 0.05 ), white = vec3( 0.93, 0.88, 0.8 ), gold = vec3( 0.95, 0.68, 0.1 ), black = vec3( 0.05, 0.045, 0.045 );
              vec3 col = orange;
              if ( pc.x < 0.5 ) col = mix( orange, vec3( 0.98, 0.55, 0.2 ), smoothstep( 0.3, -0.1, q.y ) * 0.5 );
              else if ( pc.x < 1.5 ) col = mix( white, orange, smoothstep( 0.45, 0.58, n1 ) );
              else if ( pc.x < 2.5 ) col = mix( gold, vec3( 1.0, 0.85, 0.4 ), smoothstep( 0.0, 0.3, q.x ) * 0.4 );
              else col = mix( mix( white, orange, smoothstep( 0.5, 0.6, n1 ) ), black, smoothstep( 0.68, 0.74, n2 ) * step( 0.0, q.x + 0.3 ) );
              col *= 0.62 * ( 1.0 - 0.35 * m * 0.0 ); // (the water takes some of the light)
              cgpAcc = mix( cgpAcc, col, m ); cgpCov = max( cgpCov, m );
            }
            diffuseColor.rgb = mix( diffuseColor.rgb, cgpAcc, cgpCov * uFishVis * ( 1.0 - uIce ) );
          }
          // frozen over: milky, bluish ice with snow lying on it in drifts
          if ( uIce > 0.003 ) {
            float cgpIn = cgpN( cgpW.xz * 0.04 ) * 0.6 + cgpN( cgpW.xz * 0.17 + 5.0 ) * 0.4;
            vec3 cgpIceC = mix( vec3( 0.42, 0.55, 0.64 ), vec3( 0.88, 0.92, 0.96 ), smoothstep( 0.35, 0.75, cgpIn + uIce * 0.2 ) );
            diffuseColor.rgb = mix( diffuseColor.rgb, cgpIceC, smoothstep( 0.0, 0.5, uIce ) * 0.95 );
          }`)
        .replace('#include <normal_fragment_maps>', `#include <normal_fragment_maps>
          {
            vec3 cgpN = normalize( vec3( -cgpR.y * 0.5 * ( 1.0 - 0.95 * uIce ), 1.0, -cgpR.z * 0.5 * ( 1.0 - 0.95 * uIce ) ) );
            normal = normalize( ( viewMatrix * vec4( cgpN, 0.0 ) ).xyz );
          }`)
        .replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
          if ( uMirrorOn > 0.5 ) {
            // what stands above the water, turned over: read where the mirrored camera sees this point, bent by the ripples
            vec4 cgpM = uMirrorMat * vec4( cgpW, 1.0 );
            vec2 cgpUv = cgpM.xy / cgpM.w + vec2( cgpR.y, cgpR.z ) * 0.005;
            // (four taps, a texel apart: the small target would otherwise show its pixels and the canopy's ragged edge)
            vec3 cgpRefl = ( texture2D( tMirror, clamp( cgpUv + uMirrorTexel * vec2( 0.7, 0.4 ), 0.002, 0.998 ) ).rgb + texture2D( tMirror, clamp( cgpUv + uMirrorTexel * vec2( -0.4, 0.7 ), 0.002, 0.998 ) ).rgb
              + texture2D( tMirror, clamp( cgpUv + uMirrorTexel * vec2( -0.7, -0.4 ), 0.002, 0.998 ) ).rgb + texture2D( tMirror, clamp( cgpUv + uMirrorTexel * vec2( 0.4, -0.7 ), 0.002, 0.998 ) ).rgb ) * 0.25;
            cgpRefl = min( cgpRefl, vec3( 8.0 ) );
            cgpRefl /= 1.0 + 0.22 * dot( cgpRefl, vec3( 0.333 ) ); // (the bright horizon does not blow the water out)
            float cgpNdv = saturate( dot( normal, normalize( vViewPosition ) ) );
            float cgpF = min( 0.02 + 0.98 * pow( 1.0 - cgpNdv, 5.0 ), 0.78 );
            totalEmissiveRadiance += cgpRefl * ( 0.03 + 0.97 * cgpF ) * 0.9 * ( 1.0 - 0.85 * uIce );
          } else {
            // no mirror pass (the low tier, or when the governor has dropped it): a sky laid on the water by hand, brighter toward the horizon,
            // blue by day, dark by night, stronger at a grazing angle. (The environment map alone left the pool a black hole at the low tier.)
            vec3 cgpEv = normalize( cameraPosition - cgpW );
            vec3 cgpEn = normalize( vec3( -cgpR.y * 0.5 * ( 1.0 - 0.95 * uIce ), 1.0, -cgpR.z * 0.5 * ( 1.0 - 0.95 * uIce ) ) );
            vec3 cgpEr = reflect( -cgpEv, cgpEn );
            vec3 cgpSky = mix( uHaze * 1.05, mix( vec3( 0.2, 0.26, 0.34 ), vec3( 0.46, 0.6, 0.84 ), uFSun ), smoothstep( 0.0, 0.55, max( cgpEr.y, 0.0 ) ) ) * ( 0.2 + 0.8 * uFSun );
            float cgpEf = min( 0.04 + 0.96 * pow( 1.0 - saturate( cgpEv.y ), 5.0 ), 0.8 );
            totalEmissiveRadiance += cgpSky * ( 0.05 + 0.95 * cgpEf ) * 0.85 * ( 1.0 - 0.85 * uIce );
          }`)
        .replace('#include <fog_fragment>', `#ifdef USE_FOG
          // the land's own aerial perspective (the interior's fog does not reach out here)
          float cgpHz = 1.0 - exp( -uHazeDensity * uHazeDensity * vFogDepth * vFogDepth );
          gl_FragColor.rgb = mix( gl_FragColor.rgb, uHaze, cgpHz );
        #endif`);
    };
    m.customProgramCacheKey = () => 'cg-pond-water-v4-sky' + K;
    return m;
  }

  // ---- lilies, reeds, ducks ----------------------------------------------------------------------
  _lilies(ext) {
    const r = this.rng;
    const pads = [];
    for (let i = 0; i < 90; i++) {
      const a = r.range(0, TAU), k = Math.sqrt(r.float()) * 0.8;
      pads.push([POND.x + Math.cos(a) * POND.rx * k, POND.z + Math.sin(a) * POND.rz * k, r.range(5, 11), r.range(0, TAU)]);
    }
    const padGeo = new THREE.CircleGeometry(1, 16, 0.3, TAU - 0.6);
    padGeo.rotateX(-Math.PI / 2);
    const pm = new THREE.InstancedMesh(padGeo, ext({ color: '#ffffff', side: THREE.DoubleSide }, 'pad'), pads.length);
    const col = new THREE.Color();
    pads.forEach(([x, z, s, a], i) => {
      pm.setMatrixAt(i, new THREE.Matrix4().compose(V(x, WATER_Y + 0.35, z), new THREE.Quaternion().setFromAxisAngle(V(0, 1, 0), a), V(s, 1, s)));
      pm.setColorAt(i, col.setHSL(r.range(0.24, 0.31), r.range(0.4, 0.6), r.range(0.22, 0.32)));
    });
    pm.computeBoundingSphere();
    pm.userData.pads = true;
    this.group.add(pm);
    // a flower on some: eight petals in a cup
    const petals = [];
    for (let k = 0; k < 8; k++) { const p = new THREE.ConeGeometry(0.7, 3.2, 4); p.translate(0, 1.6, 0); p.rotateZ(0.9); p.rotateY((k / 8) * TAU); petals.push(p.toNonIndexed()); }
    const fm = new THREE.InstancedMesh(mergeGeometries(petals), ext({ color: '#ffffff' }), 40);
    // (where a bee can settle: the flowers, and the pads that have none; the ice takes them away)
    this.lotusSpots = []; this.padSpots = pads.slice(40).map(([x, z, s]) => [x, z, s]);
    pads.slice(0, 40).forEach(([x, z, s], i) => {
      const fx = x + r.range(-1, 1), fz = z + r.range(-1, 1);
      this.lotusSpots.push([fx, fz, s]);
      fm.setMatrixAt(i, new THREE.Matrix4().compose(V(fx, WATER_Y + 0.5, fz), new THREE.Quaternion(), V(1, 1, 1).multiplyScalar(s * 0.28)));
      fm.setColorAt(i, col.setHSL(r.chance(0.5) ? 0.95 : 0.12, r.range(0.0, 0.5), r.range(0.82, 0.94)));
    });
    fm.computeBoundingSphere();
    fm.userData.pads = true;
    this.group.add(fm);
  }

  _reeds(ext) {
    const r = this.rng;
    // a clump: nine blades, each a tapering strip bending a little
    const blades = [];
    for (let k = 0; k < 9; k++) {
      const g = new THREE.PlaneGeometry(0.16, 1, 1, 4);
      g.translate(0, 0.5, 0);
      const p = g.attributes.position;
      const lean = r.range(-0.35, 0.35), dir = r.range(0, TAU);
      for (let i = 0; i < p.count; i++) {
        const y = p.getY(i);
        const w = p.getX(i) * (1 - y * 0.92);
        p.setXYZ(i, w + Math.cos(dir) * lean * y * y, y, Math.sin(dir) * lean * y * y);
      }
      g.rotateY(r.range(0, TAU));
      g.translate(r.range(-0.18, 0.18), 0, r.range(-0.18, 0.18));
      blades.push(g.toNonIndexed());
    }
    const clump = mergeGeometries(blades);
    const spots = [];
    const edge = outline(-9, 160);
    for (let i = 0; i < edge.length; i++) {
      // clustered: reeds along some stretches of the margin and not others
      if (Math.sin(i * 0.37) + Math.sin(i * 0.11 + 1.3) < 0.2) continue;
      if (r.chance(0.55)) spots.push([edge[i][0] + r.range(-4, 4), edge[i][1] + r.range(-4, 4), r.range(28, 62)]);
    }
    const rm = new THREE.InstancedMesh(clump, ext({ color: '#ffffff', side: THREE.DoubleSide }, 'reed', { sway: true }), spots.length);
    const col = new THREE.Color();
    spots.forEach(([x, z, h], i) => {
      rm.setMatrixAt(i, new THREE.Matrix4().compose(V(x, WATER_Y - 1, z), new THREE.Quaternion().setFromAxisAngle(V(0, 1, 0), r.range(0, TAU)), V(h * 0.55, h, h * 0.55)));
      rm.setColorAt(i, col.setHSL(r.range(0.16, 0.24), r.range(0.4, 0.55), r.range(0.26, 0.38)));
    });
    rm.computeBoundingSphere();
    this.group.add(rm);
  }

  _ducks(ext) {
    const r = this.rng;
    // a mallard: brown body, green head, yellow bill, white ring, dark tail
    const parts = [];
    const col = (geo, c) => { const k = new THREE.Color(c); const n = geo.attributes.position.count; geo.setAttribute('color', new THREE.BufferAttribute(Float32Array.from({ length: n * 3 }, (_, i) => [k.r, k.g, k.b][i % 3]), 3)); return geo; };
    const add = (geo, c, f) => { f?.(geo); parts.push(col(geo.index ? geo.toNonIndexed() : geo, c)); };
    add(new THREE.SphereGeometry(1, 14, 10), '#7d6248', (g) => { g.scale(3.4, 2.2, 6.2); g.translate(0, 1.4, 0); });
    add(new THREE.SphereGeometry(1, 12, 9), '#8c8a8c', (g) => { g.scale(2.7, 1.3, 4.0); g.translate(0, 0.8, -0.9); }); // a paler belly
    add(new THREE.SphereGeometry(1, 12, 10), '#1f6a46', (g) => { g.scale(1.8, 1.7, 2.2); g.translate(0, 4.3, 5.2); });
    add(new THREE.CylinderGeometry(0.95, 1.5, 1.6, 8, 1, true), '#e8e2d2', (g) => { g.translate(0, 3.2, 4.2); g.rotateX(0.4); });
    add(new THREE.BoxGeometry(1.5, 0.55, 2.4), '#d8b932', (g) => g.translate(0, 4.0, 7.6));
    add(new THREE.ConeGeometry(1.4, 3.0, 6), '#2b2622', (g) => { g.rotateX(-Math.PI / 2 - 0.5); g.translate(0, 2.4, -6.6); });
    this.duckGeo = mergeGeometries(parts);
    const n = 8;
    this.duckMesh = new THREE.InstancedMesh(this.duckGeo, ext({ color: '#ffffff', vertexColors: true }), n);
    // (the ducks stay on the water: culled with the pool, not drawn when it is behind the camera)
    this.duckMesh.boundingSphere = new THREE.Sphere(V(POND.x, WATER_Y + 4, POND.z), Math.max(POND.rx, POND.rz) * 1.2);
    this.group.add(this.duckMesh);
    this.ducks = Array.from({ length: n }, (_, i) => ({
      p1: r.range(0, TAU), p2: r.range(0, TAU), w1: r.range(0.034, 0.058), w2: r.range(0.026, 0.044),
      ax: POND.rx * r.range(0.35, 0.68), az: POND.rz * r.range(0.4, 0.7), dab: r.range(8, 22), dabAt: r.range(2, 12), scale: r.range(0.95, 1.2),
      yaw: 0, roll: 0, lastEmit: r.range(0, 1), dabT: -1,
    }));
    this._m4 = new THREE.Matrix4(); this._q = new THREE.Quaternion(); this._e = new THREE.Euler(0, 0, 0, 'YXZ'); this._s = V();
  }

  _stepDucks(clock, dt) {
    const m4 = this._m4, q = this._q, e = this._e, s = this._s;
    this.ducks.forEach((d, i) => {
      const t = clock;
      const x = POND.x + d.ax * Math.sin(d.w1 * t + d.p1), z = POND.z + d.az * Math.sin(d.w2 * t + d.p2);
      const vx = d.ax * d.w1 * Math.cos(d.w1 * t + d.p1), vz = d.az * d.w2 * Math.cos(d.w2 * t + d.p2);
      const speed = Math.hypot(vx, vz);
      const yawT = Math.atan2(vx, vz);
      const dy = Math.atan2(Math.sin(yawT - d.yaw), Math.cos(yawT - d.yaw));
      if (d.init) d.yaw += dy * (1 - Math.exp(-Math.max(dt, 1e-3) * 2.5));
      else { d.yaw = yawT; d.init = true; }
      d.roll += (clamp(-dy * 1.4, -0.25, 0.25) - d.roll) * (1 - Math.exp(-Math.max(dt, 1e-3) * 3));
      // now and then tip up to dabble
      if (d.dabT < 0 && t > d.dabAt) { d.dabT = 0; d.dabAt = t + d.dab; }
      let pitch = 0;
      if (d.dabT >= 0) {
        d.dabT += dt;
        const u = d.dabT / 2.4;
        pitch = Math.sin(Math.PI * clamp(u)) * 1.05;
        if (u > 0.12 && !d.s1) { d.s1 = true; this.onDabble?.(x, z, 1); }
        if (u > 0.86 && !d.s2) { d.s2 = true; this.onDabble?.(x, z, 0.6); }
        if (u >= 1) { d.dabT = -1; d.s1 = d.s2 = false; }
      }
      d.x = x; d.z = z; d.speed = speed;
      const bob = Math.sin(t * 1.7 + i * 2.3) * 0.28;
      q.setFromEuler(e.set(pitch, d.yaw, d.roll));
      m4.compose(V(x, WATER_Y + 0.4 + bob - pitch * 1.4, z), q, s.setScalar(d.scale * 1.15));
      this.duckMesh.setMatrixAt(i, m4);
      // a wake behind it
      if (clock - d.lastEmit > 0.9) {
        d.lastEmit = clock;
        this.emit = (this.emit + 1) % 24;
        this.fx.uEm.value[this.emit].set(x - Math.sin(d.yaw) * 5, z - Math.cos(d.yaw) * 5, clock, clamp(0.25 + speed * 0.07 + pitch * 0.5, 0.2, 0.8));
      }
    });
    this.duckMesh.instanceMatrix.needsUpdate = true;
  }

  // ---- per frame ----------------------------------------------------------------------------------
  // a ring on the water where something touched it: kind 'bee' (APX-9's) or 'misc' (a dipping dragonfly, a koi rising)
  ring(kind, x, z, clock, amp) {
    const c = this.cursor, lo = kind === 'bee' ? 24 : 36, n = kind === 'bee' ? 12 : 4;
    c[kind] = lo + ((c[kind] - lo + 1) % n);
    this.fx.uEm.value[c[kind]].set(x, z, clock, amp);
  }

  // bee: { pos, speed, flying }
  update(clock, dt, phases, bee = null) {
    const fx = this.fx;
    fx.uFT.value = clock;
    fx.uFSun.value = (1 - phases.night * 0.85) * (1 - WEATHER.uRain.value * 0.6);
    fx.uFLamp.value = Math.max(phases.lamps, phases.night) * 0.9;
    // ice: the water goes dull and hard, the ducks and the lilies are gone
    const ice = WEATHER.uCover.value;
    this.waterMat.roughness = 0.04 + 0.5 * Math.min(1, ice * 1.6);
    this.duckMesh.visible = ice < 0.35;
    for (const o of this.group.children) if (o.userData.pads) o.visible = ice < 0.5;
    this.iceOn = ice >= 0.5;
    // mist: in fog, at first light, and a little after rain; brighter by day, a faint glow by night
    const amt = Math.max(WEATHER.uFog.value, 0.75 * (phases.dawn ?? 0), 0.25 * WEATHER.uRain.value) * (1 - ice);
    this.mistU.uT.value = clock;
    this.mistU.uAmt.value = amt;
    this.mistU.uColor.value.setRGB(0.78, 0.8, 0.8).multiplyScalar(0.15 + 0.85 * (1 - phases.night));
    this.mist.visible = amt > 0.06;
    this._stepDucks(clock, dt);
    this._stepKoi(clock, dt, phases, bee);
    // the leaves are stepped only while the pool is in the frame (last frame's test), catching up with the time it was out of it
    this._leafDt += dt;
    if (this.inView || this._leafDt > 20) { this._stepLeaves(this._leafDt, ice); this._leafDt = 0; }
    // a wake where APX-9 flies low over the water (as over the fountain's)
    if (bee && bee.pos) {
      const h = bee.pos.y - WATER_Y;
      if (h < 40 && h > -2 && clock - this.lastBee > 0.2 && ice < 0.3 && inPond(bee.pos.x, bee.pos.z, 1.0)) {
        const amp = smooth(clamp((40 - h) / 31)) * Math.min(1, 0.3 + (bee.speed || 0) / 22);
        if (amp > 0.06) { this.lastBee = clock; this.ring('bee', bee.pos.x, bee.pos.z, clock, amp * 0.9); }
      }
    }
  }

  // ---- mist -------------------------------------------------------------------------------------
  // wisps lifting off the water at dawn and in fog: big soft additive sprites low over the pool, each drifting on the breeze and
  // swelling and thinning in its own time (worked out in the vertex shader; sized from the target being drawn)
  _mist(quality) {
    const r = this.rng, n = quality.tier === 'low' ? 14 : quality.tier === 'med' || quality.tier === 'medium' ? 24 : 36;
    const home = new Float32Array(n * 4), par = new Float32Array(n * 4);
    for (let i = 0; i < n; i++) {
      const a = r.range(0, TAU), k = Math.sqrt(r.float()) * 1.05;
      home.set([POND.x + Math.cos(a) * POND.rx * k, WATER_Y + r.range(5, 16), POND.z + Math.sin(a) * POND.rz * k, r.range(14, 34)], i * 4);
      par.set([r.range(0, TAU), r.range(0.5, 1.2), r.range(70, 150), r.float()], i * 4);
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(n * 3), 3));
    g.setAttribute('aHome', new THREE.BufferAttribute(home, 4));
    g.setAttribute('aP', new THREE.BufferAttribute(par, 4));
    this.mistU = { uT: { value: 0 }, uAmt: { value: 0 }, uRes: { value: 720 }, uColor: { value: new THREE.Color(0.8, 0.82, 0.82) } };
    const m = new THREE.ShaderMaterial({
      uniforms: this.mistU, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, fog: false,
      vertexShader: `
        attribute vec4 aHome, aP; uniform float uT, uAmt, uRes; varying float vA;
        void main() {
          float t = uT * aP.y * 0.12;
          vec3 p = aHome.xyz + vec3( sin( t * 3.0 + aP.x ) * aHome.w + t * 40.0 * 0.0, sin( t * 5.0 + aP.x * 2.0 ) * 3.0, cos( t * 2.3 + aP.x * 1.4 ) * aHome.w );
          vec4 mv = modelViewMatrix * vec4( p, 1.0 );
          float d = -mv.z;
          float swell = 0.6 + 0.4 * sin( uT * 0.21 * aP.y + aP.x * 5.0 );
          float px = aP.z * ( 0.8 + 0.4 * swell ) * uRes * 0.5 * projectionMatrix[ 1 ][ 1 ] / max( d, 1.0 );
          gl_PointSize = clamp( px, 2.0, 260.0 * uRes / 720.0 );
          vA = uAmt * swell * smoothstep( 8.0, 70.0, d );
          gl_Position = projectionMatrix * mv;
        }`,
      fragmentShader: `
        uniform vec3 uColor; varying float vA;
        void main() {
          float r = length( gl_PointCoord - 0.5 ) * 2.0;
          float a = pow( max( 1.0 - r, 0.0 ), 2.0 );
          gl_FragColor = vec4( uColor * a * vA * 0.2, 1.0 );
        }`,
    });
    g.boundingSphere = new THREE.Sphere(V(POND.x, WATER_Y + 10, POND.z), Math.max(POND.rx, POND.rz) * 1.55); // (wisps drift over the pool and a little beyond: culled with it)
    this.mist = new THREE.Points(g, m);
    this.mist.renderOrder = 3;
    this.mist.visible = false;
    this.mist.layers.enable(1);
    this.mist.onBeforeRender = (renderer) => { const rt = renderer.getRenderTarget(); this.mistU.uRes.value = rt ? rt.height : renderer.domElement.height; };
    this.group.add(this.mist);
  }

  // ---- leaves -----------------------------------------------------------------------------------
  // autumn leaves on the water: each comes in over the upwind margin and drifts across the pool on the breeze, turning slowly, and goes out over
  // the downwind one (an instanced mesh, culled with the pool; a few vectors a frame)
  _leaves(ext, quality) {
    const r = this.rng, n = quality.tier === 'low' ? 10 : quality.tier === 'med' || quality.tier === 'medium' ? 16 : 24;
    // a leaf: a pointed ellipse with a short stalk, flat on the water
    const sh = new THREE.Shape();
    sh.moveTo(0, -0.62); sh.quadraticCurveTo(0.42, -0.18, 0.0, 0.62); sh.quadraticCurveTo(-0.42, -0.18, 0, -0.62);
    const geo = new THREE.ShapeGeometry(sh, 6); geo.rotateX(-Math.PI / 2);
    const mesh = new THREE.InstancedMesh(geo, ext({ color: '#ffffff', side: THREE.DoubleSide }), n);
    mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    mesh.boundingSphere = new THREE.Sphere(V(POND.x, WATER_Y, POND.z), Math.max(POND.rx, POND.rz) * 1.2);
    const col = new THREE.Color();
    const PAL = [[0.1, 0.8, 0.5], [0.07, 0.85, 0.46], [0.13, 0.75, 0.5], [0.02, 0.7, 0.4], [0.16, 0.5, 0.34]];
    this.leaves = Array.from({ length: n }, (_, i) => {
      const p = PAL[Math.floor(r.range(0, PAL.length))];
      mesh.setColorAt(i, col.setHSL(p[0] + r.range(-0.02, 0.02), p[1], p[2] * r.range(0.85, 1.15)));
      return { x: 0, z: 0, rot: r.range(0, TAU), spin: r.range(-0.12, 0.12), speed: r.range(5, 11), size: r.range(8, 13), wob: r.range(0, TAU), run: 0 };
    });
    mesh.userData.pads = true; // (on the water's surface: not in the mirror, like the pads)
    this.leafMesh = mesh;
    this._m4l = new THREE.Matrix4(); this._ql = new THREE.Quaternion(); this._vl = V(); this._sl = V(); this._Y = V(0, 1, 0);
    this.leaves.forEach((l) => this._spawnLeaf(l, true));
    this.group.add(mesh);
  }

  // a leaf comes in over the upwind margin (at the start, anywhere along its way across)
  _spawnLeaf(l, scatter = false) {
    const r = this.rng, d = WIND.dir, dx = d.x, dz = d.y;
    const lat = r.range(-0.8, 0.8) * POND.rx, sx = -dz, sz = dx; // (sideways)
    let x = POND.x + sx * lat - dx * 900, z = POND.z + sz * lat - dz * 900, steps = 0;
    while (!inPond(x, z, 0.98) && steps++ < 260) { x += dx * 7; z += dz * 7; }
    if (scatter) { const run = r.range(0, 700); x += dx * run; z += dz * run; }
    l.x = x; l.z = z; l.run = scatter ? 40 : 0;
  }

  _stepLeaves(dt, ice) {
    const mesh = this.leafMesh;
    mesh.visible = ice < 0.5;
    if (!mesh.visible) return;
    const d = WIND.dir, dx = d.x, dz = d.y, k = Math.min(dt, 25), t = this.fx.uFT.value;
    const gustK = 0.75 + 0.5 * (WEATHER.uRain.value > 0.3 ? 1.3 : 1);
    for (let i = 0; i < this.leaves.length; i++) {
      const l = this.leaves[i], sp = l.speed * gustK * k;
      l.x += dx * sp + Math.cos(t * 0.5 + l.wob) * 0.9 * k; l.z += dz * sp + Math.sin(t * 0.43 + l.wob * 1.3) * 0.9 * k;
      l.rot += l.spin * k; l.run += sp;
      if (!inPond(l.x, l.z, 1.02)) this._spawnLeaf(l);
      const s = l.size * Math.min(1, l.run / 30);
      this._m4l.compose(this._vl.set(l.x, WATER_Y + 0.45 + Math.sin(t * 1.3 + l.wob) * 0.12, l.z), this._ql.setFromAxisAngle(this._Y, l.rot), this._sl.set(s, s, s));
      mesh.setMatrixAt(i, this._m4l);
    }
    mesh.instanceMatrix.needsUpdate = true;
  }

  // ---- koi --------------------------------------------------------------------------------------
  _koi(quality) {
    const r = this.rng;
    const n = quality.tier === 'low' ? 3 : quality.tier === 'med' || quality.tier === 'medium' ? 5 : 7;
    this.fish = Array.from({ length: n }, (_, i) => ({
      p1: r.range(0, TAU), p2: r.range(0, TAU), w1: r.range(0.11, 0.2), w2: r.range(0.085, 0.15),
      ax: POND.rx * r.range(0.3, 0.6), az: POND.rz * r.range(0.3, 0.68), size: r.range(21, 30), pal: i % 4, seed: r.range(0, 20),
      x: POND.x, z: POND.z, h: 0, riseAt: r.range(14, 50), ox: 0, oz: 0, cool: 0,
    }));
    this.uFish = { value: this.fish.map(() => new THREE.Vector4(POND.x, POND.z, 0, 24)) };
    this.uFishC = { value: this.fish.map((f) => new THREE.Vector4(f.pal, f.seed, 0, 0)) };
    this.uFishVis = { value: 1 };
  }

  _stepKoi(clock, dt, phases, bee = null) {
    const t = clock, k = Math.max(dt, 1e-3);
    this.uFishVis.value = 1 - WEATHER.uRain.value * 0.35;
    const low = bee && bee.pos && bee.pos.y - WATER_Y < 45 && bee.pos.y - WATER_Y > -2 && WEATHER.uCover.value < 0.3;
    this.fish.forEach((f, i) => {
      let x = POND.x + f.ax * Math.sin(f.w1 * t + f.p1), z = POND.z + f.az * Math.sin(f.w2 * t + f.p2);
      const vx = f.ax * f.w1 * Math.cos(f.w1 * t + f.p1), vz = f.az * f.w2 * Math.cos(f.w2 * t + f.p2);
      let hT = Math.atan2(vz, vx);
      // shy of APX-9: when it skims low overhead the fish bolts directly away from it, fast at first, and settles back to its loop over a few seconds
      if (low && f.init) {
        const dx = f.x - bee.pos.x, dz = f.z - bee.pos.z, d = Math.hypot(dx, dz) || 1;
        if (d < 80) {
          const push = (1 - d / 80) * 330 * k * (0.45 + Math.min(1, (bee.speed || 0) / 25));
          f.ox += (dx / d) * push; f.oz += (dz / d) * push;
          if (t > f.cool) { f.cool = t + 5; this.ring('misc', f.x, f.z, t, 0.4); this.onStartle?.(f.x, f.z); }
        }
      }
      const decay = Math.exp(-k / 2.6);
      f.ox *= decay; f.oz *= decay;
      const mag = Math.hypot(f.ox, f.oz);
      if (mag > 120) { f.ox *= 120 / mag; f.oz *= 120 / mag; }
      if (mag > 0.5 && !inPond(x + f.ox, z + f.oz, 0.9)) { f.ox *= 0.6; f.oz *= 0.6; } // (never out of the water)
      x += f.ox; z += f.oz;
      // heading: the path's own, or where it is actually going while it flees
      if (f.init && mag > 4) { const mx = x - f.x, mz = z - f.z; if (mx * mx + mz * mz > 1e-4) hT = Math.atan2(mz, mx); }
      if (f.init) f.h += Math.atan2(Math.sin(hT - f.h), Math.cos(hT - f.h)) * (1 - Math.exp(-k * (mag > 4 ? 9 : 3)));
      else { f.h = hT; f.init = true; }
      f.x = x; f.z = z;
      this.uFish.value[i].set(x, z, f.h, f.size);
      // now and then one rises to the surface: a ring at its head, and a sound
      if (t > f.riseAt && WEATHER.uCover.value < 0.3) {
        f.riseAt = t + this.rng.range(24, 70);
        const hx = x + Math.cos(f.h) * f.size * 0.45, hz = z + Math.sin(f.h) * f.size * 0.45;
        this.ring('misc', hx, hz, t, 0.55);
        this.onRise?.(hx, hz);
      }
    });
  }

  // the mirror pass (once the camera is placed, before the frame is drawn)
  render(renderer, scene, camera, frustum, w, h, force = false) {
    const M = this.mirror;
    const cp = this._v.setFromMatrixPosition(camera.matrixWorld);
    const near = cp.distanceTo(this.sphere.center) < 4500;
    const visible = !this.low && this.on && cp.y > WATER_Y + 1 && near && WEATHER.uCover.value < 0.8 && (force || frustum.intersectsSphere(this.sphere));
    this.inView = frustum.intersectsSphere(this.sphere);
    M.uMirrorOn.value = visible ? 1 : 0;
    // (without the mirror the water falls back on the sky map's reflection)
    this.waterMat.envMapIntensity = (this.low || !this.on ? 1.3 : visible ? 0.12 : 1.3) * (1 - 0.7 * Math.min(1, WEATHER.uCover.value * 1.5));
    if (!visible) return;
    const rw = Math.max(16, Math.round(w * this.scale)), rh = Math.max(16, Math.round(h * this.scale));
    if (this.rt.width !== rw || this.rt.height !== rh) { this.rt.setSize(rw, rh); M.uMirrorTexel.value.set(1 / rw, 1 / rh); }
    // the camera mirrored in the water's plane (as three's Reflector does it)
    const cam = this.cam, N = V(0, 1, 0);
    const rot = this._r.extractRotation(camera.matrixWorld);
    const look = this._la.set(0, 0, -1).applyMatrix4(rot).add(cp);
    cam.position.set(cp.x, 2 * WATER_Y - cp.y, cp.z);
    cam.up.set(0, 1, 0).applyMatrix4(rot).reflect(N);
    cam.lookAt(this._t.set(look.x, 2 * WATER_Y - look.y, look.z));
    cam.near = camera.near; cam.far = camera.far;
    cam.projectionMatrix.copy(camera.projectionMatrix);
    cam.projectionMatrixInverse.copy(camera.projectionMatrixInverse);
    cam.updateMatrixWorld();
    M.uMirrorMat.value.set(0.5, 0, 0, 0.5, 0, 0.5, 0, 0.5, 0, 0, 0.5, 0.5, 0, 0, 0, 1).multiply(cam.projectionMatrix).multiply(cam.matrixWorldInverse);
    // what lies under the water is cut away by moving the camera's near plane onto the water (an oblique projection, as three's Reflector does
    // it), not by a clipping plane: a clipping plane makes every material that is drawn in both passes look its shader program up again, twice a frame
    {
      const pl = this._pl.setFromNormalAndCoplanarPoint(N, this._t.set(0, WATER_Y, 0)).applyMatrix4(cam.matrixWorldInverse);
      const c = this._clip.set(pl.normal.x, pl.normal.y, pl.normal.z, pl.constant), pm = cam.projectionMatrix.elements, q = this._q4;
      q.x = (Math.sign(c.x) + pm[8]) / pm[0];
      q.y = (Math.sign(c.y) + pm[9]) / pm[5];
      q.z = -1;
      q.w = (1 + pm[10]) / pm[14];
      c.multiplyScalar(2 / c.dot(q));
      pm[2] = c.x; pm[6] = c.y; pm[10] = c.z + 1; pm[14] = c.w;
    }
    // the branches that hold nothing the mirror shows (the whole interior and its creatures, the planting, the rain) are left out of this pass, so
    // three does not walk them (every light stays in: the lighting, and with it every program, is the same as in the main pass)
    if (!this._hide) this._hide = this._mirrorSkips(scene);
    const hide = this._hide, was = this._was || (this._was = []);
    for (let i = 0; i < hide.length; i++) { was[i] = hide[i].visible; hide[i].visible = false; }
    // draw the outdoors above the water (no shadow maps: they are current; the matrices are last frame's, the main pass renders this one's)
    const sm = renderer.shadowMap, au = sm.autoUpdate, nu = sm.needsUpdate, mwa = scene.matrixWorldAutoUpdate;
    sm.autoUpdate = false; sm.needsUpdate = false;
    if (++this._frames > 3) scene.matrixWorldAutoUpdate = false; // (the first few passes bring everything's matrices up to date)
    const prevRT = renderer.getRenderTarget();
    renderer.setRenderTarget(this.rt);
    renderer.clear();
    renderer.render(scene, cam);
    renderer.setRenderTarget(prevRT);
    scene.matrixWorldAutoUpdate = mwa;
    sm.autoUpdate = au; sm.needsUpdate = nu;
    for (let i = 0; i < hide.length; i++) hide[i].visible = was[i];
  }

  // The bee in the water: its rig (and its lights' glows, which hang off it) are drawn into the mirror pass while the bee can fly (explore on), so
  // the pool shows it as it skims. Lights keep layer 1 always (the mirror pass lights the land as the main pass does); the skip list is rebuilt.
  mirrorBee(group, on) {
    group.traverse((o) => { if (o.isLight) o.layers.enable(1); else if (on) o.layers.enable(1); else o.layers.disable(1); });
    this._hide = null;
  }

  // the branches of the scene with nothing on layer 1 (the mirror's) anywhere under them: the shallowest nodes to hide
  _mirrorSkips(scene) {
    const out = [];
    const walk = (o) => {
      let any = (o.layers.mask & 2) !== 0;
      const none = [];
      for (const c of o.children) { if (walk(c)) any = true; else none.push(c); }
      if (any) out.push(...none);
      return any;
    };
    walk(scene);
    return out;
  }
}

